import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { safeGetJson, safeSetJson } from '../utils/safeStorage';

// Last non-empty facet terms per field, MODULE-scoped on purpose: the sale
// page renders a spinner INSTEAD of <Facets> while a search is in flight, so
// the component remounts on every search and instance state (useRef) would
// be empty exactly when a zero-result response needs the remembered terms.
// Session-lived, keyed by field name.
const lastKnownTerms = {};

/** Test-only: reset the module-level memory between test cases. */
export const __clearLastKnownTerms = () => {
    Object.keys(lastKnownTerms).forEach((key) => delete lastKnownTerms[key]);
};

/**
 * Facets are presented as a horizontal TAB STRIP with a single
 * collapsible panel below. Click a tab to open its facet; click the
 * active tab again to close the panel. State is persisted to
 * localStorage (key `facet_active_tab`) — best-effort via safeStorage:
 * a full quota once threw QuotaExceededError out of this effect and
 * unmounted the whole catalog in production.
 */
const Facets = ({ results, activeFacets, toggleFacetValue, inSale = false, openAll = false, resetTrigger = 0 }) => {
    const { t } = useTranslation();

    const STORAGE_KEY = 'facet_active_tab';

    const loadActiveTab = useCallback(() => {
        if (openAll) return null; // start closed when openAll just toggled
        return safeGetJson(STORAGE_KEY, null);
    }, [openAll]);

    const [activeTab, setActiveTab] = useState(loadActiveTab);

    useEffect(() => {
        safeSetJson(STORAGE_KEY, activeTab);
    }, [activeTab]);

    // Reset the open tab when openAll changes or a reset is triggered.
    useEffect(() => { setActiveTab(loadActiveTab()); }, [loadActiveTab]);
    useEffect(() => {
        if (resetTrigger > 0) setActiveTab(loadActiveTab());
    }, [resetTrigger, loadActiveTab]);

    if (!results?.facets) return null;

    const facetFields = [
        'field_collectible_type',
        'field_sub_symbol',
        'field_symbols',
        'field_category',
        'field_catalogue_part',
        'field_sale',
        'field_destinations',
        'field_item_type',
        'field_year',
        'field_grade',
    ];

    // Display label for a facet term. The server label wins for taxonomy
    // facets (translated names), but fields without a vocabulary echo the raw
    // Search-API filter value incl. its quotes (e.g. `"single"`), so:
    //  - translated fields (field_item_type) are mapped locally and IGNORE
    //    the server label;
    //  - everything else uses the server label with the quotes stripped.
    const getFacetLabel = (fieldName, value, serverLabel) => {
        switch (fieldName) {
            case 'field_item_type':
                return value === 'single'
                    ? t('sale.facetItemTypeSingle', 'Single Items')
                    : t('sale.facetItemTypeCollections', 'Collections');
            default: {
                const cleaned = (serverLabel || '').replace(/^"+|"+$/g, '').trim();
                return cleaned || value;
            }
        }
    };

    // Field labels come from the translation catalog; unknown fields fall back
    // to the API-provided vocabulary title, then a humanized field name.
    const getFieldLabel = (fieldName) =>
        t(`sale.facets.${fieldName}`, {
            defaultValue:
                results.facets_titles?.[fieldName]?.title ||
                fieldName.replace('field_', '').replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()),
        });

    const getFacetUrl = (termId, fieldName, remove = false) => {
        const searchParams = new URLSearchParams(window.location.search);
        const currentParams = {};

        for (const [key, value] of searchParams.entries()) {
            const matches = key.match(/filter\[([^\]]+)\]\[([^\]]+)\]/);
            if (matches) {
                const [, field, param] = matches;
                if (!currentParams.filter) currentParams.filter = {};
                if (!currentParams.filter[field]) currentParams.filter[field] = {};
                currentParams.filter[field][param] = value;
            } else {
                currentParams[key] = value;
            }
        }

        const params = JSON.parse(JSON.stringify(currentParams));

        if (remove) {
            if (params.filter && params.filter[fieldName] && params.filter[fieldName].values) {
                const stringArray = params.filter[fieldName].values.split(',');
                const index = stringArray.indexOf(termId);
                if (index !== -1) stringArray.splice(index, 1);
                if (stringArray.length === 0) {
                    // Removing the last term: drop the whole filter instead of
                    // leaving an empty values= plus a stale operator=IN.
                    delete params.filter[fieldName];
                } else {
                    params.filter[fieldName].values = stringArray.join(',');
                }
            }
        } else {
            if (!params.filter) params.filter = {};
            if (!params.filter[fieldName]) params.filter[fieldName] = {};

            let otherValues = '';
            if (params.filter[fieldName].values) otherValues = `,${params.filter[fieldName].values}`;
            params.filter[fieldName].values = termId + otherValues;
            params.filter[fieldName].operator = 'IN';
        }

        const urlParams = new URLSearchParams();
        Object.entries(params).forEach(([key, value]) => {
            if (key === 'filter') {
                Object.entries(value).forEach(([fieldName_, fieldParams]) => {
                    Object.entries(fieldParams).forEach(([paramName, paramValue]) => {
                        urlParams.append(`filter[${fieldName_}][${paramName}]`, paramValue);
                    });
                });
            } else {
                urlParams.append(key, value);
            }
        });

        const baseUrl = window.location.href.split('?')[0];
        return `${baseUrl}?${urlParams.toString()}`;
    };

    const isTermActive = (fieldName, value) => activeFacets[fieldName]?.includes(value);

    const handleFacetClick = (fieldName, term) => {
        const value = term.filter.replace(/"/g, '');
        toggleFacetValue(fieldName, { tid: value, count: term.count });
    };

    // A zero-result search (e.g. an active facet + a lot-number filter that
    // matches nothing) comes back with EMPTY facet term lists — without a
    // guard the whole block disappears and the active facet can no longer
    // be DESELECTED. Remember each field's last non-empty terms (module
    // scope — see lastKnownTerms above) so the tabs stay operable across a
    // zero-result response; idempotent on re-render.
    facetFields.forEach((fieldName) => {
        const terms = results.facets[fieldName];
        if (terms?.length) lastKnownTerms[fieldName] = terms;
    });

    /**
     * Terms to render for a field. Tiered so an active selection is ALWAYS
     * deselectable:
     *  1. the current response's terms;
     *  2. zero-result response + active selection → the field's last known
     *     terms (counts may be momentarily stale — irrelevant, there are no
     *     results to count);
     *  3. direct URL load straight into a zero-result search (no last known
     *     terms) → synthesize a row per selected tid so it can be unchecked.
     */
    const getTerms = (fieldName) => {
        const terms = results.facets[fieldName];
        if (terms?.length) return terms;
        const selected = activeFacets[fieldName] || [];
        if (selected.length === 0) return terms;
        if (lastKnownTerms[fieldName]?.length) {
            return lastKnownTerms[fieldName];
        }
        return selected.map((tid) => ({
            filter: `"${tid}"`,
            tid: String(tid),
            count: 0,
            label: `#${tid}`,
            parent: '0',
        }));
    };

    // Build the list of visible facet fields (with non-empty terms).
    const visibleFields = facetFields.filter((fieldName) => {
        if (fieldName === 'field_sale' && inSale) return false;
        return !!getTerms(fieldName)?.length;
    });

    if (visibleFields.length === 0) return null;

    // Hierarchical facets (Categories, Catalogue Part, Destinations, …) come
    // back from the API as a flat list mixing roots, subcategories and
    // leaves. On first open we only want the top level; once the user picks
    // a term we drill down to its children. Flat facets (no non-zero
    // parents) are untouched — every term has parent "0" so they all stay
    // visible.
    //
    // "Top level" = parent "0" OR a parent that is NOT itself in the list:
    // Solr only returns terms with direct hits, so a child whose parent
    // never got a hit (common for Destinations — countries under region
    // terms that no lot carries directly) is an orphan and must surface at
    // the top, otherwise the facet renders empty.
    const filterHierarchicalTerms = (fieldName, terms) => {
        if (!terms?.length) return terms;
        const hasHierarchy = terms.some((t) => String(t.parent) !== '0');
        if (!hasHierarchy) return terms;

        const presentTids = new Set(terms.map((t) => String(t.tid)));
        const selected = activeFacets[fieldName] || [];
        if (selected.length === 0) {
            return terms.filter(
                (t) => String(t.parent) === '0' || !presentTids.has(String(t.parent)),
            );
        }
        // Drill-down view: the SELECTED terms themselves stay visible
        // (checked, so they can be DESELECTED — previously only the children
        // rendered and the chosen parent vanished from the UI) together with
        // their children. A selected leaf with no children simply shows
        // itself. Selected tids the response no longer returns get a
        // synthesized row so a selection can never become un-removable.
        const selectedSet = new Set(selected.map(String));
        const visible = terms.filter(
            (t) => selectedSet.has(String(t.tid)) || selectedSet.has(String(t.parent)),
        );
        const presentSelected = new Set(
            visible.filter((t) => selectedSet.has(String(t.tid))).map((t) => String(t.tid)),
        );
        const synthesized = selected
            .filter((tid) => !presentSelected.has(String(tid)))
            .map((tid) => ({
                filter: `"${tid}"`,
                tid: String(tid),
                count: 0,
                label: `#${tid}`,
                parent: '0',
            }));
        return [...synthesized, ...visible];
    };

    // The persisted activeTab may point at a field that is no longer
    // visible (e.g. its selection was just cleared during a zero-result
    // search, leaving it with no terms at all) — rendering it would crash
    // on undefined terms. Fall back to the closed-panel hint instead.
    const activeFieldData = activeTab && visibleFields.includes(activeTab)
        ? {
            name: activeTab,
            terms: filterHierarchicalTerms(activeTab, getTerms(activeTab)) || [],
        }
        : null;

    return (
        <div className="facets-wrapper">
            {/* Tab strip — one tab per facet field. Click toggles open.
                When a tab is active, a Close button at the right closes
                the panel without changing the active selection. */}
            <div className="facet-tabs" role="tablist">
                {visibleFields.map((fieldName) => {
                    const isActive = activeTab === fieldName;
                    const activeCount = activeFacets[fieldName]?.length || 0;
                    return (
                        <button
                            key={fieldName}
                            type="button"
                            role="tab"
                            aria-selected={isActive}
                            className={`facet-tab${isActive ? ' is-active' : ''}${activeCount > 0 ? ' has-filters' : ''}`}
                            onClick={() => setActiveTab(isActive ? null : fieldName)}
                        >
                            <span className="facet-tab__label">{getFieldLabel(fieldName)}</span>
                            {activeCount > 0 && (
                                <span className="facet-tab__count">{activeCount}</span>
                            )}
                            <svg
                                className="facet-tab__chevron"
                                width="12"
                                height="12"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                strokeWidth="2.5"
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                aria-hidden="true"
                            >
                                <polyline points="6 9 12 15 18 9" />
                            </svg>
                        </button>
                    );
                })}

                {activeTab && (
                    <button
                        type="button"
                        className="facet-tabs__close"
                        onClick={() => setActiveTab(null)}
                        aria-label={t('sale.closeFacetPanel', { defaultValue: 'Close filter panel' })}
                        title={t('sale.closeFacetPanel', { defaultValue: 'Close filter panel' })}
                    >
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                            <line x1="18" y1="6" x2="6" y2="18" />
                            <line x1="6" y1="6" x2="18" y2="18" />
                        </svg>
                        {/* Visible label — an icon-only 32px box read as "an
                            empty box" to users (HK feedback, punch list #13). */}
                        <span className="facet-tabs__close-label">
                            {t('sale.close', { defaultValue: 'Close' })}
                        </span>
                    </button>
                )}
            </div>

            {/* Panel — either the active facet's items or a small
                instructional hint when no tab is selected. */}
            {activeFieldData ? (
                <div className="facet-panel" role="tabpanel">
                    {/* data-facet enables per-facet column overrides in CSS:
                        .facet-grid[data-facet="field_symbols"] { --facet-columns-desktop: 3; } */}
                    <div className="facet-grid" data-facet={activeFieldData.name}>
                        {activeFieldData.terms.map((term) => {
                            const value = term.filter.replace(/"/g, '');
                            const active = isTermActive(activeFieldData.name, value);
                            const label = getFacetLabel(activeFieldData.name, value, term.label);
                            const facetUrl = getFacetUrl(value, activeFieldData.name, active);

                            return (
                                <a
                                    key={term.filter}
                                    href={facetUrl}
                                    onClick={(e) => {
                                        e.preventDefault();
                                        handleFacetClick(activeFieldData.name, term);
                                    }}
                                    className={`facet-link${active ? ' facet-link--active' : ''}`}
                                    title={active ? t('sale.removeFilter') : t('sale.applyFilter')}
                                >
                                    <span className="facet-link__label">
                                        {active && '✓ '}
                                        {term.font_code != null && term.font_code !== '' && (
                                            <span className="aukphila facet-link__symbol" aria-hidden="true">
                                                {term.font_code}
                                            </span>
                                        )}
                                        {label}
                                        <span className="facet-link__count">{term.count}</span>
                                    </span>
                                </a>
                            );
                        })}
                    </div>
                </div>
            ) : (
                <p className="facet-empty">
                    {t('sale.facetEmptyHint', { defaultValue: 'Select a filter category above to narrow your results.' })}
                </p>
            )}
        </div>
    );
};

export default Facets;
