/**
 * Data-source provenance log for the `?debug=1` panel.
 *
 * DataCache records one entry per resolved fetch: which endpoint, and which
 * layer served it —
 *   'memory'        in-memory cache of this page load
 *   'localStorage'  persisted client cache (dc:*)
 *   'network'       a real request; the entry then also carries the HTTP
 *                   status, the edge/proxy cache headers (CF-Cache-Status /
 *                   Age / X-Cache — readable cross-origin because the
 *                   backoffice exposes them) and the backend's own `_debug`
 *                   block (items-json: Drupal-cache hit/miss).
 *
 * Module-scoped ring buffer + tiny pub/sub so the panel re-renders as
 * entries arrive. Recording is a no-op unless ?debug=1 is active, so the
 * production hot path stays untouched.
 */
import { isDebugRequested } from './debugParam';

const MAX_ENTRIES = 50;
const entries = [];
const listeners = new Set();

export function recordDataSource(entry) {
  if (!isDebugRequested()) return;
  entries.push({ at: Date.now(), ...entry });
  if (entries.length > MAX_ENTRIES) entries.shift();
  listeners.forEach((listener) => listener(entries));
}

/** Pull the cache-related response headers the panel displays. */
export function cacheHeadersOf(response) {
  const pick = (name) => {
    try {
      return response?.headers?.get(name) || null;
    } catch {
      return null;
    }
  };
  return {
    cfCacheStatus: pick('cf-cache-status'),
    age: pick('age'),
    xCache: pick('x-cache'),
  };
}

export function getDataSourceLog() {
  return entries;
}

export function subscribeDataSources(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Test-only: reset the module state between test cases. */
export function __clearDataSourceLog() {
  entries.length = 0;
  listeners.clear();
}
