import fetchData from '../utils/Util';

/**
 * Process payment through the /payment endpoint
 * @param {Object} params - Payment parameters
 * @param {Object} params.config - Config context with userData and siteData
 * @param {string} params.paymentMethodId - Payment method ID to use
 * @param {number} params.amount - Amount to charge
 * @param {string} params.currency - Currency code
 * @param {string} params.invoiceId - Invoice ID being paid
 * @param {Object} params.invoiceData - Invoice data for context
 * @returns {Promise<Object>} - Payment response
 */
export const processPayment = async ({
  config,
  paymentMethodId,
  amount,
  currency,
  invoiceId,
  invoiceData
}) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    // Prepare payment data for the API
    const paymentData = {
      payment_method_id: paymentMethodId,
      amount: amount,
      currency: currency,
      invoice_id: invoiceId,
      invoice_data: invoiceData,
      client_uuid: config.userData.uuid
    };

    // POST to /payment endpoint
    const response = await fetchData(
      `${config.siteData.backoffice_url}/api/payment`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(paymentData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || errorData.title || 'Payment processing failed');
    }

    const responseData = await response.json();

    return {
      success: true,
      data: responseData.data || responseData,
      transactionId: responseData.data?.transaction_id || responseData.transaction_id,
      authCode: responseData.data?.auth_code || responseData.auth_code,
      amount: amount,
      currency: currency
    };

  } catch (error) {
    console.error('Error processing payment:', error);
    return {
      success: false,
      error: error.message || 'Payment processing failed',
      errorCode: error.code
    };
  }
};

