/**
 * Set up a PayPal Express Checkout transaction (step A).
 * Returns the SecureAcceptance redirect URL and the refTransId to carry back
 * to completePayPalPayment after the buyer approves at PayPal.
 * @param {Object} params - Payment parameters
 * @param {Object} params.config - Config context with userData and siteData
 * @param {number} params.amount - Amount to charge
 * @param {string} params.currency - Currency code
 * @param {string} params.invoiceId - Invoice ID being paid
 * @param {Object} params.invoiceData - Invoice data for context (must include internalId)
 * @param {string} params.returnUrl - Page to return to after PayPal (origin + pathname)
 * @returns {Promise<Object>} - { success, secureAcceptanceUrl, refTransId, error }
 */
export const setUpPayPalPayment = async ({
  config,
  amount,
  currency,
  invoiceId,
  invoiceData,
  returnUrl,
}) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    const paymentData = {
      amount: amount,
      currency: currency,
      invoice_id: invoiceId,
      invoice_data: invoiceData,
      client_uuid: config.userData.uuid,
      return_url: returnUrl,
    };

    const response = await fetchData(
      `${config.siteData.backoffice_url}/api/payment/paypal/setup`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(paymentData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || errorData.title || 'Failed to start PayPal checkout');
    }

    const responseData = await response.json();
    const result = Array.isArray(responseData.data)
      ? responseData.data[0]
      : (responseData.data || responseData);

    return {
      success: true,
      secureAcceptanceUrl: result.secureAcceptanceUrl,
      refTransId: result.refTransId,
    };

  } catch (error) {
    console.error('Error setting up PayPal payment:', error);
    return {
      success: false,
      error: error.message || 'Failed to start PayPal checkout',
    };
  }
};

/**
 * Complete a PayPal Express Checkout transaction and capture funds (step C).
 * Called after the buyer approves at PayPal and returns with a PayerID.
 * @param {Object} params - Payment parameters
 * @param {Object} params.config - Config context with userData and siteData
 * @param {string} params.refTransId - The refTransId from setUpPayPalPayment
 * @param {string} params.payerId - The PayerID returned by PayPal on redirect
 * @param {number} params.amount - Amount to capture
 * @param {string} params.currency - Currency code
 * @param {string} params.invoiceId - Invoice ID being paid
 * @param {Object} params.invoiceData - Invoice data for context (must include internalId)
 * @returns {Promise<Object>} - { success, transactionId, payerEmail, ..., error }
 */
export const completePayPalPayment = async ({
  config,
  refTransId,
  payerId,
  amount,
  currency,
  invoiceId,
  invoiceData,
}) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    const paymentData = {
      ref_trans_id: refTransId,
      payer_id: payerId,
      amount: amount,
      currency: currency,
      invoice_id: invoiceId,
      invoice_data: invoiceData,
      client_uuid: config.userData.uuid,
    };

    const response = await fetchData(
      `${config.siteData.backoffice_url}/api/payment/paypal/complete`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(paymentData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || errorData.title || 'PayPal payment failed');
    }

    const responseData = await response.json();
    const result = Array.isArray(responseData.data)
      ? responseData.data[0]
      : (responseData.data || responseData);

    return {
      success: true,
      transactionId: result.transactionId,
      authCode: result.authCode,
      payerEmail: result.payerEmail,
      payerId: result.payerId,
      amount: amount,
      currency: currency,
    };

  } catch (error) {
    console.error('Error completing PayPal payment:', error);
    return {
      success: false,
      error: error.message || 'PayPal payment failed',
    };
  }
};

