/**
 * Refund a transaction through the /payment/refund endpoint
 * @param {Object} params - Parameters
 * @param {Object} params.config - Config context with userData and siteData
 * @param {string} params.transactionId - Transaction ID to refund
 * @param {number} params.amount - Amount to refund (optional, defaults to full amount)
 * @param {string} params.reason - Reason for refund (optional)
 * @returns {Promise<Object>} - Refund response
 */
export const refundTransaction = async ({ config, transactionId, amount, reason }) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    const refundData = {
      transaction_id: transactionId,
      ...(amount && { amount }),
      ...(reason && { reason })
    };

    const response = await fetchData(
      `${config.siteData.backoffice_url}/api/payment/refund/${transactionId}`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(refundData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || errorData.title || 'Refund processing failed');
    }

    const responseData = await response.json();
    return {
      success: true,
      data: responseData.data || responseData
    };

  } catch (error) {
    console.error('Error processing refund:', error);
    return {
      success: false,
      error: error.message || 'Refund processing failed'
    };
  }
};