// Format currency for display without decimals
export const formatCurrency = (amount, currency = 'USD') => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(amount);
};

// Helper function to calculate bid summaries for a sale
export const calculateSaleBidSummary = (saleItems = [], userBids = [], itemDetails = {}) => {
  const summary = {
    itemsBidCount: 0,
    totalOpeningPrice: 0,
    totalTopBid: 0,
    itemsWonCount: 0,
    wonOpeningPrice: 0,
    totalWonAmount: 0,
  };

  Object.values(saleItems).forEach((item, index) => {
    const bid = userBids[index];
    if (bid) {
      summary.itemsBidCount++;
      const openingPrice = Math.floor(Number(item.openingPrice) || 0);
      summary.totalOpeningPrice += openingPrice;
      const bidAmount = Math.floor(Number(bid.amount) || 0);
      summary.totalTopBid += bidAmount;

      if (bid.isWinning && item.status === 'sold') {
        summary.itemsWonCount++;
        summary.wonOpeningPrice += openingPrice;
        summary.totalWonAmount += Math.floor(Number(item.currentPrice) || 0);
      }
    }
  });
  return summary;
};

// The items-json endpoint returns `opening_price` in one of two shapes:
//   * a pre-formatted string like "$1,300" / "1,300 €"
//   * an object { raw: 1300, formatted: "$1,300" }
// Coerce both into a whole-number numeric value.
const parseOpeningPrice = (op) => {
  if (op == null) return 0;
  if (typeof op === 'number') return Math.floor(op) || 0;
  if (typeof op === 'object') return Math.floor(Number(op.raw)) || 0;
  const n = parseFloat(String(op).replace(/[^\d.-]/g, ''));
  return Number.isFinite(n) ? Math.floor(n) : 0;
};

// Helper to prepare sale items data from groupedBids.
// Reads `opening_price` from itemDetails (the actual API field) —
// previous code read `startPrice`, which the items-json endpoint
// doesn't return, so the Opening Total always landed at $0.
export const prepareSaleItemsData = (groupedBids, itemDetails) => {
  return Object.values(groupedBids).map(lotData => ({
    id: lotData.item.uuid,
    openingPrice: parseOpeningPrice(itemDetails?.[lotData.item.uuid]?.opening_price),
    currentPrice: Math.floor(lotData.item.current_price) || 0,
    status: lotData.item.status
  }));
};

// Helper to prepare user bids data
export const prepareUserBidsData = (groupedBids) => {
  return Object.values(groupedBids).map(lotData => ({
    itemId: lotData.item.uuid,
    amount: Math.floor(lotData.bids[0]?.amount) || 0,
    isWinning: lotData.bids.some(bid => bid.id === lotData.item.winning_bid),
    status: lotData.item.status
  }));
};

// Component to display bid summary
export const BidSummaryDisplay = ({ summary, currency = 'USD', t }) => {
  return {
    itemsBidOn: `${summary.itemsBidCount} ${t('myBids.summary.items', { count: summary.itemsBidCount })}`,
    openingTotal: formatCurrency(summary.totalOpeningPrice, currency),
    topBidTotal: formatCurrency(summary.totalTopBid, currency),
    itemsWon: `${summary.itemsWonCount} ${t('myBids.summary.items', { count: summary.itemsWonCount })}`,
    wonOpeningTotal: formatCurrency(summary.wonOpeningPrice, currency),
    wonAmount: formatCurrency(summary.totalWonAmount, currency)
  };
};