import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';

/**
 * Portal-mounted cream popover that follows the design system.
 *
 * Hovering / focusing the wrapped trigger shows the popover anchored
 * just above the trigger (centered horizontally). The popover is
 * rendered into a portal on document.body so it escapes any
 * overflow:hidden ancestor (.rc-card, scrollable tables); the portal
 * subtree is wrapped in a .circuit-user-ui div so design-system
 * styles + CSS custom properties cascade in.
 *
 * Props:
 *   children — the trigger element(s)
 *   content  — the popover body (JSX)
 */
export const PortalTooltip = ({ children, content }) => {
  const triggerRef = useRef(null);
  const [pos, setPos] = useState(null);

  const showTooltip = useCallback(() => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    setPos({
      left: rect.left + rect.width / 2 + window.scrollX,
      top: rect.top + window.scrollY,
    });
  }, []);

  const hideTooltip = useCallback(() => setPos(null), []);

  useEffect(() => {
    if (!pos) return undefined;
    const handleScroll = () => setPos(null);
    window.addEventListener('scroll', handleScroll, true);
    return () => window.removeEventListener('scroll', handleScroll, true);
  }, [pos]);

  return (
    <span
      className="group-tooltip-wrap"
      ref={triggerRef}
      onMouseEnter={showTooltip}
      onMouseLeave={hideTooltip}
      onFocusCapture={showTooltip}
      onBlurCapture={hideTooltip}
    >
      {children}
      {pos && createPortal(
        <div className="circuit-user-ui">
          <span
            className="group-tooltip group-tooltip--portaled"
            role="tooltip"
            style={{ left: `${pos.left}px`, top: `${pos.top}px` }}
          >
            {content}
          </span>
        </div>,
        document.body
      )}
    </span>
  );
};

export default PortalTooltip;
