import React, { useContext, useEffect, useState, useCallback, useRef } from 'react';
// Remaining Chakra primitives — used either in the still-Chakra
// compare modal (TODO native) or the responsive table / mobile cards
// that we restyle via class selectors. Skeleton kept for loading.
import {
  useToast,
  Modal, ModalOverlay, ModalContent, ModalBody,
  Image, Box, Text, Flex, HStack, Checkbox,
  Link as ChakraLink,
  Table, Thead, Tbody, Tr, Th, Td,
  Card, CardBody, Show, Hide, Stack, StackDivider,
  Skeleton, SkeletonText,
  useDisclosure,
} from '@chakra-ui/react';
import { ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';
import { Search, RefreshCw, LayoutList, List, Scale, Plus } from 'lucide-react';
import fetchData from '../utils/Util';
import { useDataCache } from '../services/DataCache';
import FavoriteButton from '../components/FavoriteButton';
import ItemImageGallery from '../components/ItemImageGallery';
import { CircuitDropdown } from '../components/CircuitDropdown';
import { handleImageError } from '../utils/imageFallback';


const CompareWidget = ({ selectedItems, onCompare, t }) => {
  if (selectedItems.length === 0) return null;

  return (
    <div className="favorites-compare-widget">
      <p className="favorites-compare-widget__count">
        {selectedItems.length === 1
          ? t('myFavorites.selectMoreItems')
          : t('myFavorites.selectedItems', { count: selectedItems.length })}
      </p>
      <button
        type="button"
        className="btn-primary-action btn-primary-action--sm"
        onClick={onCompare}
        disabled={selectedItems.length < 2}
      >
        <Scale size={14} /> {t('myFavorites.compareItems')}
      </button>
      {selectedItems.length >= 4 && (
        <p className="favorites-compare-widget__hint">
          {t('myFavorites.maxItemsReached')}
        </p>
      )}
    </div>
  );
};

const CompareModal = ({ isOpen, onClose, items, t }) => {
  // Rows are filtered based on whether any item has the value.
  const rows = [
    {
      key: 'image',
      label: t('myFavorites.image'),
      always: true,
      render: (item) => (
        item.image_gallery?.images_path?.[0]?.big ? (
          <img
            src={item.image_gallery.images_path[0].big}
            onError={handleImageError}
            alt={`Lot ${item.lot_number}`}
            className="compare-table__img"
            loading="lazy"
          />
        ) : '-'
      ),
    },
    {
      key: 'lot',
      label: t('myFavorites.lot'),
      always: true,
      render: (item) => <span className="compare-table__lot">{item.lot_number}</span>,
    },
    {
      key: 'title',
      label: t('myFavorites.title'),
      has: (it) => it.show_title,
      render: (item) => item.show_title ? item.title : '-',
    },
    {
      key: 'opening',
      label: t('myFavorites.startPrice'),
      always: true,
      render: (item) => <span className="compare-table__num">{item.opening_price}</span>,
    },
    {
      key: 'estimate',
      label: t('myFavorites.estimate'),
      has: (it) => !!it.estimation,
      render: (item) => <span className="compare-table__num">{item.estimation || '-'}</span>,
    },
    {
      key: 'soldfor',
      label: t('myFavorites.soldFor'),
      has: (it) => !!it.soldfor,
      render: (item) => <span className="compare-table__num compare-table__num--sold">{item.soldfor || '-'}</span>,
    },
    {
      key: 'category',
      label: t('myFavorites.category'),
      has: (it) => !!it.categories,
      render: (item) => item.categories || '-',
    },
    {
      key: 'catalog',
      label: t('myFavorites.catalogInfo'),
      has: (it) => !!it.item_taxonomy?.catalogue_name_and_number?.rendered,
      render: (item) => item.item_taxonomy?.catalogue_name_and_number?.rendered ? (
        <span dangerouslySetInnerHTML={{ __html: item.item_taxonomy.catalogue_name_and_number.rendered }} />
      ) : '-',
    },
    {
      key: 'symbols',
      label: t('myFavorites.symbols'),
      has: (it) => !!it.item_taxonomy?.symbols?.rendered,
      render: (item) => (
        <span className={`catalog-symbols ${item.item_taxonomy?.symbols?.class_wrapper || 'aukphila'}`}>
          {item.item_taxonomy?.symbols?.rendered || '-'}
        </span>
      ),
    },
    {
      key: 'description',
      label: t('myFavorites.description'),
      has: (it) => !!(it.body || it.footer),
      render: (item) => (
        <span
          className="compare-table__body"
          dangerouslySetInnerHTML={{
            __html: (item.body || '-') + (item.footer ? ' ' + item.footer : ''),
          }}
        />
      ),
    },
    {
      key: 'provenance',
      label: t('myFavorites.provenance'),
      has: (it) => !!it.provenance,
      render: (item) => (
        <span dangerouslySetInnerHTML={{ __html: item.provenance || '-' }} />
      ),
    },
    {
      key: 'sale',
      label: t('myFavorites.saleTitle'),
      has: (it) => !!it.sale_title,
      render: (item) => item.sale_title || '-',
    },
  ];

  const visibleRows = rows.filter((r) => r.always || items.some(r.has));

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="6xl">
      <ModalOverlay bg="rgba(28, 22, 14, 0.55)" backdropFilter="blur(4px)" />
      <ModalContent
        maxW="95vw"
        bg="transparent"
        boxShadow="none"
        className="favorites-compare-modal"
      >
        <ModalBody p={0}>
          <div className="circuit-user-ui">
            <div className="compare-modal">
              <header className="compare-modal__head">
                <h2 className="compare-modal__title">
                  {t('myFavorites.CompareItems')}
                </h2>
                <button
                  type="button"
                  className="compare-modal__close"
                  onClick={onClose}
                  aria-label={t('myFavorites.close', { defaultValue: 'Close' })}
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                    <line x1="18" y1="6" x2="6" y2="18" />
                    <line x1="6" y1="6" x2="18" y2="18" />
                  </svg>
                </button>
              </header>
              <div className="compare-modal__body">
                <div className="compare-table-wrap">
                  <table className="compare-table">
                    <colgroup>
                      <col className="compare-table__label-col" />
                      {items.map((item) => (
                        <col
                          key={item.id}
                          className="compare-table__item-col"
                          style={{ width: `${100 / items.length}%` }}
                        />
                      ))}
                    </colgroup>
                    <tbody>
                      {visibleRows.map((row) => (
                        <tr key={row.key} className={`compare-table__row compare-table__row--${row.key}`}>
                          <th scope="row" className="compare-table__label">
                            <span className="compare-table__label-pill">{row.label}</span>
                          </th>
                          {items.map((item) => (
                            <td key={item.id} className="compare-table__cell">
                              {row.render(item)}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </ModalBody>
      </ModalContent>
    </Modal>
  );
};

// Summary-view lot body. Renders directly under the lot title, clamped
// to a single line. The expand toggle only appears when the text is
// actually cut off; opening it un-clamps the text in place so the
// trailing ellipsis flows into the full body. Each instance keeps its
// own open state, so any number of lots can be expanded at once.
const LotDescription = ({ html, t }) => {
  const textRef = useRef(null);
  const [expanded, setExpanded] = useState(false);
  const [truncated, setTruncated] = useState(false);

  useEffect(() => {
    const el = textRef.current;
    if (!el) return;

    const measure = () => {
      // Only meaningful while clamped; once expanded the toggle stays
      // visible via the `|| expanded` guard below.
      if (!expanded) {
        setTruncated(el.scrollHeight > el.clientHeight + 1);
      }
    };

    measure();

    let ro;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(measure);
      ro.observe(el);
    }
    return () => ro && ro.disconnect();
  }, [html, expanded]);

  return (
    <div className="lot-desc">
      <div
        ref={textRef}
        className={`lot-desc__text${expanded ? ' is-expanded' : ''}`}
        dangerouslySetInnerHTML={{ __html: html }}
      />
      {(truncated || expanded) && (
        <button
          type="button"
          className={`fav-desc-toggle${expanded ? ' is-open' : ''}`}
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-label={t(expanded ? 'myFavorites.hideDescription' : 'myFavorites.showDescription')}
          title={t(expanded ? 'myFavorites.hideDescription' : 'myFavorites.showDescription')}
        >
          <Plus size={15} />
        </button>
      )}
    </div>
  );
};

const MyFavorites = ({ language }) => {
  const {
    t,
    i18n
  } = useTranslation();
  const [isLoading, setIsLoading] = useState(true);
  const [favorites, setFavorites] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('lot-asc');
  const [selectedSale, setSelectedSale] = useState('all');
  const [itemsPerPage, setItemsPerPage] = useState(12);
  const [currentPage, setCurrentPage] = useState(1);
  const [viewType, setViewType] = useState('full');
  const config = useContext(ConfigContext);
  const { fetchItemsByIds } = useDataCache();
  const toast = useToast();
  const [selectedToCompare, setSelectedToCompare] = useState([]);
  const {
    isOpen: isCompareOpen,
    onOpen: onCompareOpen,
    onClose: onCompareClose
  } = useDisclosure();
  const [sales, setSales] = useState([
    {
      id: 0,
      uuid: 'all',
      title: t('myFavorites.allSales')
    }
  ]);
  const [unfollowedIds, setUnfollowedIds] = useState(new Set());


  // Fetch sales list.
  useEffect(() => {
    if (!config.accessToken) return;
    if (!config.userData) return;

    const fetchSales = async () => {
      const data = config.userData;
      if (data.website_bidder_info && Array.isArray(data.website_bidder_info)) {
        const fetchedSales = data.website_bidder_info.map(info => ({
          id: info.sale,
          uuid: info.sale_uuid,
          title: info.sale_title || `Sale ${info.id}`,
          status: info.sale_status
        }));

        setSales([
          {
            id: 0,
            uuid: 'all',
            title: t('myFavorites.allSales')
          }, ...fetchedSales
        ]);
      }
    };

    fetchSales();
  }, [config.accessToken, config.siteData, config.siteData.backoffice_url, config.userData, toast, t]);

  // Fetch favorites items.
  const fetchFavorites = useCallback(async (saleUuid = 'all') => {
    setIsLoading(true);
    try {
      // First fetch favorite items
      let url = `${config.backendUrl}/api/item_flaggings`;
      if (saleUuid !== 'all') {
        url += `?sale_uuid=${saleUuid}`;
      }

      const response = await fetchData(url, {
        mockData: 'api-items-favorites',
        headers: { 'access-token': config.accessToken },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch favorites');
      }

      const flaggingsResult = await response.json();
      const favoriteItems = flaggingsResult.data || [];

      // If we have favorite items, fetch their details
      if (favoriteItems.length > 0) {
        // Get the uuids of all favorite items
        const itemUuids = favoriteItems.map(item => item.item_uuid);

        const language = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        const itemsResult = await fetchItemsByIds(
          config.siteData.backoffice_url_lang,
          itemUuids,
          language
        );

        // Merge flagging data with item details
        const mergedItems = favoriteItems.map(favorite => {
          const itemDetails = itemsResult.data.find(item => item.uuid === favorite.item_uuid);
          return {
            ...favorite, ...itemDetails
          };
        });

        setFavorites(mergedItems);
      } else {
        setFavorites([]);
      }
      setIsLoading(false);
    } catch (error) {
      toast({
        title: t('myFavorites.errorFetching'),
        description: error.message,
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      setIsLoading(false);
    }
  }, [config.backendUrl, config.siteData.backoffice_url_lang, config.accessToken, i18n.language, fetchItemsByIds, toast, t]);

  // Fetch favorites items.
  useEffect(() => {
    if (!config.accessToken) return;
    if (!config.userData) return;

    fetchFavorites(selectedSale);
  }, [selectedSale, fetchFavorites, config.accessToken, config.userData]);

  const handleCompareToggle = (item) => {
    setSelectedToCompare(prev => {
      if (prev.find(i => i.id === item.id)) {
        return prev.filter(i => i.id !== item.id);
      }
      if (prev.length >= 4) {
        toast({
          title: t('myFavorites.maxItemsReached'),
          status: 'warning',
          duration: 3000,
          isClosable: true,
        });
        return prev;
      }
      return [...prev, item];
    });
  };

  const Pagination = ({
    currentPage,
    totalPages,
    onPageChange,
    totalItems,
    itemsPerPage,
  }) => {
    const startItem = (currentPage - 1) * itemsPerPage + 1;
    const endItem = Math.min(currentPage * itemsPerPage, totalItems);

    return (
      <nav className="favorites-pagination" aria-label="Pagination">
        <p className="favorites-pagination__status">
          {t('pagination.showing', {
            start: startItem,
            end: endItem,
            total: totalItems,
          })}
        </p>

        <div className="favorites-pagination__controls">
          <button
            type="button"
            className="favorites-pagination__btn"
            disabled={currentPage === 1}
            onClick={() => onPageChange(currentPage - 1)}
          >
            {t('pagination.previous')}
          </button>

          {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
            <button
              key={page}
              type="button"
              aria-current={currentPage === page ? 'page' : undefined}
              className={`favorites-pagination__btn favorites-pagination__btn--num${currentPage === page ? ' is-active' : ''}`}
              onClick={() => onPageChange(page)}
            >
              {page}
            </button>
          ))}

          <button
            type="button"
            className="favorites-pagination__btn"
            disabled={currentPage === totalPages}
            onClick={() => onPageChange(currentPage + 1)}
          >
            {t('pagination.next')}
          </button>
        </div>
      </nav>
    );
  };

  const filteredItems = favorites
    .filter(item => {
      const matchesSearch = item.body?.toLowerCase().includes(searchTerm.toLowerCase()) || item.lot_number?.toLowerCase().includes(searchTerm.toLowerCase()) || item.title?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesSale = selectedSale === 'all' || item.sale_uuid === selectedSale;
      return matchesSearch && matchesSale;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'lot-asc':
          return parseInt(a.lot_number) - parseInt(b.lot_number);
        case 'lot-desc':
          return parseInt(b.lot_number) - parseInt(a.lot_number);
        case 'price-asc':
          // Replace thousands separator and remove non-numeric characters
          const priceA = parseFloat(a.opening_price.replace(/\./g, '').replace(/[^\d]/g, ''));
          const priceB = parseFloat(b.opening_price.replace(/\./g, '').replace(/[^\d]/g, ''));
          return priceA - priceB;
        case 'price-desc':
          // Replace thousands separator and remove non-numeric characters
          const descPriceA = parseFloat(a.opening_price.replace(/\./g, '').replace(/[^\d]/g, ''));
          const descPriceB = parseFloat(b.opening_price.replace(/\./g, '').replace(/[^\d]/g, ''));
          return descPriceB - descPriceA;
        default:
          return 0;
      }
    })

  const totalPages = Math.ceil(filteredItems.length / itemsPerPage);
  const paginatedItems = filteredItems.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);
  // The "Description" column holds the lot title (when shown) plus the
  // body beneath it, so it appears whenever either is present.
  const pageHasDescription = paginatedItems.some(
    (item) => item.show_title || item.body || item.footer
  );

  const TableSkeleton = () => (<Box borderWidth="1px" borderRadius="lg" overflow="hidden">
      <Table variant="simple">
        <Thead>
          <Tr>
            <Th width="50px"><Skeleton height="20px" width="20px"/></Th>
            <Th><Skeleton height="20px" width="100px"/></Th>
            <Th><Skeleton height="20px" width="200px"/></Th>
            <Th><Skeleton height="20px" width="100px"/></Th>
            <Th><Skeleton height="20px" width="150px"/></Th>
            <Th><Skeleton height="20px" width="100px"/></Th>
            <Th><Skeleton height="20px" width="150px"/></Th>
            <Th><Skeleton height="20px" width="100px"/></Th>
          </Tr>
        </Thead>
        <Tbody>
          {Array.from({ length: 5 }).map((_, index) => (<Tr key={index}>
              <Td><Skeleton height="20px" width="20px"/></Td>
              <Td>
                <Flex align="center" gap={4}>
                  <Skeleton height="50px" width="50px"/>
                  <Skeleton height="20px" width="60px"/>
                </Flex>
              </Td>
              <Td><Skeleton height="20px" width="200px"/></Td>
              <Td><Skeleton height="20px" width="80px"/></Td>
              <Td><Skeleton height="20px" width="120px"/></Td>
              <Td><Skeleton height="20px" width="80px"/></Td>
              <Td><Skeleton height="20px" width="120px"/></Td>
              <Td>
                <HStack spacing={2}>
                  <Skeleton height="30px" width="80px"/>
                  <Skeleton height="30px" width="80px"/>
                </HStack>
              </Td>
            </Tr>))}
        </Tbody>
      </Table>
    </Box>);

  if (isLoading) {
    return (
      <div className="my-favorites-page">
        <section className="rc-card account-card my-favorites">
          <header className="card-head">
            <h2 className="page-title">{t('userBlock.myFavorites')}</h2>
          </header>
          <div className="card-body">
            <div className="my-bids-toolbar" style={{ marginBottom: 'var(--space-5)' }}>
              <Skeleton height="40px" width="300px" />
              <Skeleton height="40px" width="240px" />
              <Skeleton height="40px" width="200px" />
            </div>
            {viewType === 'table' ? (
              <TableSkeleton />
            ) : (
              Array.from({ length: 3 }).map((_, index) => (
                <Box key={index} p={4} borderWidth="1px" borderRadius="lg" mb={4}>
                  <Flex gap={4}>
                    <Skeleton height="200px" width="200px" />
                    <Box flex="1">
                      <SkeletonText mt="4" noOfLines={1} spacing="4" width="200px" />
                      <SkeletonText mt="4" noOfLines={3} spacing="4" />
                      <Flex gap={6} mt={4}>
                        <Skeleton height="20px" width="120px" />
                        <Skeleton height="20px" width="120px" />
                        <Skeleton height="20px" width="120px" />
                      </Flex>
                      <SkeletonText mt="4" noOfLines={4} spacing="4" />
                    </Box>
                  </Flex>
                </Box>
              ))
            )}
          </div>
        </section>
      </div>
    );
  }

  const sortOptions = [
    { value: 'lot-asc',   label: t('sort.lotAsc') },
    { value: 'lot-desc',  label: t('sort.lotDesc') },
    { value: 'price-asc', label: t('sort.priceAsc') },
    { value: 'price-desc',label: t('sort.priceDesc') },
  ];
  const perPageOptions = [12, 24, 36, 48].map((n) => ({
    value: String(n),
    label: t('filters.itemsPerPageOption', { count: n, defaultValue: `${n} per page` }),
  }));

  return (
    <div className="my-favorites-page">
      <CompareWidget
        selectedItems={selectedToCompare}
        onCompare={onCompareOpen}
        t={t}
      />

      <section className="rc-card account-card my-favorites">
        <header className="card-head">
          <h2 className="page-title">{t('userBlock.myFavorites')}</h2>
        </header>

        <div className="card-body">
          <div className="favorites-toolbar">
            <CircuitDropdown
              variant="wide"
              value={selectedSale}
              onChange={(v) => setSelectedSale(v)}
              ariaLabel={t('filters.saleLabel')}
              options={sales.map((sale) => ({
                value: sale.uuid,
                label: sale.title,
              }))}
            />

            <div className="favorites-search">
              <Search size={16} className="favorites-search__icon" aria-hidden="true" />
              <input
                type="search"
                className="field-input favorites-search__input"
                placeholder={t('search.placeholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                aria-label={t('filters.searchLabel')}
              />
            </div>

            <CircuitDropdown
              value={sortBy}
              onChange={(v) => setSortBy(v)}
              ariaLabel={t('filters.sortLabel')}
              options={sortOptions}
            />

            <CircuitDropdown
              value={String(itemsPerPage)}
              onChange={(v) => setItemsPerPage(Number(v))}
              ariaLabel={t('filters.itemsPerPage')}
              options={perPageOptions}
            />

            <button
              type="button"
              className="btn-secondary-action"
              onClick={() => {
                setSearchTerm('');
                setSortBy('lot-asc');
                setItemsPerPage(12);
                setSelectedToCompare([]);
              }}
            >
              <RefreshCw size={14} /> {t('filters.reset')}
            </button>

            <div className="view-toggle favorites-toolbar__view" role="group" aria-label={t('myBids.summaryView')}>
              <button
                type="button"
                className={`view-toggle__btn${viewType === 'table' ? ' is-active' : ''}`}
                onClick={() => setViewType('table')}
              >
                <List /> {t('myBids.summaryView')}
              </button>
              <button
                type="button"
                className={`view-toggle__btn${viewType === 'full' ? ' is-active' : ''}`}
                onClick={() => setViewType('full')}
              >
                <LayoutList /> {t('myBids.detailedView')}
              </button>
            </div>
          </div>

          {/* Content Area */}
          {paginatedItems.length === 0 ? (
            <div className="favorites-empty">
              {favorites.length === 0 ? (
                <>
                  <p className="favorites-empty__title">{t('myFavorites.noFavorites')}</p>
                  <p className="favorites-empty__hint">{t('myFavorites.addFavoritesHint')}</p>
                </>
              ) : (
                <p className="favorites-empty__title">{t('myFavorites.noMatchingFavorites')}</p>
              )}
            </div>
          ) : viewType === 'table' ? (<>
            {/* Desktop Table View */}
            <Hide below="md">
              <Box borderWidth="1px" borderRadius="lg" overflow="auto">
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th width="50px"></Th>
                      <Th width="60px">{t('myFavorites.image')}</Th>
                      <Th>{t('myFavorites.lot')}</Th>
                      {pageHasDescription && (<Th>{t('myFavorites.description')}</Th>)}
                      <Th>{t('myFavorites.startPrice')}</Th>
                      <Th>{t('myFavorites.estimate')}</Th>
                      <Th>{t('myFavorites.soldFor')}</Th>
                      <Th>{t('myFavorites.actions')}</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {paginatedItems.map((item) => {
                      const descHtml = (item.body || '') + (item.footer ? ' ' + item.footer : '');
                      const hasBody = !!(item.body || item.footer);
                      return (
                      <Tr key={item.id} opacity={unfollowedIds.has(item.item_id) ? 0.5 : 1}>
                        <Td>
                          <Hide below="md">
                            <Checkbox
                              isChecked={selectedToCompare.some(i => i.id === item.id)}
                              onChange={() => handleCompareToggle(item)}
                              isDisabled={selectedToCompare.length >= 4 && !selectedToCompare.some(i => i.id === item.id)}
                            />
                          </Hide>
                        </Td>
                        <Td py={0}>
                          <ChakraLink href={item.url}>
                            {item.image_gallery?.images_path?.[0]?.small ? (
                              <Image
                                src={item.image_gallery.images_path[0].small}
                                onError={handleImageError}
                                alt={`Lot ${item.lot_number}`}
                                height="50px"
                                objectFit="cover"
                                borderRadius="md"
                                loading="lazy"
                              />
                            ) : (
                              <Box
                                width="50px"
                                height="50px"
                                bg="gray.100"
                                borderRadius="md"
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                              >
                                <Text fontSize="xs" color="gray.400">N/A</Text>
                              </Box>
                            )}
                          </ChakraLink>
                        </Td>
                        <Td>
                          <ChakraLink href={item.url} color="blue.500">
                            {item.lot_number}
                          </ChakraLink>
                        </Td>
                        {pageHasDescription && (
                          <Td maxW="360px" className="fav-desc-cell">
                            {item.show_title && item.title && (
                              <div className="fav-desc-cell__title">{item.title}</div>
                            )}
                            {hasBody ? (
                              <LotDescription html={descHtml} t={t} />
                            ) : (!item.show_title && '-')}
                          </Td>
                        )}
                        <Td>{item.opening_price}</Td>
                        <Td>{item.estimation || '-'}</Td>
                        <Td>{item.soldfor || '-'}</Td>
                        <Td>
                          <HStack spacing={2}>
                            <FavoriteButton
                              itemId={item.item_id}
                              initialIsFollowing={!unfollowedIds.has(item.item_id)}
                              onFavoriteChange={(isFollowing) => {
                                if (isFollowing) {
                                  setUnfollowedIds(prev => {
                                    const newSet = new Set(prev);
                                    newSet.delete(item.item_id);
                                    return newSet;
                                  });
                                } else {
                                  setUnfollowedIds(prev => {
                                    const newSet = new Set(prev);
                                    newSet.add(item.item_id);
                                    return newSet;
                                  });
                                }
                              }}
                            />
                          </HStack>
                        </Td>
                      </Tr>
                      );
                    })}
                  </Tbody>
                </Table>
              </Box>
            </Hide>

            {/* Mobile Card View */}
            <Show below="md">
              <Stack spacing={4}>
                {paginatedItems.map((item) => (<Card key={item.id}>
                    <CardBody>
                      <Stack divider={<StackDivider/>} spacing={3}>
                        <Flex justify="space-between" align="center">
                          <ChakraLink href={item.url} color="blue.500">
                            {t('myFavorites.lot')} {item.lot_number}
                          </ChakraLink>
                          <Hide below="md">
                            <Checkbox
                              isChecked={selectedToCompare.some(i => i.id === item.id)}
                              onChange={() => handleCompareToggle(item)}
                              isDisabled={selectedToCompare.length >= 4 && !selectedToCompare.some(i => i.id === item.id)}
                            />
                          </Hide>
                        </Flex>

                        {item.show_title && (<Text fontWeight="medium">{item.title}</Text>)}

                        {(item.body || item.footer) && (
                          <LotDescription
                            html={(item.body || '') + (item.footer ? ' ' + item.footer : '')}
                            t={t}
                          />
                        )}

                        <Stack spacing={2}>
                          <Flex justify="space-between">
                            <Text fontWeight="medium">{t('myFavorites.startPrice')}:</Text>
                            <Text>{item.opening_price}</Text>
                          </Flex>
                          <Flex justify="space-between">
                            <Text fontWeight="medium">{t('myFavorites.estimate')}:</Text>
                            <Text>{item.estimation || '-'}</Text>
                          </Flex>
                          <Flex justify="space-between">
                            <Text fontWeight="medium">{t('myFavorites.soldFor')}:</Text>
                            <Text>{item.soldfor || '-'}</Text>
                          </Flex>
                        </Stack>

                        <Box>
                          <FavoriteButton
                            itemId={item.item_id}
                            initialIsFollowing={!unfollowedIds.has(item.item_id)}
                            onFavoriteChange={(isFollowing) => {
                              if (isFollowing) {
                                setUnfollowedIds(prev => {
                                  const newSet = new Set(prev);
                                  newSet.delete(item.item_id);
                                  return newSet;
                                });
                              } else {
                                setUnfollowedIds(prev => {
                                  const newSet = new Set(prev);
                                  newSet.add(item.item_id);
                                  return newSet;
                                });
                              }
                            }}
                          />
                        </Box>
                      </Stack>
                    </CardBody>
                  </Card>))}
              </Stack>
            </Show>
          </>) : (
            <div className="favorite-list">
              {paginatedItems.map((item) => {
                const onUnfollowed = (isFollowing) => {
                  setUnfollowedIds((prev) => {
                    const next = new Set(prev);
                    if (isFollowing) next.delete(item.item_id);
                    else next.add(item.item_id);
                    return next;
                  });
                };
                const isInCompare = selectedToCompare.some((i) => i.id === item.id);
                const compareDisabled = selectedToCompare.length >= 4 && !isInCompare;

                return (
                  <article
                    key={item.id}
                    className={`favorite-lot${unfollowedIds.has(item.item_id) ? ' is-unfollowed' : ''}`}
                  >
                    <a href={item.url} className="favorite-lot__image" aria-label={`Lot ${item.lot_number}`}>
                      <ItemImageGallery
                        images={item.image_gallery?.images_path || []}
                        displayMode="teaser"
                      />
                    </a>

                    <div className="favorite-lot__body">
                      <header className="favorite-lot__head">
                        <a href={item.url} className="favorite-lot__lot-link">
                          {t('myBids.lot')} {item.lot_number}
                        </a>
                        {item.show_title && (
                          <h3 className="favorite-lot__title">{item.title}</h3>
                        )}
                      </header>

                      <div className="favorite-lot__stats">
                        <div className="favorite-lot__stat">
                          <span className="favorite-lot__stat-label">
                            {t('myFavorites.startPrice')}
                          </span>
                          <span className="favorite-lot__stat-value">
                            {item.opening_price}
                          </span>
                        </div>
                        {item.estimation && (
                          <div className="favorite-lot__stat">
                            <span className="favorite-lot__stat-label">
                              {t('myFavorites.estimate')}
                            </span>
                            <span className="favorite-lot__stat-value">
                              {item.estimation}
                            </span>
                          </div>
                        )}
                        {item.soldfor !== undefined && item.soldfor !== null && (
                          <div className="favorite-lot__stat favorite-lot__stat--sold">
                            <span className="favorite-lot__stat-label">
                              {t('myFavorites.soldFor')}
                            </span>
                            <span className="favorite-lot__stat-value">
                              {item.soldfor}
                            </span>
                          </div>
                        )}
                      </div>

                      {(item.categories
                        || item.item_taxonomy?.catalogue_name_and_number?.rendered
                        || item.item_taxonomy?.symbols?.rendered) && (
                        <div className="favorite-lot__meta">
                          {item.categories && (
                            <span className="favorite-lot__meta-pill">{item.categories}</span>
                          )}
                          {item.item_taxonomy?.catalogue_name_and_number?.rendered && (
                            <span
                              className="favorite-lot__meta-pill"
                              dangerouslySetInnerHTML={{
                                __html: item.item_taxonomy.catalogue_name_and_number.rendered,
                              }}
                            />
                          )}
                          {item.item_taxonomy?.symbols?.rendered && (
                            <span
                              className={`favorite-lot__meta-pill catalog-symbols ${item.item_taxonomy.symbols.class_wrapper || 'aukphila'}`}
                              dangerouslySetInnerHTML={{
                                __html: item.item_taxonomy.symbols.rendered,
                              }}
                            />
                          )}
                        </div>
                      )}

                      <div
                        className="favorite-lot__description"
                        dangerouslySetInnerHTML={{
                          __html: (item.body || '') + (item.footer ? ' ' + item.footer : ''),
                        }}
                      />

                      {item.provenance && (
                        <div
                          className="favorite-lot__description favorite-lot__description--provenance"
                          dangerouslySetInnerHTML={{ __html: item.provenance }}
                        />
                      )}

                      <div className="favorite-lot__sale">
                        {item.sale_title && <span>{item.sale_title}</span>}
                        {item.live_sale_date && <span>{item.live_sale_date}</span>}
                      </div>
                    </div>

                    <div className="favorite-lot__actions">
                      <FavoriteButton
                        itemId={item.item_id}
                        initialIsFollowing={!unfollowedIds.has(item.item_id)}
                        onFavoriteChange={onUnfollowed}
                      />
                      <Hide below="md">
                        <label
                          className={`checkbox-row favorite-lot__compare${compareDisabled ? ' is-disabled' : ''}`}
                        >
                          <input
                            type="checkbox"
                            checked={isInCompare}
                            disabled={compareDisabled}
                            onChange={() => handleCompareToggle(item)}
                          />
                          <span className="checkbox-label">
                            {t('myFavorites.addToCompare')}
                          </span>
                        </label>
                      </Hide>
                      <a
                        href={item.url}
                        className="bid-limit-submit favorite-lot__view"
                      >
                        {t('myFavorites.viewItem')}
                      </a>
                    </div>
                  </article>
                );
              })}
            </div>
          )}

        {/* Pagination */}
        {paginatedItems.length > 0 && (<Pagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={setCurrentPage}
            totalItems={filteredItems.length}
            itemsPerPage={itemsPerPage}
          />)}

          {/* Compare Modal — TODO(circuit): replace with native popover. */}
          <CompareModal
            isOpen={isCompareOpen}
            onClose={onCompareClose}
            items={selectedToCompare}
            t={t}
          />
        </div>
      </section>
    </div>
  );
};

export default MyFavorites;