import React from 'react';
import { createRoot } from 'react-dom/client';
import { createPortal } from 'react-dom';
import './styles/index.css';
import './styles/styles.scss';
import i18n from './config/i18n';
import Cookies from 'js-cookie';
import enTranslations from './locales/en.json';
import frTranslations from './locales/fr.json';
import deTranslations from './locales/de.json';
import nlTranslations from './locales/nl.json';
import ruTranslations from './locales/ru.json';
import zhTranslations from './locales/zh.json';

import UserBlock from './pages/UserBlock';
import MyBids from './pages/MyBids';
import MyAccount from './pages/MyAccount';
import Myfavorites from './pages/MyFavorites';
import Register from './pages/Register';
import Login from './pages/Login';
import SalePage from './pages/Sale';
import SalesList from './pages/SalesList';
import SaleInfo from './pages/SaleInfo';
import ItemPage from './pages/ItemPage';
import PricesRealized from './pages/PricesRealized';
import FeaturedItems from './pages/FeaturedItems';
import ForgotPassword from './pages/ForgotPassword';
import { ChakraProvider } from '@chakra-ui/react';
import { CacheProvider } from '@emotion/react';
import createCache from '@emotion/cache';
import { ConfigProvider } from './config/Config';
import { DataCacheProvider } from './services/DataCache';
import AuthWrapper from './components/AuthWrapper';
import packageJson from '../package.json';
import PlaceBid from './pages/PlaceBid';
import FavoriteButton from './components/FavoriteButton';
import BillingContainer from './pages/BillingContainer'; // Import the new container
import UserInterests from './pages/UserInterests';
import SubscriptionMagazine from './pages/SubscriptionMagazine';
import SubscriptionPurchase from './pages/SubscriptionPurchase';
import Balance from './pages/Balance';
import LiveSaleLinks from './pages/LiveSaleLinks';
import chakraTheme from './chakraTheme';

// Custom Emotion cache so generated classes are prefixed `circuit-` instead of `css-`.
// Prevents host-site rules like `.css-0 { ... }` from accidentally targeting our Chakra elements.
const emotionCache = createCache({
  key: 'circuit',
  container: document.head,
});

// Log version information
console.log(`Circuit User UI Version: ${packageJson.version}`);
console.log(`Build Time: ${new Date().toISOString()}`);

// Load translation resources
i18n.addResourceBundle('en', 'translation', enTranslations, true, true);
i18n.addResourceBundle('fr', 'translation', frTranslations, true, true);
i18n.addResourceBundle('de', 'translation', deTranslations, true, true);
i18n.addResourceBundle('nl', 'translation', nlTranslations, true, true);
i18n.addResourceBundle('ru', 'translation', ruTranslations, true, true);
i18n.addResourceBundle('zh', 'translation', zhTranslations, true, true);

// Set language with priority: circuit-setup attribute > cookie > browser language
const supportedLanguages = ['en', 'fr', 'de', 'nl', 'ru', 'zh'];

// First check circuit-setup div for language attribute
const siteElement = document.getElementById('circuit-setup');
const setupLanguage = siteElement?.getAttribute('language');

if (setupLanguage && supportedLanguages.includes(setupLanguage)) {
  i18n.changeLanguage(setupLanguage);
} else {
  // Fall back to cookie
  let prefLanguage = Cookies.get('pref-browser-lang');
  if (prefLanguage === 'zh-hans') {
    prefLanguage = 'zh';
  }

  if (prefLanguage && supportedLanguages.includes(prefLanguage)) {
    i18n.changeLanguage(prefLanguage);
  } else {
    // If no valid cookie is set, use the browser's language
    const browserLang = navigator.language.split('-')[0]; // e.g., 'en-US' becomes 'en'
    if (supportedLanguages.includes(browserLang)) {
      i18n.changeLanguage(browserLang);
    } else {
      i18n.changeLanguage('en'); // fallback to English
    }
  }
}

// Find all containers
const containers = {
  userBlock: document.getElementById('user-block'),
  myBids: document.getElementById('my-bids'),
  myAccount: document.getElementById('my-account'),
  myFavorites: document.getElementById('my-favorites'),
  register: document.getElementById('register'),
  login: document.getElementById('login'),
  forgotPassword: document.getElementById('forgotpassword'),
  billingPage: document.getElementById('billing-history'),
  paymentMethods: document.getElementById('payment-method'),
  userInterests: document.getElementById('my-interests'),
  subscriptionMagazine: document.getElementById('subscription-magazine'),
  subscriptionPurchase: document.getElementById('subscription-purchase'),
  balance: document.getElementById('balance-btn'),
  salePage: document.getElementById('ca-sale-page'),
  salesList: document.getElementById('ca-sales-list'),
  saleInfo: document.getElementById('ca-sale-info'),
  itemPage: document.getElementById('ca-item-page'),
  pricesRealized: document.getElementById('ca-prices-realized'),
  featuredItems: document.getElementById('ca-featured-items'),
  liveSaleLinks: document.getElementById('live-sale-links'),
};

// Get item page UUID and display mode if container exists
// Can uuid or nid
const itemId = containers.itemPage?.getAttribute('data-item-id');
const itemPageDisplayMode = containers.itemPage?.getAttribute('data-display-mode') || 'full';

// Get sale info NID if container exists
const saleInfoNid = containers.saleInfo?.getAttribute('data-sale-nid');

// Find all place-bid containers (supports multiple instances)
const placeBidContainers = document.querySelectorAll('.place-bid');

// Find all favorite-btn containers (supports multiple instances)
const favoriteBtnContainers = document.querySelectorAll('.favorite-btn');

// Check if any containers exist
const hasAnyContainer = Object.values(containers).some(container => container !== null) || placeBidContainers.length > 0 || favoriteBtnContainers.length > 0;

if (hasAnyContainer) {
  // Create a hidden div for the single React root
  const appRoot = document.createElement('div');
  appRoot.id = 'circuit-app-root';
  appRoot.style.display = 'none';
  document.body.appendChild(appRoot);

  // Create a single root for all components with shared ConfigProvider
  const root = createRoot(appRoot);

  // Get FavoriteButton props for all favorite-btn containers
  const favoriteBtnInstances = Array.from(favoriteBtnContainers).map((container, index) => ({
    container,
    itemId: container.getAttribute('data-item-id'),
    displayMode: container.getAttribute('data-display-mode') || 'grid',
    key: `favorite-btn-${index}`,
  }));

  // Get PlaceBid props for all place-bid containers
  const placeBidInstances = Array.from(placeBidContainers).map((container, index) => ({
    container,
    saleNid: container.getAttribute('data-sale-nid'),
    saleUuid: container.getAttribute('data-sale-uuid'),
    itemUuid: container.getAttribute('data-item-uuid'),
    debug: container.getAttribute('data-debug') === 'true',
    hideSoldUnsold: container.getAttribute('hide-sold-unsold') === 'true',
    key: `place-bid-${index}`,
  }));

  // Component that uses portals to render into the original containers
  const App = () => (
    <CacheProvider value={emotionCache}>
    <ChakraProvider theme={chakraTheme} resetCSS={false}>
      <ConfigProvider>
        <DataCacheProvider>
          <>
            {containers.register && createPortal(<Register />, containers.register)}
            {containers.login && createPortal(<Login />, containers.login)}
            {containers.forgotPassword && createPortal(<ForgotPassword />, containers.forgotPassword)}
            {containers.userBlock && createPortal(<UserBlock />, containers.userBlock)}
            {containers.myBids && createPortal(<AuthWrapper><MyBids /></AuthWrapper>, containers.myBids)}
            {containers.myAccount && createPortal(<AuthWrapper><MyAccount /></AuthWrapper>, containers.myAccount)}
            {containers.userInterests && createPortal(<UserInterests />, containers.userInterests)}
            {containers.myFavorites && createPortal(<AuthWrapper><Myfavorites /></AuthWrapper>, containers.myFavorites)}
            {containers.billingPage && createPortal(<AuthWrapper><BillingContainer /></AuthWrapper>, containers.billingPage)}
            {containers.paymentMethods && createPortal(<AuthWrapper><BillingContainer /></AuthWrapper>, containers.paymentMethods)}
            {containers.subscriptionMagazine && createPortal(<SubscriptionMagazine />, containers.subscriptionMagazine)}
            {containers.subscriptionPurchase && createPortal(<SubscriptionPurchase />, containers.subscriptionPurchase)}
            {containers.balance && createPortal(<Balance />, containers.balance)}
            {containers.salePage && createPortal(<SalePage />, containers.salePage)}
            {containers.salesList && createPortal(<SalesList />, containers.salesList)}
            {containers.saleInfo && createPortal(<SaleInfo saleNid={saleInfoNid} />, containers.saleInfo)}
            {containers.itemPage && createPortal(<ItemPage itemId={itemId}  displayMode={itemPageDisplayMode} />, containers.itemPage)}
            {containers.pricesRealized && createPortal(<PricesRealized />, containers.pricesRealized)}
            {containers.featuredItems && createPortal(<FeaturedItems />, containers.featuredItems)}
            {containers.liveSaleLinks && createPortal(<LiveSaleLinks />, containers.liveSaleLinks)}

            {/* Render all PlaceBid instances */}
            {placeBidInstances.map(({ container, itemUuid, saleUuid, debug, hideSoldUnsold, key }) =>
              createPortal(
                <PlaceBid
                  key={key}
                  itemUuid={itemUuid}
                  saleUuid={saleUuid}
                  debug={debug}
                  hideSoldUnsold={hideSoldUnsold}
                />,
                container
              )
            )}

            {/* Render all FavoriteButton instances */}
            {favoriteBtnInstances.map(({ container, itemId, displayMode, key }) =>
              createPortal(
                <FavoriteButton
                  key={key}
                  itemId={itemId}
                  displayMode={displayMode}
                />,
                container
              )
            )}
          </>
        </DataCacheProvider>
      </ConfigProvider>
    </ChakraProvider>
    </CacheProvider>
  );

  root.render(<App />);
}
