import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useForm, Controller } from 'react-hook-form';
import AddressFormatter from '@shopify/address';

const ADDRESS_TYPE_OPTIONS = [
  { value: 'letters', label: 'Letters' },
  { value: 'consignor_statement', label: 'Consignor address' },
  { value: 'shipping_for_lots', label: 'Shipping for lots' },
  { value: 'catalogue', label: 'Catalogue' },
  { value: 'invoices', label: 'Invoices' },
];

const AddressForm = ({ address, onSave, onDelete, namePrefixes, isDefault, onDefaultChange, defaultCountry, isFirstAddress = false }) => {
  const { t, i18n } = useTranslation();
  const [countries, setCountries] = useState([]);
  const [provinces, setProvinces] = useState([]);
  const [countryFormatter, setCountryFormatter] = useState(null);
  const [addressFormatter, setAddressFormatter] = useState(null);
  const [error, setError] = useState(null);

  const extraData = address?.address?.data ? JSON.parse(address.address.data) : null;
  const defaultValues = address ? {
    defaultAddress: isFirstAddress ? true : (address.default_address || false),
    addressTypes: address.address_types || [],
    careOf: extraData?.care_of || '',
    namePrefix: extraData?.name_prefix || '',
    firstName: address.address.first_name || '',
    lastName: address.address.last_name || '',
    company: address.address.organisation_name || '',
    address1: address.address.thoroughfare || '',
    address2: address.address.premise || '',
    city: address.address.locality || '',
    province: address.address.administrative_area || '',
    zip: address.address.postal_code || '',
    country: address.address.country || defaultCountry || '',
  } : {
    defaultAddress: false,
    addressTypes: [],
    namePrefix: '',
    firstName: '',
    careOf: '',
    lastName: '',
    company: '',
    address1: '',
    address2: '',
    city: '',
    province: '',
    zip: '',
    country: '',
  };

  const { control, handleSubmit, setValue, watch } = useForm({
    defaultValues,
  });

  const selectedCountry = watch('country');

  useEffect(() => {
    const initializeAddressFormatter = async () => {
      try {
        const formatter = new AddressFormatter(i18n.language);
        setAddressFormatter(formatter);

        const loadedCountries = await formatter.getCountries();
        setCountries(loadedCountries);

        if (defaultCountry && !selectedCountry) {
          setValue('country', defaultCountry);
        }
      } catch (err) {
        console.error('Error initializing AddressFormatter:', err);
        setError('An error occurred while initializing the address formatter. Please try again.');
      }
    };

    initializeAddressFormatter();
  }, [i18n.language, defaultCountry, selectedCountry, setValue]);

  useEffect(() => {
    const loadProvinces = async () => {
      if (selectedCountry && addressFormatter) {
        try {
          const cf = await addressFormatter.getCountry(selectedCountry);
          setProvinces(cf.zones);
          setCountryFormatter(cf);
        } catch (err) {
          console.error('Error loading provinces:', err);
          setError('An error occurred while loading the provinces. Please try again.');
        }
      }
    };

    loadProvinces();
  }, [selectedCountry, addressFormatter]);

  useEffect(() => {
    const subscription = watch((value, { name }) => {
      if (name === 'defaultAddress') {
        onDefaultChange(value[name]);
      }
    });
    return () => subscription.unsubscribe();
  }, [watch, onDefaultChange]);

  const onSubmit = async (data) => {
    try {
      onSave(data);
    } catch (err) {
      setError('An error occurred while saving. Please try again.');
    }
  };

  const renderField = useCallback((field) => {
    if (!countryFormatter && field !== 'country') {
      return null;
    }

    switch (field) {
      case 'defaultAddress':
        return (
          <Controller
            name="defaultAddress"
            control={control}
            render={({ field }) => (
              <div className="address-form__default-row">
                <label className="checkbox-row">
                  <input
                    type="checkbox"
                    checked={!!(isFirstAddress || isDefault)}
                    disabled={isFirstAddress}
                    onChange={(e) => {
                      field.onChange(e.target.checked);
                      setValue('defaultAddress', e.target.checked);
                      onDefaultChange(e.target.checked);
                    }}
                  />
                  <span className="checkbox-label">{t('addressForm.defaultAddress')}</span>
                </label>
                {isFirstAddress && (
                  <p className="field-help">{t('addressForm.firstAddressDefault')}</p>
                )}
              </div>
            )}
          />
        );
      case 'addressTypes':
        return (
          <Controller
            name="addressTypes"
            control={control}
            render={({ field }) => {
              const value = Array.isArray(field.value) ? field.value : [];
              return (
                <div className="address-types-group">
                  <p className="address-types-group__label">{t('addressForm.addressType')}</p>
                  <div className="address-types-group__options">
                    {ADDRESS_TYPE_OPTIONS.map((type) => (
                      <label key={type.value} className="checkbox-row">
                        <input
                          type="checkbox"
                          checked={value.includes(type.value)}
                          onChange={(e) => {
                            const isChecked = e.target.checked;
                            const selected = isChecked
                              ? [...value, type.value]
                              : value.filter((v) => v !== type.value);
                            field.onChange(selected);
                            setValue('addressTypes', selected);
                          }}
                        />
                        <span className="checkbox-label">
                          {t(`addressForm.addressTypes.${type.value}`)}
                        </span>
                      </label>
                    ))}
                  </div>
                </div>
              );
            }}
          />
        );
      case 'namePrefix':
        return (
          <Controller
            key={field}
            name="namePrefix"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-namePrefix" className="field-label">{t('addressForm.title')}</label>
                <select
                  id="af-namePrefix"
                  {...field}
                  className="field-select"
                  onChange={(e) => {
                    field.onChange(e);
                    setValue('namePrefix', e.target.value);
                  }}
                >
                  <option value="">{t('addressForm.selectTitle')}</option>
                  {namePrefixes.map((prefix) => (
                    <option key={prefix.id} value={prefix.id}>{prefix.label}</option>
                  ))}
                </select>
              </div>
            )}
          />
        );
      case 'firstName':
        return (
          <Controller
            key={field}
            name="firstName"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-firstName" className="field-label">{t('addressForm.firstName')}</label>
                <input id="af-firstName" {...field} type="text" className="field-input" />
              </div>
            )}
          />
        );
      case 'lastName':
        return (
          <Controller
            key={field}
            name="lastName"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-lastName" className="field-label">{t('addressForm.lastName')}</label>
                <input id="af-lastName" {...field} type="text" className="field-input" />
              </div>
            )}
          />
        );
      case 'careOf':
        return (
          <Controller
            key={field}
            name="careOf"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-careOf" className="field-label">{t('addressForm.careOf')}</label>
                <input id="af-careOf" {...field} type="text" className="field-input" />
              </div>
            )}
          />
        );
      case 'address1':
        return (
          <Controller
            key={field}
            name="address1"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-address1" className="field-label">
                  {countryFormatter.labels.address1}<span className="req">*</span>
                </label>
                <input id="af-address1" {...field} type="text" required className="field-input" />
              </div>
            )}
          />
        );
      case 'address2':
        return (
          <Controller
            key={field}
            name="address2"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-address2" className="field-label">{countryFormatter.labels.address2}</label>
                <input id="af-address2" {...field} type="text" className="field-input" />
              </div>
            )}
          />
        );
      case 'city':
        return (
          <Controller
            key={field}
            name="city"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-city" className="field-label">
                  {countryFormatter.labels.city}<span className="req">*</span>
                </label>
                <input id="af-city" {...field} type="text" required className="field-input" />
              </div>
            )}
          />
        );
      case 'zip':
        return (
          <Controller
            key={field}
            name="zip"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-zip" className="field-label">
                  {countryFormatter.labels.postalCode}<span className="req">*</span>
                </label>
                <input id="af-zip" {...field} type="text" required className="field-input" />
              </div>
            )}
          />
        );
      case 'province':
        return (countryFormatter.zones && countryFormatter.zones.length > 0 && (
          <Controller
            key={field}
            name="province"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-province" className="field-label">
                  {countryFormatter.labels.zone}<span className="req">*</span>
                </label>
                <select id="af-province" {...field} required className="field-select">
                  <option value="">Select {countryFormatter.labels.zone.toLowerCase()}</option>
                  {provinces.map((province) => (
                    <option key={province.code} value={province.code}>{province.name}</option>
                  ))}
                </select>
              </div>
            )}
          />
        ));
      case 'country':
        return (
          <Controller
            key={field}
            name="country"
            control={control}
            render={({ field }) => (
              <div className="field">
                <label htmlFor="af-country" className="field-label">{t('addressForm.country')}</label>
                <select
                  id="af-country"
                  {...field}
                  className="field-select"
                  onChange={(e) => {
                    field.onChange(e);
                    setValue('country', e.target.value);
                  }}
                >
                  <option value="">{t('addressForm.selectCountry')}</option>
                  {countries.map((country) => (
                    <option key={country.code} value={country.code}>{country.name}</option>
                  ))}
                </select>
              </div>
            )}
          />
        );
      default:
        return null;
    }
  },
    [control, provinces, countries, setValue, countryFormatter, namePrefixes, isDefault, onDefaultChange, isFirstAddress, t]);

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="address-form">
      {error && (
        <div className="cream-note cream-note--error address-form__error" role="alert">
          <strong>{t('addressForm.error')}</strong>{error}
        </div>
      )}

      {renderField('defaultAddress')}
      {renderField('addressTypes')}

      {countryFormatter && (
        <div className="address-form__override">
          <p className="address-form__override-note">
            {t('addressForm.override_address_name')}
          </p>
          {renderField('namePrefix')}
          <div className="field-row">
            {renderField('firstName')}
            {renderField('lastName')}
          </div>
        </div>
      )}

      {renderField('careOf')}
      {renderField('address1')}
      {renderField('address2')}
      <div className="field-row">
        {renderField('city')}
        {renderField('province')}
      </div>
      <div className="field-row">
        {renderField('zip')}
        {renderField('country')}
      </div>

      {address.extraData && address.extraData.keys && address.extraData.keys.length > 0 && (
        <div className="address-form__extras">
          <h4>{t('addressForm.extraFields', 'Extra Fields')}</h4>
          <ul>
            {address.extraData.keys.map((key) => (
              <li key={key}>
                {key}: <b>{address.extraData.data[key]}</b>
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="address-form__actions">
        {onDelete ? (
          <button
            type="button"
            className="btn-destructive-action"
            onClick={() => onDelete(address)}
          >
            {t('addressForm.delete')}
          </button>
        ) : <span />}
        <button type="submit" className="btn-primary-action">
          {t('addressForm.save')}
        </button>
      </div>
    </form>
  );
};

export default AddressForm;
