import React, { useState, useEffect, useContext, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import {
    Box,
    Text,
    Flex,
    Spinner,
    Alert,
    AlertIcon,
    Heading,
    VStack,
    Breadcrumb,
    BreadcrumbItem,
    BreadcrumbLink,
    Button,
    Link as ChakraLink,
    Modal,
    ModalOverlay,
    ModalContent,
    ModalHeader,
    ModalFooter,
    ModalBody,
    ModalCloseButton,
    FormControl,
    FormLabel,
    Input,
    Textarea,
    useDisclosure,
    useToast,
    Image,
} from '@chakra-ui/react';
import { ChevronRightIcon, ExternalLinkIcon } from '@chakra-ui/icons';
import ReCAPTCHA from 'react-google-recaptcha';
import ItemImageGallery from '../components/ItemImageGallery';
import PlaceBid from './PlaceBid';
import FavoriteButton from '../components/FavoriteButton';
import { useDataCache } from '../services/DataCache';
import { handleImageError } from '../utils/imageFallback';
import { googleCalendarUrl, icsDataUri, plainText } from '../utils/calendarLinks';
import { isCacheResetRequested } from '../utils/resetParam';
import DataSourceDebugPanel from '../components/DataSourceDebugPanel';

const ItemPage = ( {itemObject = false, itemId = false, displayMode = 'full', inSale = false, itemDisplayMode = null }) => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { isOpen, onOpen, onClose } = useDisclosure();
    const toast = useToast();
    const { fetchItem, fetchItemJson, submitItemQuestion } = useDataCache();
    const featuredGalleryRef = useRef(null);
    const featuredLgInstance = useRef(null);
    const recaptchaRef = useRef(null);

    // State Management
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [item, setItem] = useState(null);
    const [bsItemId, setBsItemId] = useState(null); // Bid Server item ID (different from itemId prop which is backoffice NID)
    const [isFavorite, setIsFavorite] = useState(false);
    const [isClient, setIsClient] = useState(false);

    // Set client state
    useEffect(() => {
        setIsClient(true);
    }, []);

    // Form state
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        question: ''
    });
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [captchaToken, setCaptchaToken] = useState(null);

    // Open the ask-question modal, prefilling from the logged-in user's
    // profile — the name/email fields are disabled for logged-in users, so
    // without prefill they would be stuck empty and unsubmittable.
    const openAskQuestion = () => {
        if (config.accessToken && config.userData) {
            const fullName = [config.userData.first_name, config.userData.last_name]
                .filter(Boolean).join(' ');
            setFormData(prev => ({
                ...prev,
                name: prev.name || fullName,
                email: prev.email || config.userData.mail || '',
                phone: prev.phone || config.userData.mobile || '',
            }));
        }
        onOpen();
    };

    // "Request images" on image-less lots opens the same modal with the
    // question prefilled — only when the field is still empty, so a draft
    // the user already typed is never overwritten.
    const openRequestImages = () => {
        setFormData(prev => ({
            ...prev,
            question: prev.question || t('itempage.requestImagesPrefill'),
        }));
        openAskQuestion();
    };

    // Effect for fetching data
    useEffect(() => {
        // Fetch Item Data
        const getItemData = async () => {
            setIsLoading(true);
            setError(null);

            try {
                if (!itemId) {
                    throw new Error('No item UUID/ NID provided');
                }

                // Fetch item details using items-json endpoint from DataCache.
                // `?reset=1` on the host page bypasses every cache layer for
                // this item: DataCache memory/localStorage AND the backoffice
                // items-json cache (the endpoint honors `reset`).
                const itemData = await fetchItemJson(itemId, config.siteData.backoffice_url_lang, {
                    reset: isCacheResetRequested(),
                });

                if (itemData) {
                    setItem(itemData);

                    // Fire-and-forget: the render only needs itemData (backoffice).
                    // FavoriteButton hydrates once the bid server responds.
                    if (itemData.sale_uuid) {
                        fetchItem(itemData.uuid, itemData.sale_uuid)
                            .then(cachedItem => {
                                if (cachedItem && cachedItem.id) {
                                    setBsItemId(cachedItem.id);
                                    setIsFavorite(cachedItem.is_favorite || false);
                                }
                            })
                            .catch(cacheErr => {
                                console.error('Failed to fetch bid server item ID from cache:', cacheErr);
                            });
                    }
                } else {
                    throw new Error('Item not found');
                }

            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        if (config.siteData && itemId) {
            getItemData();
        }
        else {
            if (itemObject) {
                setItem(itemObject);

                // Fetch bid server data to get ID and favorite status
                if (itemObject.uuid && itemObject.sale_uuid) {
                    fetchItem(itemObject.uuid, itemObject.sale_uuid)
                        .then(cachedItem => {
                            if (cachedItem && cachedItem.id) {
                                setBsItemId(cachedItem.id);
                                setIsFavorite(cachedItem.is_favorite || false);
                            }
                        })
                        .catch(err => {
                            console.error('Failed to fetch bid server item data:', err);
                        });
                } else if (itemObject.id) {
                    // Fallback: if itemObject already has id (shouldn't happen from Sale page)
                    setBsItemId(itemObject.id);
                    if (itemObject.is_favorite !== undefined) {
                        setIsFavorite(itemObject.is_favorite);
                    }
                }

                setIsLoading(false);
            }
        }
    }, [itemObject, itemId, config.siteData, i18n.language, fetchItem, fetchItemJson]);

    // Build breadcrumb category tree
    const getCategoryTree = () => {
        if (!item?.item_taxonomy?.field_category?.ancestors) return [];

        return item.item_taxonomy.field_category.ancestors.map(cat => ({
            name: cat.name_field?.[i18n.language]?.[0]?.value || cat.name,
            tid: cat.tid
        }));
    };

    // Build category filter URL for breadcrumbs
    const buildCategoryUrl = (categoryIndex) => {
        if (!item?.sale_url) return '#';

        const categoryTree = getCategoryTree();
        // Get all category TIDs from root to current index (inclusive)
        const tids = categoryTree.slice(0, categoryIndex + 1).map(cat => cat.tid);

        // Build the filter parameter string
        const filterValues = tids.join(',');
        const filterParams = `filter[field_category][values]=${filterValues}&filter[field_category][operator]=IN`;

        return `${item.sale_url}?${filterParams}`;
    };


    // Handle form input changes
    const handleFormChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // Handle favorite toggle - update local state when favorite changes
    const handleFavoriteToggle = (newIsFavorite) => {
        // FavoriteButton handles the API call, we just update local state
        setIsFavorite(newIsFavorite);
        setItem(prev => ({
            ...prev,
            is_favorite: newIsFavorite
        }));
    };

    // Handle form submission
    const handleSubmitQuestion = async (e) => {
        e.preventDefault();

        // Validate required fields
        if (!formData.name.trim() || !formData.email.trim() || !formData.question.trim()) {
            toast({
                title: t('itempage.messages.missingFields'),
                description: t('itempage.messages.missingFieldsDescription'),
                status: 'error',
                duration: 5000,
                isClosable: true,
            });
            return;
        }

        // The backend verifies the token whenever its secret is configured;
        // require the widget here whenever the site key is configured.
        if (config.recaptchaKey && !captchaToken) {
            toast({
                title: t('itempage.messages.captchaRequired'),
                description: t('itempage.messages.captchaRequiredDescription'),
                status: 'error',
                duration: 5000,
                isClosable: true,
            });
            return;
        }

        setIsSubmitting(true);

        try {
            // Submit question using DataCache
            await submitItemQuestion(config.siteData.backoffice_url_lang || config.siteData.backoffice_url, {
                item_uuid: item?.uuid || '',
                item_title: item?.title || '',
                lot_number: item?.lot_number || '',
                name: formData.name,
                email: formData.email,
                phone: formData.phone,
                question: formData.question,
                recaptcha_token: captchaToken || '',
            });

            toast({
                title: t('itempage.messages.questionSubmitted'),
                description: t('itempage.messages.questionSubmittedDescription'),
                status: 'success',
                duration: 5000,
                isClosable: true,
            });

            onClose();
            // Reset form
            setFormData({
                name: '',
                email: '',
                phone: '',
                question: ''
            });
            setCaptchaToken(null);
            recaptchaRef.current?.reset();
        } catch (err) {
            // A used token is spent — force a fresh solve for the retry.
            setCaptchaToken(null);
            recaptchaRef.current?.reset();
            toast({
                title: t('itempage.messages.submitError'),
                description: err.message || t('itempage.messages.submitErrorDescription'),
                status: 'error',
                duration: 5000,
                isClosable: true,
            });
        } finally {
            setIsSubmitting(false);
        }
    };

    // Initialize lightGallery for featured mode
    useEffect(() => {
        if (!isClient || displayMode !== 'featured' || !featuredGalleryRef.current || !item?.image_gallery?.images_path) {
            return;
        }

        const initGallery = async () => {
            try {
                const lightGallery = (await import('lightgallery')).default;
                const lgZoom = (await import('lightgallery/plugins/zoom')).default;

                await import('lightgallery/css/lightgallery.css');
                await import('lightgallery/css/lg-zoom.css');

                if (featuredGalleryRef.current && !featuredLgInstance.current) {
                    if (featuredLgInstance.current) {
                        featuredLgInstance.current.destroy();
                    }

                    featuredLgInstance.current = lightGallery(featuredGalleryRef.current, {
                        licenseKey: 'LIG-855CEE25-6856-4181-9A1C-125171EDE6BD',
                        plugins: [lgZoom],
                        speed: 500,
                        download: false,
                        mode: 'lg-fade',
                        counter: true,
                        dynamic: true,
                        dynamicEl: item.image_gallery.images_path.map((image, index) => ({
                            src: image.zoom || image.big,
                            thumb: image.small,
                            subHtml: `<h4>Image ${index + 1} of ${item.image_gallery.images_path.length}</h4>`,
                        })),
                        zoom: true,
                        actualSize: true,
                        showZoomInOutIcons: true,
                        enableZoom: true,
                        enableTouch: true,
                    });
                }
            } catch (error) {
                console.error('Failed to initialize lightGallery for featured mode:', error);
            }
        };

        initGallery();

        return () => {
            if (featuredLgInstance.current) {
                featuredLgInstance.current.destroy();
                featuredLgInstance.current = null;
            }
        };
    }, [isClient, displayMode, item]);

    if (isLoading) {
        return (
            <Flex width="100%" height="400px" justifyContent="center" alignItems="center">
                <Spinner color="blue.500" size="xl" thickness="4px"/>
            </Flex>
        );
    }

    if (error) {
        return (
            <div className="item-error-page">
                <div className="item-error-page__card">
                    <div className="item-error-page__icon" aria-hidden="true">
                        <svg width="44" height="44" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                            <circle cx="12" cy="12" r="10" />
                            <line x1="12" y1="8" x2="12" y2="12" />
                            <line x1="12" y1="16" x2="12.01" y2="16" />
                        </svg>
                    </div>
                    <h1 className="item-error-page__title">
                        {t('itempage.errorTitle', { defaultValue: "We couldn't load this lot" })}
                    </h1>
                    <p className="item-error-page__lead">
                        {t('itempage.errorLead', {
                            defaultValue: 'Something went wrong while fetching the lot details. This is usually temporary — please try again in a moment.',
                        })}
                    </p>
                    <div className="item-error-page__detail">
                        <span className="item-error-page__detail-label">
                            {t('itempage.error', { defaultValue: 'Error' })}
                        </span>
                        <span className="item-error-page__detail-msg">{error}</span>
                    </div>
                    <div className="item-error-page__actions">
                        <button
                            type="button"
                            className="bid-limit-submit"
                            onClick={() => window.location.reload()}
                        >
                            {t('itempage.tryAgain', { defaultValue: 'Try Again' })}
                        </button>
                        <a href="/" className="btn-secondary-action">
                            {t('itempage.goHome', { defaultValue: 'Go to Home' })}
                        </a>
                    </div>
                </div>
            </div>
        );
    }

    if (!item) {
        return (
            <div className="item-error-page">
                <div className="item-error-page__card">
                    <div className="item-error-page__icon item-error-page__icon--muted" aria-hidden="true">
                        <svg width="44" height="44" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                            <circle cx="11" cy="11" r="8" />
                            <line x1="21" y1="21" x2="16.65" y2="16.65" />
                        </svg>
                    </div>
                    <h1 className="item-error-page__title">
                        {t('itempage.itemNotFoundTitle', { defaultValue: 'Lot not found' })}
                    </h1>
                    <p className="item-error-page__lead">
                        {t('itempage.itemNotFound')}
                    </p>
                    <div className="item-error-page__actions">
                        <a href="/" className="bid-limit-submit">
                            {t('itempage.goHome', { defaultValue: 'Go to Home' })}
                        </a>
                    </div>
                </div>
            </div>
        );
    }

    const categoryTree = getCategoryTree();
    const shouldShowPlaceBid = !item.withdrawn_hide;
    const isWithdrawnHidden = item.withdrawn && item.withdrawn_hide;
    // Session date: a non-empty override replaces the regular session date.
    const saleSessionDate = item.sale_session_date_override?.trim() || item.sale_session_date?.trim() || '';

    return (
        <Box maxW="1920px" mx="auto" p={displayMode === 'grid' ? 0 : 4} className="item-page" id="item-page" position="relative" data-display-mode={displayMode}>
            {/* ?debug=1 data-source panel — standalone item page only (grid
                tiles are many ItemPage instances; the Sale page mounts its
                own single panel). */}
            {displayMode === 'full' && <DataSourceDebugPanel />}
            {/* Withdrawn Overlay - Over entire page */}
            {item.withdrawn && !isWithdrawnHidden && (
                <Box
                    position="absolute"
                    top="20%"
                    left="50%"
                    transform="translate(-50%, -50%) rotate(-45deg)"
                    zIndex={1000}
                    pointerEvents="none"
                    className="item-withdrawn-overlay"
                    id="item-withdrawn-overlay"
                >
                    <Text
                        fontSize={["2xl", "3xl", "4xl", "6xl"]}
                        fontWeight="bold"
                        color="red.600"
                        backgroundColor="rgba(128, 128, 128, 0.3)"
                        padding={["10px 20px", "15px 30px", "20px 60px"]}
                        textTransform="uppercase"
                        whiteSpace="nowrap"
                    >
                        {t('itempage.withdrawn')}
                    </Text>
                </Box>
            )}

            {/* Breadcrumbs - Only show in full mode */}
            {displayMode === 'full' && (
                <Breadcrumb
                    spacing="8px"
                    separator={<ChevronRightIcon color="gray.500" />}
                    fontSize="sm"
                    className="item-breadcrumbs"
                    id="item-breadcrumbs"
                    sx={{
                        '& .chakra-breadcrumb__list': {
                            display: 'flex',
                            flexWrap: 'wrap'
                        }
                    }}
                >
                <BreadcrumbItem>
                    <BreadcrumbLink href="/">{t('itempage.home')}</BreadcrumbLink>
                </BreadcrumbItem>

                {item.sale_title && (
                    <BreadcrumbItem>
                        <BreadcrumbLink href={`${item.sale_url}`} dangerouslySetInnerHTML={{ __html: item.sale_title }} />
                    </BreadcrumbItem>
                )}

                {categoryTree.map((cat, index) => (
                    <BreadcrumbItem key={cat.tid}>
                        <BreadcrumbLink href={buildCategoryUrl(index)}>{cat.name}</BreadcrumbLink>
                    </BreadcrumbItem>
                ))}

                <BreadcrumbItem isCurrentPage>
                    <BreadcrumbLink>{t('itempage.lot', { number: item.lot_number })}</BreadcrumbLink>
                </BreadcrumbItem>
            </Breadcrumb>
            )}

            {/* Main lot card — wraps header, gallery, pricing, description,
                and metadata in a single surface so the layout matches the
                .lot-info / .favorite-lot card design. Renders in all
                display modes (full / teaser / grid / featured). Prev/next
                below are full-only siblings. In grid mode the tile carries
                a native tooltip with the lot description, which the tile
                itself has no room to render (HK punch list #15). */}
            <section
                className="item-page__card"
                title={
                    displayMode === 'grid' && item.body
                        ? `${item.body.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300)}`
                        : undefined
                }>

            {/* Grid-only top bar — lot number (left) + favorite button
                (right) on a single row above the gallery. Other display
                modes keep the lot number inside .item-header and the
                favorite button overlaid, so this block is grid-only. */}
            {displayMode === 'grid' && (
                <Box className="item-grid-topbar" id="item-grid-topbar">
                    <Heading
                        as={ChakraLink}
                        href={`${item.url}`}
                        size="md"
                        className="item-lot-info"
                        id="item-lot-info"
                    >
                        <span className="item-lot-number" id="item-lot-number">{t('itempage.lot', { number: item.lot_number })}</span>
                        {item.sold_status_class === 'sold' && <span className="item-status item-status-sold" id="item-status-sold">SOLD</span>}
                        {item.withdrawn && <span className="item-status item-status-withdrawn" id="item-status-withdrawn">WITHDRAWN</span>}
                    </Heading>
                    {config.accessToken && bsItemId && (
                        <Box className="item-favorite" id="item-favorite">
                            <FavoriteButton
                                itemId={bsItemId}
                                initialIsFollowing={isFavorite}
                                onFavoriteChange={handleFavoriteToggle}
                                displayMode={displayMode}
                            />
                        </Box>
                    )}
                </Box>
            )}

            {/* Gallery — rendered as a sibling of the body wrapper so
                its height never affects the body's internal spacing.
                Not rendered when the lot is withdrawn-and-hidden. */}
            {!isWithdrawnHidden && (
                <Box className="item-gallery" id="item-gallery">
                    {displayMode === 'featured' ? (
                        <Box
                            ref={featuredGalleryRef}
                            onClick={() => {
                                if (featuredLgInstance.current) {
                                    try {
                                        featuredLgInstance.current.openGallery(0);
                                    } catch (error) {
                                        console.error('Error opening gallery:', error);
                                    }
                                } else {
                                    console.warn('Gallery not initialized yet');
                                }
                            }}
                            cursor="pointer"
                            position="relative"
                            _hover={{ opacity: 0.9 }}
                            transition="opacity 0.2s"
                        >
                            {item.image_gallery?.images_path && item.image_gallery.images_path.length > 0 ? (
                                <Image
                                    src={item.image_gallery.images_path[0]?.big || item.image_gallery.images_path[0]}
                                    onError={handleImageError}
                                    alt={item.title || `Lot ${item.lot_number}`}
                                    width="100%"
                                    objectFit="contain"
                                    maxH="500px"
                                    loading="lazy"
                                />
                            ) : (
                                <Box
                                    width="100%"
                                    height="300px"
                                    bg="gray.100"
                                    display="flex"
                                    alignItems="center"
                                    justifyContent="center"
                                >
                                    <Text color="gray.500">{t('item.noMedia', { defaultValue: 'No media available' })}</Text>
                                </Box>
                            )}
                        </Box>
                    ) : (
                        <ItemImageGallery
                            images={item.image_gallery?.images_path || []}
                            displayMode={displayMode}
                            hideNavigation={itemDisplayMode === 'lot-number'}
                        />
                    )}

                    {/* Image-less lot on the full page: offer "Request images",
                        which opens the ask-question modal prefilled. Same
                        usable-media predicate as ItemImageGallery's sanitize,
                        so this appears exactly when the placeholder does. */}
                    {displayMode === 'full' &&
                        !(item.image_gallery?.images_path || []).some(
                            (media) => media && (media.big || media.small || media.video_url || media.pdf_url),
                        ) && (
                        <Box className="item-request-images" id="item-request-images">
                            <button
                                type="button"
                                className="btn-secondary-action"
                                onClick={openRequestImages}
                                id="item-request-images-button"
                            >
                                {t('itempage.requestImages')}
                            </button>
                        </Box>
                    )}
                </Box>
            )}

            {/* Body wrapper — flex column. Gallery is a sibling above,
                so the body's items stack tight regardless of gallery
                height. */}
            <div className="item-page__body">

            {/* Item Header - Full Width */}
            <Box mb={4} className="item-header" id="item-header">
                {/* Lot number row: number/status left, favorite heart right —
                    same layout as the grid tile's topbar (HK punch list #7).
                    In grid mode both render in .item-grid-topbar above the
                    gallery instead, so this row is skipped there. */}
                {displayMode !== 'grid' && (
                    <Box className="item-header-row">
                        <Heading
                            as="h3"
                            size="md"
                            className="item-lot-info"
                            id="item-lot-info"
                            {...(displayMode === 'teaser' || displayMode === 'featured' ? {
                                as: ChakraLink,
                                href: `${item.url}`
                            } : {})}
                        >
                            <span className="item-lot-number" id="item-lot-number">{t('itempage.lot', { number: item.lot_number })}</span>
                            {item.sold_status_class === 'sold' && <span className="item-status item-status-sold" id="item-status-sold">SOLD</span>}
                            {item.withdrawn && <span className="item-status item-status-withdrawn" id="item-status-withdrawn">WITHDRAWN</span>}
                        </Heading>
                        {displayMode !== 'featured' && config.accessToken && bsItemId && (
                            <Box className="item-favorite" id="item-favorite">
                                <FavoriteButton
                                    itemId={bsItemId}
                                    initialIsFollowing={isFavorite}
                                    onFavoriteChange={handleFavoriteToggle}
                                    displayMode={displayMode}
                                />
                            </Box>
                        )}
                    </Box>
                )}

                {/* Render title - Hidden when itemDisplayMode is 'lot-number' */}
                {itemDisplayMode !== 'lot-number' && !!item.show_title && item.title && (
                    displayMode === 'featured' || displayMode === 'teaser' || displayMode === 'grid' ? (
                        <ChakraLink href={`${item.url}`} >
                            <Heading as="h1" size="xl" mb={2} className="item-title" id="item-title" >
                                {item.title}
                            </Heading>
                        </ChakraLink>
                    ) : (
                        <Heading as="h1" size="xl" mb={2} className="item-title" id="item-title">
                            {item.title}
                        </Heading>
                    )
                )}

                {/* Render subtitle for teaser, grid, and full modes - Hidden when itemDisplayMode is 'lot-number' */}
                {itemDisplayMode !== 'lot-number' && !!item.show_title && item.subtitle && displayMode !== 'featured' && (
                    displayMode === 'teaser' || displayMode === 'grid' ? (
                        <ChakraLink href={`${item.url}`} >
                            <Heading as="h2" size="lg" fontWeight="normal"  mb={2} className="item-subtitle" id="item-subtitle" >
                                {item.subtitle}
                            </Heading>
                        </ChakraLink>
                    ) : (
                        <Heading as="h2" size="lg" fontWeight="normal" color="gray.600" mb={2} className="item-subtitle" id="item-subtitle">
                            {item.subtitle}
                        </Heading>
                    )
                )}

                {/* Public Message - Hidden in grid and featured modes */}
                {displayMode !== 'grid' && displayMode !== 'featured' && item.public_message && (
                    <Alert status="info" className="item-public-message" id="item-public-message" mb={4} width="fit-content">
                        <AlertIcon />
                        <Box dangerouslySetInnerHTML={{ __html: item.public_message }} />
                    </Alert>
                )}

                {/* Favorite button moved into .item-header-row above (heart
                    right-aligned to the lot number, like the grid tile). */}
            </Box>

            {/* Main Content */}
            {isWithdrawnHidden ? (
                /* Withdrawn and Hidden - Show only withdrawn message */
                <Box textAlign="center" py={[10, 15, 20]} className="item-withdrawn-hidden" id="item-withdrawn-hidden">
                    <Box
                        display="inline-block"
                        transform="rotate(-45deg)"
                        mb={[4, 6, 8]}
                    >
                        <Text
                            fontSize={["2xl", "3xl", "4xl", "6xl"]}
                            fontWeight="bold"
                            color="red.600"
                            backgroundColor="rgba(128, 128, 128, 0.8)"
                            padding={["10px 20px", "15px 30px", "20px 60px"]}
                            textTransform="uppercase"
                            whiteSpace="nowrap"
                        >
                            {t('itempage.withdrawn')}
                        </Text>
                    </Box>
                    <Text fontSize={["sm", "md", "lg"]} color="gray.600" mt={4}>
                        {t('itempage.withdrawnMessage')}
                    </Text>
                </Box>
            ) : (
                <>
                    {/* Pricing and Bid Wrapper - Hidden when itemDisplayMode is 'lot-number' */}
                    {itemDisplayMode !== 'lot-number' && (
                    <Box className="item-pricing-bid-wrapper" id="item-pricing-bid-wrapper">
                        {/* Price Information */}
                        <Box borderWidth="1px" borderRadius="md" className="item-pricing" id="item-pricing">
                            {item.opening_price && !item.withdrawn_hide && (
                                <Text className="item-price-opening" id="item-price-opening">
                                    <Text as="span" fontWeight="semibold">{t('itempage.pricing.opening')}: </Text>
                                    <Text as="span" className="item-price-opening-value" id="item-price-opening-value">{item.opening_price}</Text>
                                </Text>
                            )}

                            {item.estimation && (
                                <Text className="item-price-estimate" id="item-price-estimate">
                                    <Text as="span" fontWeight="semibold">{t('itempage.pricing.estimate')}: </Text>
                                    <Text as="span" className="item-price-estimate-value" id="item-price-estimate-value">{item.estimation}</Text>
                                </Text>
                            )}

                            {item.retail_price && (
                                <Text className="item-price-retail" id="item-price-retail">
                                    <Text as="span" fontWeight="semibold">{t('itempage.pricing.retail')}: </Text>
                                    <Text as="span" className="item-price-retail-value" id="item-price-retail-value">{item.retail_price}</Text>
                                </Text>
                            )}
                        </Box>

                        {/* Place Bid Component */}
                        {shouldShowPlaceBid && (
                            <Box borderWidth="1px" borderRadius="md" className="item-place-bid" id="item-place-bid">
                                <PlaceBid
                                    saleUuid={item.sale_uuid}
                                    itemUuid={item.uuid}
                                    itemObject={item}
                                />
                            </Box>
                        )}

                        {/* Ask a question about this item — full item page and
                            the sale list (teaser) view. */}
                        {(displayMode === 'full' || displayMode === 'teaser') && (
                            <Box className="item-ask-question" id="item-ask-question" mt={3}>
                                <button
                                    type="button"
                                    className="btn-secondary-action"
                                    onClick={openAskQuestion}
                                    id="item-ask-question-button"
                                >
                                    {t('itempage.askQuestion')}
                                </button>
                            </Box>
                        )}
                    </Box>
                    )}

                    {/* Certificate Links - Only in grid mode */}
                    {displayMode === 'grid' && item.certificate_link && item.certificate_link.some(cert => cert.url || cert.title) && (
                        <Flex className="item-certificates" id="item-certificates" mb={4} alignItems="baseline" flexWrap="wrap" gap={2}>
                            <Heading size="sm" mb={0} mt={0}>
                                <span className="fa-stack cert-badge-icon">
                                    <i className="fa fa-certificate fa-stack-2x" style={{color: '#1a96f0'}}></i>
                                    <i className="fa fa-check fa-stack-1x fa-inverse"></i>
                                </span>
                                {t('itempage.certificates')}
                            </Heading>
                            {item.certificate_link.filter(cert => cert.url || cert.title).map((cert, idx) => (
                                <Button
                                    key={idx}
                                    as="a"
                                    href={cert.url}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    size="sm"
                                    variant="link"
                                    rightIcon={<ExternalLinkIcon />}
                                    className="item-certificate-link"
                                    id={`item-certificate-link-${idx}`}
                                >
                                    {cert.title || cert.url}
                                </Button>
                            ))}
                        </Flex>
                    )}

                    {/* View More Details Link - Only in grid mode */}
                    {displayMode === 'grid' && (
                        <Box textAlign="center" mb={4} className="item-grid-link">
                            <ChakraLink
                                href={`${item.url}`}
                                color="blue.600"
                                fontWeight="semibold"
                                fontSize="lg"
                                _hover={{ color: 'blue.700', textDecoration: 'underline' }}
                            >
                                {t('itempage.viewMoreDetails')}
                            </ChakraLink>
                        </Box>
                    )}

                    {/* Content sections - Hidden in grid and featured modes */}
                    {displayMode !== 'grid' && displayMode !== 'featured' && (
                    <>
                    {/* Content Wrapper */}
                    <Box className="item-content-wrapper" id="item-content-wrapper">
                        {/* Description */}
                        {item.body && (
                            <Box className="item-description" id="item-description" mb={4} dangerouslySetInnerHTML={{ __html: item.body }} />
                        )}

                        {/* Footer summary — short addendum below the description, no label. */}
                        {item.footer_summary && (
                            <Box className="item-footer-summary" id="item-footer-summary" mb={4} dangerouslySetInnerHTML={{ __html: item.footer_summary }} />
                        )}

                        {/* Footer */}
                        {item.footer && (
                            <Box className="item-footer" id="item-footer" mb={4}>
                                <Box dangerouslySetInnerHTML={{ __html: item.footer }} />
                            </Box>
                        )}

                        {/* Provenance */}
                        {item.provenance && (
                            <Box className="item-provenance" id="item-provenance" mb={4}>
                                <Heading size="sm" mb={2}>{t('itempage.provenance')}</Heading>
                                <Box dangerouslySetInnerHTML={{ __html: item.provenance }} />
                            </Box>
                        )}

                        {/* Caption */}
                        {item.caption && (
                            <Box className="item-caption" id="item-caption" mb={4}>
                                <Heading size="sm" mb={2}>{t('itempage.caption')}</Heading>
                                <Box dangerouslySetInnerHTML={{ __html: item.caption }} />
                            </Box>
                        )}

                        {/* Essay */}
                        {item.essay && (
                            <Box className="item-essay" id="item-essay" mb={4}>
                                <Heading size="sm" mb={2}>{t('itempage.essay')}</Heading>
                                <Box dangerouslySetInnerHTML={{ __html: item.essay }} />
                            </Box>
                        )}

                        {/* Literature */}
                        {item.literature && (
                            <Box className="item-literature" id="item-literature" mb={4}>
                                <Heading size="sm" mb={2}>{t('itempage.literature')}</Heading>
                                <Box dangerouslySetInnerHTML={{ __html: item.literature }} />
                            </Box>
                        )}
                    </Box>

                    {/* Metadata Wrapper */}
                    <Box className="item-metadata-wrapper" id="item-metadata-wrapper">
                        {/* Dimensions */}
                        {item.dimensions && (
                            <Box className="item-dimensions" id="item-dimensions" mb={4}>
                                <Text>
                                    <Text as="span" fontWeight="semibold">{t('itempage.dimensions')}: </Text>
                                    <Text as="span">{item.dimensions}</Text>
                                </Text>
                            </Box>
                        )}

                        {/* Grade */}
                        {item.grade && (
                            <Box className="item-grade" id="item-grade" mb={4}>
                                <Text>
                                    <Text as="span" fontWeight="semibold">{t('itempage.grade')}: </Text>
                                    <Text as="span">{item.grade}</Text>
                                </Text>
                            </Box>
                        )}

                        {/* Country */}
                        {item.country && (
                            <Box className="item-country" id="item-country" mb={4}>
                                <Text>
                                    <Text as="span" fontWeight="semibold">{t('itempage.country')}: </Text>
                                    <Text as="span">{item.country}</Text>
                                </Text>
                            </Box>
                        )}

                        {/* Year */}
                        {item.year && (
                            <Box className="item-year" id="item-year" mb={4}>
                                <Text>
                                    <Text as="span" fontWeight="semibold">{t('itempage.year')}: </Text>
                                    <Text as="span">{item.year}</Text>
                                </Text>
                            </Box>
                        )}

                        {/* Taxonomy Items */}
                        {item.item_taxonomy && Object.entries(item.item_taxonomy).map(([key, taxonomy]) => {
                            // Special handling for catalogue_name_and_number
                            if (key === 'catalogue_name_and_number' && taxonomy?.data && Array.isArray(taxonomy.data) && taxonomy.data.length > 0) {
                                return (
                                    <Box key={key} className={`item-taxonomy item-taxonomy-${key}`} id={`item-taxonomy-${key}`} mb={4}>
                                        {taxonomy.data.map((catalog, idx) => (
                                            <Text key={idx} mb={1}>
                                                <Text as="span" fontWeight="semibold">{t('itempage.catalogue')}: </Text>
                                                {catalog.name} {catalog.number}
                                                {catalog.value && parseFloat(catalog.value) !== 0 && (
                                                    <Text as="span" ml={2}>
                                                        <Text as="span" fontWeight="semibold">{t('itempage.catalogueValue')}: </Text>${catalog.value}
                                                    </Text>
                                                )}
                                            </Text>
                                        ))}
                                    </Box>
                                );
                            }

                            // Skip catalogue_value since it's displayed with catalogue_name_and_number
                            if (key === 'catalogue_value') {
                                return null;
                            }

                            // Special handling for symbols — `rendered` is the
                            // pre-aggregated glyph string for the icon font
                            // referenced by `class_wrapper` (aukphila/ngai).
                            if (key === 'symbols') {
                                if (!taxonomy?.rendered || !taxonomy.rendered.trim()) return null;
                                return (
                                    <Box key={key} className={`item-taxonomy item-taxonomy-${key}`} id={`item-taxonomy-${key}`} mb={4}>
                                        <Text>
                                            {taxonomy.label && <Text as="span" fontWeight="semibold">{taxonomy.label}: </Text>}
                                            <Text as="span" className={taxonomy.class_wrapper}>
                                                {taxonomy.rendered}
                                            </Text>
                                        </Text>
                                    </Box>
                                );
                            }

                            // Special handling for mediums
                            if (key === 'field_mediums' && taxonomy?.rendered && taxonomy.rendered.trim()) {
                                return (
                                    <Box key={key} className={`item-taxonomy item-taxonomy-${key}`} id={`item-taxonomy-${key}`} mb={4}>
                                        <Text>
                                            <Text as="span" fontWeight="semibold">{t('itempage.medium')}: </Text>
                                            <Text as="span" dangerouslySetInnerHTML={{ __html: taxonomy.rendered }} />
                                        </Text>
                                    </Box>
                                );
                            }

                            // Special handling for category - show full category tree
                            if (key === 'field_category' && taxonomy?.ancestors && Array.isArray(taxonomy.ancestors) && taxonomy.ancestors.length > 0) {
                                return (
                                    <Box key={key} className={`item-taxonomy item-taxonomy-${key}`} id={`item-taxonomy-${key}`} mb={4}>
                                        <Text>
                                            <Text as="span" fontWeight="semibold">{t('itempage.category')}: </Text>
                                            {taxonomy.ancestors.map((cat, idx) => (
                                                <React.Fragment key={cat.tid}>
                                                    {idx > 0 && ' > '}
                                                    <Text as="span">
                                                        {cat.name_field?.[i18n.language]?.[0]?.value || cat.name}
                                                    </Text>
                                                </React.Fragment>
                                            ))}
                                        </Text>
                                    </Box>
                                );
                            }

                            // Regular taxonomy items with rendered HTML
                            if (taxonomy?.rendered && taxonomy.rendered.trim()) {
                                return (
                                    <Box key={key} className={`item-taxonomy item-taxonomy-${key}`} id={`item-taxonomy-${key}`} mb={4}>
                                        <Text>
                                            {taxonomy.label && <Text as="span" fontWeight="semibold">{taxonomy.label}: </Text>}
                                            <Text as="span" dangerouslySetInnerHTML={{ __html: taxonomy.rendered }} />
                                        </Text>
                                    </Box>
                                );
                            }
                            return null;
                        })}

                        {/* Certificate Links */}
                        {item.certificate_link && item.certificate_link.some(cert => cert.url || cert.title) && (
                            <Box className="item-certificates" id="item-certificates" mb={4}>
                                <Heading size="sm" mb={3}>
                                    <span className="fa-stack cert-badge-icon">
                                        <i className="fa fa-certificate fa-stack-2x" style={{color: '#1a96f0'}}></i>
                                        <i className="fa fa-check fa-stack-1x fa-inverse"></i>
                                    </span>
                                    {t('itempage.certificates')}
                                </Heading>
                                {item.certificate_link.filter(cert => cert.url || cert.title).map((cert, idx) => (
                                    <Button
                                        key={idx}
                                        as="a"
                                        href={cert.url}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        size="sm"
                                        variant="link"                                        
                                        rightIcon={<ExternalLinkIcon />}
                                        justifyContent="space-between"
                                        className="item-certificate-link"
                                        id={`item-certificate-link-${idx}`}
                                        mb={2}
                                        display="block"
                                    >
                                        {cert.title || cert.url}
                                    </Button>
                                ))}
                            </Box>
                        )}                    

                        {/* Reference Links */}
                        {item.reference_link && item.reference_link.some(ref => ref.url || ref.title) && (
                            <Box className="item-references" id="item-references" mb={4}>
                                <Heading size="sm" mb={3}>{t('itempage.references')}</Heading>
                                {item.reference_link.filter(ref => ref.url || ref.title).map((ref, idx) => (
                                    <Button
                                        key={idx}
                                        as="a"
                                        href={ref.url}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        size="sm"
                                        variant="link"
                                        rightIcon={<ExternalLinkIcon />}
                                        justifyContent="space-between"
                                        className="item-reference-link"
                                        id={`item-reference-link-${idx}`}
                                        mb={2}
                                        display="block"
                                    >
                                        {ref.title || ref.url}
                                    </Button>
                                ))}
                            </Box>
                        )}

                        {/* Tax Warning */}
                        {item.taxwarning && item.taxwarning.length > 0 && (
                            <Alert status="warning" className="item-tax-warning" id="item-tax-warning" mb={4}>
                                <AlertIcon />
                                <Box>
                                    {item.taxwarning.map((warning, idx) => (
                                        <Text key={idx} fontSize="sm">{warning}</Text>
                                    ))}
                                </Box>
                            </Alert>
                        )}
                    </Box>

                    {/* Ask About This Item - hidden until endpoint is available */}
                    </>
                    )}
                </>
            )}

            {/* Sale-wrapper — pinned to the bottom of the body column
                for teaser/grid when NOT inside a sale page. Rendered
                last so it sits beneath all other body content. */}
            {(displayMode === 'teaser' || displayMode === 'grid') && !inSale && item.sale_uuid && item.sale_title && (
                <a
                    href={item.sale_url}
                    className="item-sale-wrapper"
                    id="item-sale-wrapper"
                >
                    <span className="item-sale-wrapper__label">
                        {t('itempage.fromSale', { defaultValue: 'From Sale' })}
                    </span>
                    <span
                        className="item-sale-wrapper__title"
                        dangerouslySetInnerHTML={{ __html: item.sale_title }}
                    />
                    {item.sale_date_location && (
                        <span
                            className="item-sale-wrapper__meta"
                            dangerouslySetInnerHTML={{ __html: item.sale_date_location }}
                        />
                    )}
                </a>
            )}
            {/* Auction-date info — collapsible accordion (closed by
                default), INSIDE the lot card: the "when is this lot
                auctioned" info belongs to the lot (HK punch list #17).
                Shown on the full detail page AND on list (teaser) rows —
                the data condition below keeps it away from tiles whose
                item feed lacks the sale/session fields. */}
            {(displayMode === 'full' || displayMode === 'teaser') && !isWithdrawnHidden && item.sale_uuid && (item.sale_title || item.sale_description) && (
              <details className="item-sale-accordion">
                <summary className="item-sale-accordion__summary">
                  <span className="item-sale-accordion__label">
                    {t('itempage.saleInformation', { defaultValue: 'When will this lot be auctioned?' })}
                  </span>
                  <span className="item-sale-accordion__chevron" aria-hidden="true">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="6 9 12 15 18 9" />
                    </svg>
                  </span>
                </summary>
                <div className="item-sale-accordion__body">
                  {item.sale_title && (
                    <h3
                      className="item-sale-accordion__title"
                      dangerouslySetInnerHTML={{ __html: item.sale_title }}
                    />
                  )}
                  {item.sale_subtitle && (
                    <p className="item-sale-accordion__subtitle" dangerouslySetInnerHTML={{ __html: item.sale_subtitle }} />
                  )}
                  {item.sale_date_location && (
                    <p className="item-sale-accordion__meta" dangerouslySetInnerHTML={{ __html: item.sale_date_location }} />
                  )}
                  {(item.sale_session_name || saleSessionDate) && (
                    <p className="item-sale-accordion__meta item-sale-accordion__session">
                      <strong>{t('itempage.saleSession', { defaultValue: 'Session' })}: </strong>
                      {item.sale_session_name}
                      {item.sale_session_name && saleSessionDate ? ' — ' : ''}
                      {saleSessionDate}
                    </p>
                  )}
                  {/* Add-to-calendar — only when a machine-readable session
                      start exists (a free-text date override can't become a
                      calendar event). Google deep link + agnostic .ics. */}
                  {!!parseInt(item.sale_session_timestamp, 10) && (() => {
                    const calendarEvent = {
                      title: [plainText(item.sale_title), item.sale_session_name, t('itempage.lot', { number: item.lot_number })]
                        .filter(Boolean).join(' — '),
                      start: parseInt(item.sale_session_timestamp, 10),
                      end: parseInt(item.sale_session_timestamp_end, 10) || undefined,
                      details: item.url ? new URL(item.url, window.location.origin).href : '',
                      location: plainText(item.sale_date_location),
                    };
                    return (
                      <p className="item-sale-accordion__calendar">
                        <span className="item-sale-accordion__calendar-label">
                          {t('itempage.addToCalendar', { defaultValue: 'Add to my calendar' })}:
                        </span>
                        <a
                          href={googleCalendarUrl(calendarEvent)}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="item-sale-accordion__calendar-link"
                        >
                          Google Calendar
                        </a>
                        <a
                          href={icsDataUri({ ...calendarEvent, uid: `${item.uuid || item.lot_number}-session@circuitauction.com` })}
                          download="auction-session.ics"
                          className="item-sale-accordion__calendar-link"
                        >
                          {t('itempage.addToCalendarIcs', { defaultValue: 'Apple / Outlook (.ics)' })}
                        </a>
                      </p>
                    );
                  })()}
                  {item.sale_description && (
                    <div className="item-sale-accordion__description" dangerouslySetInnerHTML={{ __html: item.sale_description }} />
                  )}
                </div>
              </details>
            )}
            </div>
              </section>

            {/* Previous/Next Navigation — sits OUTSIDE the lot card so
                the chevrons are always clearly visible. */}
            {displayMode === 'full' && !isWithdrawnHidden && (item.previous_lot || item.next_lot) && (
              <nav className="item-lot-navigation" aria-label="Lot navigation">
                {item.previous_lot ? (
                  <a href={`${item.previous_lot_url}`} className="item-lot-navigation__btn item-lot-navigation__btn--prev">
                    ← {t('itempage.previousLot')}
                  </a>
                ) : <span />}
                {item.next_lot && (
                  <a href={`${item.next_lot_url}`} className="item-lot-navigation__btn item-lot-navigation__btn--next">
                    {t('itempage.nextLot')} →
                  </a>
                )}
              </nav>
            )}

            {/* (Sale-wrapper for teaser/grid is rendered INSIDE the
                lot card — see <a className="item-sale-wrapper"> below
                the <header className="item-lot-info"> branch.) */}

            {/* Ask Question Modal */}
            <Modal isOpen={isOpen} onClose={onClose} size="lg">
                <ModalOverlay />
                {/* The modal portals to document.body, outside the scoped app
                    containers — the class re-establishes the .circuit-user-ui
                    scope so the design-system button styles apply inside. */}
                <ModalContent maxW="90vw" w="lg" className="circuit-user-ui">
                    <ModalHeader>{t('itempage.modal.title')}</ModalHeader>
                    <ModalCloseButton />
                    <form onSubmit={handleSubmitQuestion}>
                        <ModalBody pb={6} overflowX="hidden">
                            <VStack spacing={4} align="stretch" width="100%" maxW="100%">
                                {item && (
                                    <Box p={3} bg="gray.50" borderRadius="md">
                                        <Text fontSize="sm" fontWeight="semibold">
                                            {t('itempage.lot', { number: item.lot_number })}
                                            {item.title && `: ${item.title}`}
                                        </Text>
                                    </Box>
                                )}

                                <FormControl isRequired>
                                    <FormLabel>{t('itempage.modal.name')}</FormLabel>
                                    <Input
                                        name="name"
                                        value={formData.name}
                                        onChange={handleFormChange}
                                        placeholder={t('itempage.modal.namePlaceholder')}
                                        isDisabled={config.accessToken && (config.userData?.first_name || config.userData?.last_name)}
                                        sx={{
                                            width: '100%',
                                            maxWidth: '100%',
                                            boxSizing: 'border-box',
                                            _disabled: { opacity: 0.8 }
                                        }}
                                    />
                                </FormControl>

                                <FormControl isRequired>
                                    <FormLabel>{t('itempage.modal.email')}</FormLabel>
                                    <Input
                                        name="email"
                                        type="email"
                                        value={formData.email}
                                        onChange={handleFormChange}
                                        placeholder={t('itempage.modal.emailPlaceholder')}
                                        isDisabled={config.accessToken && config.userData?.mail}
                                        sx={{
                                            width: '100%',
                                            maxWidth: '100%',
                                            boxSizing: 'border-box',
                                            _disabled: { opacity: 0.8 }
                                        }}
                                    />
                                </FormControl>

                                <FormControl>
                                    <FormLabel>{t('itempage.modal.phone')}</FormLabel>
                                    <Input
                                        name="phone"
                                        type="tel"
                                        value={formData.phone}
                                        onChange={handleFormChange}
                                        placeholder={t('itempage.modal.phonePlaceholder')}
                                        isDisabled={config.accessToken && config.userData?.mobile}
                                        sx={{
                                            width: '100%',
                                            maxWidth: '100%',
                                            boxSizing: 'border-box',
                                            _disabled: { opacity: 0.8 }
                                        }}
                                    />
                                </FormControl>

                                <FormControl isRequired>
                                    <FormLabel>{t('itempage.modal.question')}</FormLabel>
                                    <Textarea
                                        name="question"
                                        value={formData.question}
                                        onChange={handleFormChange}
                                        placeholder={t('itempage.modal.questionPlaceholder')}
                                        rows={5}
                                        resize="vertical"
                                        sx={{
                                            width: '100%',
                                            maxWidth: '100%',
                                            boxSizing: 'border-box'
                                        }}
                                    />
                                </FormControl>

                                {/* TODO(circuit): the ReCAPTCHA iframe is third-party and won't
                                    respect design tokens. Wrapper provides spacing only. */}
                                {config.recaptchaKey && (
                                    <div className="recaptcha-wrap">
                                        <ReCAPTCHA
                                            ref={recaptchaRef}
                                            sitekey={config.recaptchaKey}
                                            onChange={(token) => setCaptchaToken(token)}
                                            theme="light"
                                            hl={i18n.language}
                                        />
                                    </div>
                                )}
                            </VStack>
                        </ModalBody>

                        <ModalFooter className="ask-question-footer">
                            <button
                                type="button"
                                className="btn-secondary-action"
                                onClick={onClose}
                            >
                                {t('itempage.modal.cancel')}
                            </button>
                            <button
                                type="submit"
                                className="bid-limit-submit"
                                disabled={isSubmitting}
                            >
                                {isSubmitting
                                    ? t('itempage.modal.submitting')
                                    : t('itempage.modal.submit')}
                            </button>
                        </ModalFooter>
                    </form>
                </ModalContent>
            </Modal>
        </Box>
    );
};

export default ItemPage;
