import React, { useState, useEffect, useContext, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import fetchData from '../utils/Util';
import { useDataCache } from '../services/DataCache';
import {
    Spinner,
    Link,
    Image,
} from '@chakra-ui/react';
import { FaPlay, FaPause, FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import ItemPage from './ItemPage';
import { SaleLinkChakra } from "../components/ItemLink";
import { handleImageError } from '../utils/imageFallback';

const FeaturedItems = () => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSalesPublic } = useDataCache();
    const [saleNid, setSaleNid] = useState(null);
    const [displayMode, setDisplayMode] = useState(null);
    const [itemDisplayMode, setItemDisplayMode] = useState(null);
    const [saleData, setSaleData] = useState(null);
    const [itemUuids, setItemUuids] = useState([]);
    const [currentSlide, setCurrentSlide] = useState(0);
    const [isPlaying, setIsPlaying] = useState(true);
    const [isHovering, setIsHovering] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    // Read sale NID, display mode, and item display mode from data attributes on mount
    useEffect(() => {
        const container = document.getElementById('ca-featured-items');
        if (container) {
            const dataSaleNid = container.getAttribute('data-sale-nid');
            if (dataSaleNid) {
                setSaleNid(dataSaleNid);
            }

            const dataDisplayMode = container.getAttribute('data-display-mode');
            if (dataDisplayMode) {
                setDisplayMode(dataDisplayMode);
            }

            const dataItemDisplay = container.getAttribute('data-item-display');
            if (dataItemDisplay) {
                setItemDisplayMode(dataItemDisplay);
            }
        }
    }, []);

    // Fetch sale data when display mode includes sale info
    useEffect(() => {
        if (!config.siteData || !saleNid) return;
        if (displayMode !== 'sale-image' && displayMode !== 'sale-info') return;

        let cancelled = false;
        fetchSalesPublic(config.siteData.backoffice_url_lang, { saleNid })
            .then(data => {
                if (cancelled) return;
                // API returns data as an array with one element
                const sale = data.data?.[0] || data[0] || data;
                setSaleData(sale);
            })
            .catch(err => {
                if (!cancelled) console.error('Error fetching sale data:', err);
            });

        return () => { cancelled = true; };
    }, [config.siteData, saleNid, displayMode, fetchSalesPublic]);

    // Fetch featured items for the sale
    useEffect(() => {
        const fetchFeaturedItems = async () => {
            if (!config.siteData || !saleNid) {
                setIsLoading(false);
                return;
            }

            setIsLoading(true);
            setError(null);

            try {
                const params = new URLSearchParams({
                    fields: 'lot,uuid,sale_number',
                    'filter[tags]': 'Featured item',
                    sale_id: saleNid,
                    sort: 'lot_number'
                });

                const response = await fetchData(
                    `${config.siteData.backoffice_url_lang}/api/v1.0/items-public?${params.toString()}`
                );

                if (!response.ok) {
                    throw new Error('Failed to fetch featured items');
                }

                const data = await response.json();
                setItemUuids(data.data || []);
            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        fetchFeaturedItems();
    }, [config.siteData, saleNid]);

    // Carousel navigation handlers
    const nextSlide = useCallback(() => {
        setCurrentSlide((prev) => (prev + 1) % itemUuids.length);
        setIsPlaying(false); // Pause autoplay when user manually navigates
    }, [itemUuids.length]);

    const prevSlide = useCallback(() => {
        setCurrentSlide((prev) => (prev - 1 + itemUuids.length) % itemUuids.length);
        setIsPlaying(false); // Pause autoplay when user manually navigates
    }, [itemUuids.length]);

    const goToSlide = (index) => {
        setCurrentSlide(index);
        setIsPlaying(false); // Pause autoplay when user manually navigates
    };

    const togglePlayPause = useCallback(() => {
        setIsPlaying((p) => !p);
    }, []);

    // Autoplay - advance slides every 8 seconds when playing
    useEffect(() => {
        if (!isPlaying || itemUuids.length <= 1) {
            return;
        }

        const interval = setInterval(() => {
            setCurrentSlide((prev) => (prev + 1) % itemUuids.length);
        }, 8000); // 8 seconds

        return () => clearInterval(interval);
    }, [isPlaying, itemUuids.length]);

    // Keyboard navigation
    useEffect(() => {
        const handleKeyPress = (e) => {
            // Don't handle keyboard shortcuts if user is typing in an input field
            const target = e.target;
            const isInputField = target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable;

            if (isInputField) {
                return; // Allow normal typing in input fields
            }

            if (e.key === 'ArrowLeft') {
                prevSlide();
            }
            if (e.key === 'ArrowRight') {
                nextSlide();
            }
            if (e.key === ' ') {
                e.preventDefault();
                togglePlayPause();
            }
        };

        window.addEventListener('keydown', handleKeyPress);
        return () => window.removeEventListener('keydown', handleKeyPress);
    }, [nextSlide, prevSlide, togglePlayPause]);

    // Get language-specific sale data
    const getSaleDisplayData = (sale) => {
        if (!sale) return null;
        const currentLang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        return {
            title: sale.label?.[currentLang] || sale.label?.en || '',
            subtitle: sale.subtitle?.[currentLang] || sale.subtitle?.en || '',
            description: sale.description?.[currentLang]?.value || sale.description?.en?.value || '',
            dateLocation: sale.date_and_location_string?.[currentLang] || sale.date_and_location_string?.en || '',
        };
    };

    // Sale Header Component (shown when displayMode is "sale-image" or "sale-info")
    const SaleHeader = () => {
        if (!displayMode || !saleData) return null;
        if (displayMode !== 'sale-image' && displayMode !== 'sale-info') return null;

        const displayData = getSaleDisplayData(saleData);
        const logoUrl = saleData.logo?.url;

        // Mode 1: Sale image only
        if (displayMode === 'sale-image') {
            return (
                <div className="featured-sale-header featured-sale-header--image-only">
                    {logoUrl && (
                        <SaleLinkChakra saleId={saleData.id} className="featured-sale-header__image-link">
                            <Image
                                src={logoUrl}
                                onError={handleImageError}
                                alt={saleData.logo?.alt || displayData.title}
                                className="featured-sale-header__image"
                                loading="lazy"
                            />
                        </SaleLinkChakra>
                    )}
                </div>
            );
        }

        // Mode 2: Sale image + info below
        if (displayMode === 'sale-info') {
            return (
                <div className="featured-sale-header">
                    {logoUrl && (
                        <SaleLinkChakra saleId={saleData.id} className="featured-sale-header__image-link">
                            <Image
                                src={logoUrl}
                                onError={handleImageError}
                                alt={saleData.logo?.alt || displayData.title}
                                className="featured-sale-header__image"
                                loading="lazy"
                            />
                        </SaleLinkChakra>
                    )}

                    <SaleLinkChakra saleId={saleData.id} className="featured-sale-header__title-link">
                        <h2 className="featured-sale-header__title">
                            {displayData.title}
                        </h2>
                    </SaleLinkChakra>

                    {displayData.dateLocation && (
                        <p className="featured-sale-header__date">
                            {displayData.dateLocation}
                        </p>
                    )}

                    <div className="featured-sale-header__links">
                        {saleData.id && (
                            <SaleLinkChakra saleId={saleData.id} className="featured-sale-header__link featured-sale-header__link--primary">
                                {t('sales.onlineCatalog', 'Online Catalog')} →
                            </SaleLinkChakra>
                        )}
                        {saleData.pdf_link?.url && (
                            <Link
                                href={saleData.pdf_link.url}
                                className="featured-sale-header__link"
                                isExternal
                            >
                                {t('sales.pdfCatalogue', 'PDF Catalogue')}
                            </Link>
                        )}
                        {saleData.e_book_link?.url && (
                            <Link
                                href={saleData.e_book_link.url}
                                className="featured-sale-header__link"
                                isExternal
                            >
                                {t('sales.ebook', 'E-Book')}
                            </Link>
                        )}
                        {saleData.pdf_sale_result?.url && (
                            <Link
                                href={saleData.pdf_sale_result.url}
                                className="featured-sale-header__link"
                                isExternal
                            >
                                {t('sales.saleResults', 'Sale Results')}
                            </Link>
                        )}
                    </div>
                </div>
            );
        }

        return null;
    };

    if (isLoading) {
        return (
            <div className="featured-items featured-items--loading">
                <Spinner size="xl" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="featured-items">
                <div className="cream-note cream-note--error" role="alert">
                    {error}
                </div>
            </div>
        );
    }

    if (!saleNid) {
        return (
            <div className="featured-items">
                <div className="cream-note cream-note--warning" role="status">
                    {t('featured.noSaleNid', { defaultValue: 'Please provide a sale NID to view featured items.' })}
                </div>
            </div>
        );
    }

    if (itemUuids.length === 0) {
        return null; // Don't show anything if no featured items
    }

    return (
        <section className="featured-items">
            <SaleHeader />

            <div
                className="featured-items__viewport"
                onMouseEnter={() => setIsHovering(true)}
                onMouseLeave={() => setIsHovering(false)}
            >
                <div
                    className="featured-items__track"
                    style={{ transform: `translateX(-${currentSlide * 100}%)` }}
                >
                    {itemUuids.map((item) => (
                        <div key={item.uuid} className="featured-items__slide">
                            <ItemPage
                                itemId={item.uuid}
                                displayMode="featured"
                                itemDisplayMode={itemDisplayMode}
                            />
                        </div>
                    ))}
                </div>

                {/* Play/Pause — center of the viewport, visible on hover. */}
                {itemUuids.length > 1 && (
                    <button
                        type="button"
                        className={`featured-items__play${isHovering ? ' is-hovering' : ''}`}
                        onClick={togglePlayPause}
                        aria-label={isPlaying ? 'Pause slideshow' : 'Play slideshow'}
                    >
                        {isPlaying ? <FaPause /> : <FaPlay />}
                    </button>
                )}

                {/* Prev / Next — left and right edges, visible on hover. */}
                {itemUuids.length > 1 && (
                    <>
                        <button
                            type="button"
                            className={`featured-items__nav featured-items__nav--prev${isHovering ? ' is-hovering' : ''}`}
                            onClick={prevSlide}
                            aria-label="Previous slide"
                        >
                            <FaChevronLeft />
                        </button>
                        <button
                            type="button"
                            className={`featured-items__nav featured-items__nav--next${isHovering ? ' is-hovering' : ''}`}
                            onClick={nextSlide}
                            aria-label="Next slide"
                        >
                            <FaChevronRight />
                        </button>
                    </>
                )}
            </div>

            {/* Dot Indicators — below the viewport. */}
            {itemUuids.length > 1 && (
                <div className="featured-items__dots" role="tablist" aria-label="Slide indicators">
                    {itemUuids.map((item, index) => (
                        <button
                            key={item.uuid}
                            type="button"
                            role="tab"
                            aria-selected={currentSlide === index}
                            aria-label={`Go to slide ${index + 1}`}
                            className={`featured-items__dot${currentSlide === index ? ' is-active' : ''}`}
                            onClick={() => goToSlide(index)}
                        />
                    ))}
                </div>
            )}
        </section>
    );
};

export default FeaturedItems;
