import React, { useState, useContext, useEffect } from 'react';
import { useTranslation, Trans } from 'react-i18next';
import { Spinner } from '@chakra-ui/react';
import fetchData from '../utils/Util';
import PhoneInput, { getCountries, formatPhoneNumberIntl } from 'react-phone-number-input';
import flags from 'react-phone-number-input/flags';
import ReCAPTCHA from 'react-google-recaptcha';
import { ConfigContext } from '../config/Config';
import MyAccount from './MyAccount';

const EyeIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

const EyeOffIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
    <line x1="1" y1="1" x2="23" y2="23" />
  </svg>
);

const Register = () => {
  const { t, i18n } = useTranslation();
  const config = useContext(ConfigContext);

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    mail: '',
    pass: '',
    mobile: '',
    language: i18n.language,
    recaptcha_token: '',
    site: config.siteName,
  });

  const [country, setCountry] = useState('US');
  const [formattedMobile, setFormattedMobile] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isConfirmPasswordTouched, setIsConfirmPasswordTouched] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [confirmPassword, setConfirmPassword] = useState('');
  const [captchaToken, setCaptchaToken] = useState('');
  const [showMyAccount, setShowMyAccount] = useState(false);
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [agreeOtherSites, setAgreeOtherSites] = useState(true);

  useEffect(() => {
    const checkUserAuthentication = async () => {
      if (config.userData.accessToken) {
        setShowMyAccount(true);
      }
    };

    checkUserAuthentication();
  }, [config]);

  useEffect(() => {
    const detectCountry = () => {
      const browserLanguage = navigator.language || navigator.userLanguage;
      const [languageCode, countryCode] = browserLanguage.split('-');

      if (countryCode) {
        setCountry(countryCode.toUpperCase());
      } else {
        const countries = getCountries();
        const matchingCountry = countries.find((c) => c.toLowerCase() === languageCode.toLowerCase());
        setCountry(matchingCountry || 'US');
      }
    };

    detectCountry();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      if (!termsAccepted) {
        return;
      }

      if (captchaToken === '' || captchaToken === null) {
        setError('Please complete the reCAPTCHA verification');
        setIsLoading(false);
        return;
      }

      const response = await fetchData(`${config.backendUrl}/api/v2.0/user_registration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...formData, recaptcha_token: captchaToken, agree_other_sites: agreeOtherSites }),
      });

      if (response.ok) {
        const result = await response.json();
        const accessToken = result.data[0]?.access_token;
        config.setAccessToken(accessToken);
        try {
          setSuccessMessage('Registration successful! You will be redirected to your account page.');
          setShowMyAccount(true);
        } catch (err) {
          console.error('Error fetching user data:', err);
          setError(`Registration successful, ${err.title}`);
          setShowMyAccount(true);

          const urlParams = new URLSearchParams(window.location.search);
          const redirectUrl = urlParams.get('redirect');
          window.location.href = redirectUrl || '/';
        }
      } else {
        const errorData = await response.json();
        setError(errorData.title || 'Registration failed. Please try again.');
      }
    } catch (err) {
      console.error('Network error:', err);
      setError('Registration failed due to a network error. Please check your internet connection and try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleConfirmPasswordChange = (e) => {
    setConfirmPassword(e.target.value);
    setIsConfirmPasswordTouched(true);
  };

  const togglePasswordVisibility = () => setShowPassword((s) => !s);
  const toggleConfirmPasswordVisibility = () => setShowConfirmPassword((s) => !s);

  const handleMobileChange = (value) => {
    const formattedNumber = value ? formatPhoneNumberIntl(value) : '';
    setFormattedMobile(formattedNumber);
    setFormData({
      ...formData,
      mobile: value,
    });
  };

  if (config.success === false) {
    return (
      <div className="auth-page">
        <div className="cream-note cream-note--error" role="alert">
          {t('register.cannotAccessSettings')}
        </div>
      </div>
    );
  }

  if (showMyAccount) {
    return <MyAccount />;
  }

  const passwordsMatch =
    isConfirmPasswordTouched && confirmPassword !== '' && formData.pass === confirmPassword;
  const passwordsMismatch =
    isConfirmPasswordTouched && formData.pass !== confirmPassword;

  const connectedSites = Array.isArray(config.siteData?.connected_backoffices)
    ? config.siteData.connected_backoffices
    : [];

  return (
    <div className="auth-page auth-page--wide">
      <section className="rc-card auth-card">
        <header className="card-head">
          <h2 className="page-title">{t('register.title')}</h2>
        </header>

        <div className="card-body">
          {successMessage && (
            <div className="cream-note cream-note--success" role="status">
              {t('register.successMessage')}
            </div>
          )}

          <div className="auth-intro">
            <p>{t('register.instructions')}</p>
          </div>

          <form onSubmit={handleSubmit} className="acct-form">
            <div className="field-row">
              <div className="field">
                <label htmlFor="reg-firstName" className="field-label">
                  {t('register.firstName')}<span className="req">*</span>
                </label>
                <input
                  id="reg-firstName"
                  type="text"
                  name="first_name"
                  value={formData.first_name}
                  onChange={handleChange}
                  placeholder={t('register.firstName')}
                  required
                  disabled={isLoading}
                  className="field-input"
                  autoComplete="given-name"
                />
              </div>
              <div className="field">
                <label htmlFor="reg-lastName" className="field-label">
                  {t('register.lastName')}<span className="req">*</span>
                </label>
                <input
                  id="reg-lastName"
                  type="text"
                  name="last_name"
                  value={formData.last_name}
                  onChange={handleChange}
                  placeholder={t('register.lastName')}
                  required
                  disabled={isLoading}
                  className="field-input"
                  autoComplete="family-name"
                />
              </div>
            </div>

            <div className="field">
              <label htmlFor="reg-email" className="field-label">
                {t('register.email')}<span className="req">*</span>
              </label>
              <input
                id="reg-email"
                type="email"
                name="mail"
                value={formData.mail}
                onChange={handleChange}
                placeholder={t('register.email')}
                required
                disabled={isLoading}
                className="field-input"
                autoComplete="email"
              />
            </div>

            <div className="field">
              <label className="field-label">
                {t('register.mobileNumber')}<span className="req">*</span>
              </label>
              {/* TODO(circuit): replace react-phone-number-input with native widget once documented. */}
              <PhoneInput
                className="phone-input-dropdown"
                country={country}
                value={formData.mobile}
                onChange={handleMobileChange}
                placeholder={t('register.enterLocalMobile')}
                onCountryChange={(countryCode) => setCountry(countryCode)}
                flags={flags}
                defaultCountry={country}
                required
                disabled={isLoading}
              />
              {formattedMobile && (
                <p className="field-format">
                  <span>{t('register.standardInternationalFormat')}</span>
                  <span className="field-format__value">{formattedMobile}</span>
                </p>
              )}
            </div>

            <div className="field">
              <label htmlFor="reg-password" className="field-label">
                {t('register.newPassword')}<span className="req">*</span>
              </label>
              <div className="password-input-wrap">
                <input
                  id="reg-password"
                  type={showPassword ? 'text' : 'password'}
                  name="pass"
                  value={formData.pass}
                  onChange={handleChange}
                  placeholder={t('register.newPassword')}
                  disabled={isLoading}
                  className="field-input"
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={togglePasswordVisibility}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                  disabled={isLoading}
                >
                  {showPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
            </div>

            <div className="field">
              <label htmlFor="reg-confirm" className="field-label">
                {t('register.confirmPassword')}<span className="req">*</span>
              </label>
              <div className="password-input-wrap">
                <input
                  id="reg-confirm"
                  type={showConfirmPassword ? 'text' : 'password'}
                  name="confirmPassword"
                  value={confirmPassword}
                  onChange={handleConfirmPasswordChange}
                  onBlur={() => setIsConfirmPasswordTouched(true)}
                  placeholder={t('register.confirmPassword')}
                  disabled={isLoading}
                  className="field-input"
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={toggleConfirmPasswordVisibility}
                  aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                  disabled={isLoading}
                >
                  {showConfirmPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
              {passwordsMismatch && (
                <span className="validation-message validation-message--err">
                  {t('register.passwordsDoNotMatch')}
                </span>
              )}
              {passwordsMatch && (
                <span className="validation-message validation-message--ok">
                  {t('register.passwordsMatch')}
                </span>
              )}
            </div>

            <label className="checkbox-row terms-acceptance">
              <input
                type="checkbox"
                id="termsCheckbox"
                checked={termsAccepted}
                onChange={() => setTermsAccepted(!termsAccepted)}
                required
                disabled={isLoading}
              />
              <span className="checkbox-label">
                <Trans i18nKey="register.termsAcceptance">
                  I have read and accepted the Auctioneers <a href="/terms" target="_blank" rel="noopener noreferrer">Terms and Conditions</a> and <a href="/conditions" target="_blank" rel="noopener noreferrer">Data Privacy Terms</a> and I agree to abide by them.
                </Trans>
              </span>
            </label>

            {connectedSites.length > 0 && (
              <label className="checkbox-row terms-acceptance">
                <input
                  type="checkbox"
                  id="otherSitesCheckbox"
                  checked={agreeOtherSites}
                  onChange={() => setAgreeOtherSites(!agreeOtherSites)}
                  disabled={isLoading}
                />
                <span className="checkbox-label">
                  {t('register.partnerCompaniesConsent')}{' '}
                  {connectedSites.map((site, index) => (
                    <span key={site.url}>
                      <a href={`https://${site.url}`} target="_blank" rel="noopener noreferrer">{site.url}</a>
                      {index < connectedSites.length - 1 && ', '}
                    </span>
                  ))}
                </span>
              </label>
            )}

            {/* TODO(circuit): the ReCAPTCHA iframe is third-party and won't
                respect design tokens. Wrapper provides spacing only. */}
            <div className="recaptcha-wrap">
              <ReCAPTCHA
                sitekey={config.recaptchaKey}
                onChange={(token) => setCaptchaToken(token)}
                theme="light"
                hl={i18n.language}
              />
            </div>

            <p
              className="required-note"
              dangerouslySetInnerHTML={{
                __html: t('register.requiredFields', { asterisk: '<span class="req">*</span>' }),
              }}
            />

            <div className="card-actions">
              <button
                type="submit"
                className="btn-primary-action"
                disabled={isLoading}
              >
                {isLoading ? <Spinner size="sm" /> : t('register.signUpButton')}
              </button>
            </div>

            {error && (
              <div className="cream-note cream-note--error" role="alert" style={{ marginTop: 'var(--space-5)' }}>
                <strong>{t('register.errorTitle')}</strong>{error}
              </div>
            )}
          </form>
        </div>
      </section>
    </div>
  );
};

export default Register;
