import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import fetchData from '../utils/Util';
import {
    Box,
    Spinner,
    IconButton,
    Flex,
    Icon,
    Heading,
    Text,
    Link,
    Image,
} from '@chakra-ui/react';
import { ChevronLeftIcon, ChevronRightIcon } from '@chakra-ui/icons';
import { FaPlay, FaPause } from 'react-icons/fa';
import ItemPage from './ItemPage';
import { ItemLinkChakra, SaleLinkChakra } from "../components/ItemLink";
import { handleImageError } from '../utils/imageFallback';


const SingleSaleCarousel = ({ sale, displayMode, itemDisplayMode, hideSaleHeader = false }) => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const [itemUuids, setItemUuids] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [currentSlide, setCurrentSlide] = useState(0);
    const [isPlaying, setIsPlaying] = useState(true);
    const [isHovering, setIsHovering] = useState(false);

    // Fetch featured items for this sale
    useEffect(() => {
        const fetchFeaturedItems = async () => {
            if (!config.siteData || !sale) {
                return;
            }

            setIsLoading(true);

            try {
                const params = new URLSearchParams({
                    fields: 'lot,uuid,sale_number',
                    'filter[tags]': 'Featured item',
                    sale_id: sale.id,
                    sort: 'lot_number'
                });

                const response = await fetchData(
                    `${config.siteData.backoffice_url_lang}/api/v1.0/items-public?${params.toString()}`
                );

                if (!response.ok) {
                    throw new Error('Failed to fetch featured items');
                }

                const data = await response.json();
                setItemUuids(data.data || []);
            } catch (err) {
                console.error('SingleSaleCarousel - Error fetching featured items:', err);
            } finally {
                setIsLoading(false);
            }
        };

        fetchFeaturedItems();
    }, [config.siteData, sale]);

    // Carousel navigation handlers
    const nextSlide = () => {
        setCurrentSlide((prev) => (prev + 1) % itemUuids.length);
        setIsPlaying(false);
    };

    const prevSlide = () => {
        setCurrentSlide((prev) => (prev - 1 + itemUuids.length) % itemUuids.length);
        setIsPlaying(false);
    };

    const goToSlide = (index) => {
        setCurrentSlide(index);
        setIsPlaying(false);
    };

    const togglePlayPause = () => {
        setIsPlaying(!isPlaying);
    };

    // Autoplay
    useEffect(() => {
        if (!isPlaying || itemUuids.length <= 1) return;

        const interval = setInterval(() => {
            setCurrentSlide((prev) => (prev + 1) % itemUuids.length);
        }, 8000);

        return () => clearInterval(interval);
    }, [isPlaying, itemUuids.length]);

    // Get language-specific sale data
    const getSaleDisplayData = (saleData) => {
        if (!saleData) return null;
        const currentLang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        return {
            title: saleData.label?.[currentLang] || saleData.label?.en || '',
            subtitle: saleData.subtitle?.[currentLang] || saleData.subtitle?.en || '',
            description: saleData.description?.[currentLang]?.value || saleData.description?.en?.value || '',
            dateLocation: saleData.date_and_location_string?.[currentLang] || saleData.date_and_location_string?.en || '',
        };
    };

    // Sale Header Component
    const SaleHeader = () => {
        if (hideSaleHeader) return null;
        if (!displayMode || !sale) return null;
        if (displayMode !== 'sale-image' && displayMode !== 'sale-info') return null;

        const displayData = getSaleDisplayData(sale);
        const logoUrl = sale.logo?.url;

        if (displayMode === 'sale-image') {
            return (
                <Box className="featured-items-sale-header" mb={6} textAlign="center">
                    {logoUrl && (
                        <SaleLinkChakra saleId={sale.id} className="sale-header__image-link">
                            <Image
                                src={logoUrl}
                                onError={handleImageError}
                                alt={sale.logo?.alt || displayData.title}
                                className="sale-header__image"
                                maxW="100%"
                                height="auto"
                                objectFit="contain"
                                mx="auto"
                                loading="lazy"
                            />
                        </SaleLinkChakra>
                    )}
                </Box>
            );
        }

        if (displayMode === 'sale-info') {
            return (
                <Box className="featured-items-sale-header" mb={6} textAlign="center">
                    {logoUrl && (
                        <SaleLinkChakra saleId={sale.id} className="sale-header__image-link" display="block" mb={4}>
                            <Image
                                src={logoUrl}
                                onError={handleImageError}
                                alt={sale.logo?.alt || displayData.title}
                                className="sale-header__image"
                                maxW="100%"
                                height="auto"
                                objectFit="contain"
                                mx="auto"
                                loading="lazy"
                            />
                        </SaleLinkChakra>
                    )}

                    <SaleLinkChakra saleId={sale.id} className="sale-header__title-link">
                        <Heading className="sale-header__title" fontSize="2xl" mb={2}>
                            {displayData.title}
                        </Heading>
                    </SaleLinkChakra>

                    {displayData.dateLocation && (
                        <Text className="sale-header__date" fontSize="md" color="gray.600" mb={3}>
                            {displayData.dateLocation}
                        </Text>
                    )}

                    {sale.id && (
                        <Box mb={2}>
                            <SaleLinkChakra saleId={sale.id} color="blue.600" fontSize="md">
                                {t('sales.onlineCatalog', 'Online Catalog')}
                            </SaleLinkChakra>
                        </Box>
                    )}

                    {(sale.pdf_link?.url || sale.e_book_link?.url || sale.pdf_sale_result?.url) && (
                        <Flex className="sale-header__pdf-links" gap={3} flexWrap="wrap" justifyContent="center">
                            {sale.pdf_link?.url && (
                                <Link
                                    href={sale.pdf_link.url}
                                    className="sale-header__pdf-link"
                                    isExternal
                                    color="blue.600"
                                    fontSize="sm"
                                >
                                    {t('sales.pdfCatalogue', 'PDF Catalogue')}
                                </Link>
                            )}
                            {sale.e_book_link?.url && (
                                <Link
                                    href={sale.e_book_link.url}
                                    className="sale-header__ebook-link"
                                    isExternal
                                    color="blue.600"
                                    fontSize="sm"
                                >
                                    {t('sales.ebook', 'E-Book')}
                                </Link>
                            )}
                            {sale.pdf_sale_result?.url && (
                                <Link
                                    href={sale.pdf_sale_result.url}
                                    className="sale-header__results-link"
                                    isExternal
                                    color="blue.600"
                                    fontSize="sm"
                                >
                                    {t('sales.saleResults', 'Sale Results')}
                                </Link>
                            )}
                        </Flex>
                    )}
                </Box>
            );
        }

        return null;
    };

    // Lot Info Component
    const LotInfo = () => {
        if (!itemDisplayMode || itemUuids.length === 0) return null;

        const currentItem = itemUuids[currentSlide];
        if (!currentItem) return null;

        if (itemDisplayMode === 'lot-number') {
            const lotNumber = currentItem.lot;
            const saleNumber = currentItem.sale_number || sale?.sale_number || sale?.id;

            return (
                <Box className="featured-items-lot-info" textAlign="center" mt={4}>
                    <ItemLinkChakra itemUuid={currentItem.uuid} fontSize="lg" fontWeight="bold" color="blue.600">
                        LOT {lotNumber} - Sale {saleNumber}
                    </ItemLinkChakra>
                </Box>
            );
        }

        return null;
    };

    if (isLoading) {
        return (
            <Box display="flex" justifyContent="center" py={8}>
                <Spinner size="xl" />
            </Box>
        );
    }

    if (itemUuids.length === 0) {
        return null; // Don't show anything if no featured items
    }

    return (
        <Box className="single-sale-carousel" mb={8}>
            <SaleHeader />

            <Box className="featured-items-carousel" position="relative" width="100%">
                <Box
                    position="relative"
                    overflow="hidden"
                    width="100%"
                    onMouseEnter={() => setIsHovering(true)}
                    onMouseLeave={() => setIsHovering(false)}
                >
                    <Box
                        display="flex"
                        transition="transform 0.5s ease-in-out"
                        transform={`translateX(-${currentSlide * 100}%)`}
                    >
                        {itemUuids.map((item) => (
                            <Box
                                key={item.uuid}
                                className="featured-item-slide"
                                minW="100%"
                                maxW="100%"
                                flexShrink={0}
                            >
                                <Box px={4}>
                                    <ItemPage
                                        itemId={item.uuid}
                                        displayMode="featured"
                                        itemDisplayMode={itemDisplayMode}
                                    />
                                </Box>
                            </Box>
                        ))}
                    </Box>

                    {itemUuids.length > 1 && (
                        <IconButton
                            icon={isPlaying ? <Icon as={FaPause} /> : <Icon as={FaPlay} />}
                            onClick={togglePlayPause}
                            position="absolute"
                            top="50%"
                            left="50%"
                            transform="translate(-50%, -50%)"
                            zIndex={3}
                            colorScheme="blackAlpha"
                            bg="rgba(0, 0, 0, 0.6)"
                            color="white"
                            size="lg"
                            borderRadius="full"
                            opacity={isHovering ? 1 : 0}
                            transition="opacity 0.3s"
                            _hover={{ bg: 'rgba(0, 0, 0, 0.8)' }}
                            aria-label={isPlaying ? "Pause slideshow" : "Play slideshow"}
                        />
                    )}
                </Box>

                {itemUuids.length > 1 && (
                    <>
                        <IconButton
                            icon={<ChevronLeftIcon boxSize={8} />}
                            onClick={prevSlide}
                            position="absolute"
                            left="20px"
                            top="50%"
                            transform="translateY(-50%)"
                            zIndex={2}
                            colorScheme="blackAlpha"
                            bg="rgba(0, 0, 0, 0.6)"
                            color="white"
                            size="lg"
                            borderRadius="full"
                            opacity={isHovering ? 1 : 0}
                            transition="opacity 0.3s"
                            aria-label="Previous slide"
                            _hover={{ bg: 'rgba(0, 0, 0, 0.8)', transform: 'translateY(-50%) scale(1.1)' }}
                        />

                        <IconButton
                            icon={<ChevronRightIcon boxSize={8} />}
                            onClick={nextSlide}
                            position="absolute"
                            right="20px"
                            top="50%"
                            transform="translateY(-50%)"
                            zIndex={2}
                            colorScheme="blackAlpha"
                            bg="rgba(0, 0, 0, 0.6)"
                            color="white"
                            size="lg"
                            borderRadius="full"
                            opacity={isHovering ? 1 : 0}
                            transition="opacity 0.3s"
                            aria-label="Next slide"
                            _hover={{ bg: 'rgba(0, 0, 0, 0.8)', transform: 'translateY(-50%) scale(1.1)' }}
                        />

                        {itemDisplayMode !== 'lot-number' && (
                            <Flex
                                justifyContent="center"
                                gap={2}
                                mt={4}
                                className="carousel-dots"
                            >
                                {itemUuids.map((item, index) => (
                                    <Box
                                        key={item.uuid}
                                        onClick={() => goToSlide(index)}
                                        cursor="pointer"
                                        width="12px"
                                        height="12px"
                                        borderRadius="full"
                                        bg={currentSlide === index ? 'blue.500' : 'gray.300'}
                                        transition="all 0.3s"
                                        _hover={{
                                            bg: currentSlide === index ? 'blue.600' : 'gray.400',
                                            transform: 'scale(1.2)'
                                        }}
                                    />
                                ))}
                            </Flex>
                        )}
                    </>
                )}

                <LotInfo />
            </Box>
        </Box>
    );
};

export default SingleSaleCarousel;
