import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Box, Image, SimpleGrid, Text, Icon, IconButton, Spinner } from '@chakra-ui/react';
import { FaPlay, FaFilePdf, FaPause } from 'react-icons/fa';
import { ChevronLeftIcon, ChevronRightIcon } from '@chakra-ui/icons';
import { handleImageError, NO_IMAGE_SRC } from '../utils/imageFallback';

// Detect media type from item data
const getMediaType = (item) => {
    if (item.video_url) return 'video';
    if (item.pdf_url) return 'pdf';
    return 'image';
};

// Extract a frame from video at specified time
const extractVideoFrame = (videoUrl, seekTime = 1.0) => {
    return new Promise((resolve, reject) => {
        const video = document.createElement('video');
        video.crossOrigin = 'anonymous';
        video.preload = 'metadata';

        const handleLoadedData = () => {
            // Seek to the specified time
            video.currentTime = Math.min(seekTime, video.duration);
        };

        const handleSeeked = () => {
            try {
                // Create canvas and draw video frame
                const canvas = document.createElement('canvas');
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;

                const ctx = canvas.getContext('2d');
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

                // Convert canvas to data URL
                const dataUrl = canvas.toDataURL('image/jpeg', 0.8);

                // Cleanup
                video.removeEventListener('loadeddata', handleLoadedData);
                video.removeEventListener('seeked', handleSeeked);
                video.removeEventListener('error', handleError);
                video.src = '';

                resolve(dataUrl);
            } catch (error) {
                reject(error);
            }
        };

        const handleError = (error) => {
            video.removeEventListener('loadeddata', handleLoadedData);
            video.removeEventListener('seeked', handleSeeked);
            video.removeEventListener('error', handleError);
            reject(error);
        };

        video.addEventListener('loadeddata', handleLoadedData);
        video.addEventListener('seeked', handleSeeked);
        video.addEventListener('error', handleError);

        video.src = videoUrl;
        video.load();
    });
};

const ItemImageGallery = ({ images: rawImages, displayMode = 'full', hideNavigation = false }) => {
    const { t } = useTranslation();
    // Ignore gallery entries with no usable media source: an entry whose
    // .big/.small is an empty string renders an <img> that errors, flashes
    // the broken-image fallback, and then flips to the placeholder on the
    // next render. Sanitizing up front lands such items in the placeholder
    // branch directly — no flicker — and keeps every effect below (preload,
    // slideshow, thumbnails, lightGallery) on the same clean list.
    const images = useMemo(
        () => (rawImages || []).filter(
            (media) => media && (media.big || media.small || media.video_url || media.pdf_url),
        ),
        [rawImages],
    );
    const galleryRef = useRef(null);
    const lgInstance = useRef(null);
    const [isClient, setIsClient] = useState(false);
    const [activeIndex, setActiveIndex] = useState(0);
    const [videoThumbnails, setVideoThumbnails] = useState({});
    const [isHovering, setIsHovering] = useState(false);
    const [isPaused, setIsPaused] = useState(false);
    const [isTransitioning, setIsTransitioning] = useState(false);
    const [previousIndex, setPreviousIndex] = useState(0);
    const [isImageLoading, setIsImageLoading] = useState(false);

    useEffect(() => {
        setIsClient(true);
    }, []);

    // Preload next and previous images in featured mode (images only, not videos/PDFs)
    useEffect(() => {
        if (displayMode !== 'featured' || !images || images.length <= 1) {
            return;
        }

        // Calculate next and previous indices
        const nextIndex = activeIndex === images.length - 1 ? 0 : activeIndex + 1;
        const prevIndex = activeIndex === 0 ? images.length - 1 : activeIndex - 1;

        // Preload next image (only if it's an image, not video/PDF)
        const nextItem = images[nextIndex];
        if (nextItem && getMediaType(nextItem) === 'image' && nextItem.big) {
            const nextImg = new window.Image();
            nextImg.src = nextItem.big;
        }

        // Preload previous image (only if it's an image, not video/PDF)
        const prevItem = images[prevIndex];
        if (prevItem && getMediaType(prevItem) === 'image' && prevItem.big) {
            const prevImg = new window.Image();
            prevImg.src = prevItem.big;
        }
    }, [displayMode, images, activeIndex]);

    // Auto-advance slideshow in featured mode (images only, skip videos/PDFs)
    useEffect(() => {
        if (displayMode !== 'featured' || !images || images.length <= 1 || isPaused) {
            return;
        }

        const interval = setInterval(() => {
            setPreviousIndex(activeIndex);
            setIsTransitioning(true);

            // Find next image (skip videos and PDFs)
            let nextIndex = activeIndex;
            let attempts = 0;
            do {
                nextIndex = (nextIndex + 1) % images.length;
                attempts++;
                // Prevent infinite loop if no images exist
                if (attempts > images.length) {
                    nextIndex = activeIndex;
                    break;
                }
            } while (getMediaType(images[nextIndex]) !== 'image' && attempts <= images.length);

            setActiveIndex(nextIndex);

            // Reset transition state after animation completes
            setTimeout(() => setIsTransitioning(false), 800);
        }, 9000); // 9 seconds

        return () => clearInterval(interval);
    }, [displayMode, images, isPaused, activeIndex]);

    // Extract video frames for thumbnails
    useEffect(() => {
        if (!isClient || !images || images.length === 0) return;

        const extractFrames = async () => {
            const thumbnails = {};

            for (let i = 0; i < images.length; i++) {
                const item = images[i];
                if (getMediaType(item) === 'video' && item.video_url) {
                    try {
                        const frameUrl = await extractVideoFrame(item.video_url, 3.0);
                        thumbnails[item.video_url] = frameUrl;
                    } catch (error) {
                        console.error(`Failed to extract frame from video ${i}:`, error);
                        // Keep as null to use fallback
                        thumbnails[item.video_url] = null;
                    }
                }
            }

            setVideoThumbnails(thumbnails);
        };

        extractFrames();
    }, [images, isClient]);

    useEffect(() => {
        if (!isClient || !galleryRef.current || !images || images.length === 0) {
            return;
        }

        // Dynamically import lightGallery only on client side
        const initGallery = async () => {
            try {
                const lightGallery = (await import('lightgallery')).default;
                const lgZoom = (await import('lightgallery/plugins/zoom')).default;
                const lgVideo = (await import('lightgallery/plugins/video')).default;

                await import('lightgallery/css/lightgallery.css');
                await import('lightgallery/css/lg-zoom.css');
                await import('lightgallery/css/lg-video.css');

                if (galleryRef.current && !lgInstance.current) {
                    // Destroy existing instance if any
                    if (lgInstance.current) {
                        lgInstance.current.destroy();
                    }

                    lgInstance.current = lightGallery(galleryRef.current, {
                        licenseKey: 'LIG-855CEE25-6856-4181-9A1C-125171EDE6BD',
                        plugins: [lgZoom, lgVideo],
                        speed: 500,
                        download: false,
                        mode: 'lg-fade',
                        counter: true,
                        dynamic: true,
                        // Pass images as dynamic content
                        dynamicEl: images.map((image, index) => {
                            const mediaType = getMediaType(image);

                            if (mediaType === 'video') {
                                return {
                                    video: {
                                        source: [{
                                            src: image.video_url,
                                            type: 'video/mp4'
                                        }],
                                        attributes: {
                                            preload: 'metadata',
                                            controls: true,
                                        }
                                    },
                                    thumb: image.small || '',
                                    subHtml: `<h4>Video ${index + 1} of ${images.length}</h4>`,
                                };
                            } else if (mediaType === 'pdf') {
                                return {
                                    iframe: true,
                                    src: image.pdf_url,
                                    thumb: image.small || '',
                                    subHtml: `<h4>PDF ${index + 1} of ${images.length}</h4>`,
                                };
                            } else {
                                return {
                                    src: image.zoom,
                                    thumb: image.small,
                                    subHtml: `<h4>Image ${index + 1} of ${images.length}</h4>`,
                                };
                            }
                        }),
                        // Zoom plugin settings
                        zoom: true,
                        actualSize: true,
                        showZoomInOutIcons: true,
                        actualSizeIcons: {
                            zoomIn: 'lg-zoom-in',
                            zoomOut: 'lg-zoom-out',
                        },
                        // Enable zoom on double-click and pinch
                        enableZoom: true,
                        enableTouch: true,
                        // Wait for image to load before enabling zoom
                        appendSubHtmlTo: '.lg-item',
                        // Video settings
                        videojs: false,
                        videojsOptions: {},
                        // Iframe settings for PDFs
                        iframeWidth: '100%',
                        iframeHeight: '100%',
                        iframeMaxWidth: '100%',
                        iframeMaxHeight: '100%',
                    });

                    // Add event listeners
                    if (galleryRef.current) {
                        // Handle zoom ready after slide change
                        galleryRef.current.addEventListener('lgAfterSlide', (event) => {
                            // Give the image time to load before zoom becomes active
                            setTimeout(() => {
                                const lgContainer = document.querySelector('.lg-container');
                                if (lgContainer) {
                                    lgContainer.classList.add('lg-zoom-ready');
                                }
                            }, 100);

                            // Auto-play video when navigating to a video slide
                            const currentIndex = event.detail.index;
                            const currentItem = images[currentIndex];
                            if (currentItem && getMediaType(currentItem) === 'video') {
                                // Find and play the video element
                                setTimeout(() => {
                                    const videoElement = document.querySelector('.lg-current video');
                                    if (videoElement) {
                                        videoElement.play().catch(err => {
                                            console.log('Video autoplay prevented:', err);
                                        });
                                    }
                                }, 200);
                            }
                        });

                        // Auto-play video on initial gallery open if first slide is video
                        galleryRef.current.addEventListener('lgAfterOpen', () => {
                            const firstItem = images[0];
                            if (firstItem && getMediaType(firstItem) === 'video') {
                                setTimeout(() => {
                                    const videoElement = document.querySelector('.lg-current video');
                                    if (videoElement) {
                                        videoElement.play().catch(err => {
                                            console.log('Video autoplay prevented:', err);
                                        });
                                    }
                                }, 200);
                            }
                        });
                    }
                }
            } catch (error) {
                console.error('Failed to initialize lightGallery:', error);
            }
        };

        initGallery();

        // Cleanup on unmount
        return () => {
            if (lgInstance.current) {
                lgInstance.current.destroy();
                lgInstance.current = null;
            }
        };
    }, [images, isClient]);

    const handleThumbnailClick = (index) => {
        // Just change the active image, don't open lightbox

        // Set loading state
        setIsImageLoading(true);

        // Preload the image
        const img = new window.Image();
        img.onload = () => {
            setIsImageLoading(false);
        };
        img.onerror = () => {
            setIsImageLoading(false);
        };
        img.src = images[index]?.big;

        setActiveIndex(index);
    };

    const handleMainImageClick = () => {
        // Open lightbox starting at the current active index
        if (lgInstance.current) {
            try {
                lgInstance.current.openGallery(activeIndex);
            } catch (error) {
                console.error('Error opening gallery:', error);
            }
        }
    };

    const handlePrevImage = (e) => {
        e.stopPropagation(); // Prevent opening lightbox

        if (displayMode === 'featured') {
            setPreviousIndex(activeIndex);
            setIsTransitioning(true);
            setTimeout(() => setIsTransitioning(false), 800);

            // Find previous image (skip videos and PDFs)
            let prevIndex = activeIndex;
            let attempts = 0;
            do {
                prevIndex = (prevIndex - 1 + images.length) % images.length;
                attempts++;
                if (attempts > images.length) {
                    prevIndex = activeIndex;
                    break;
                }
            } while (getMediaType(images[prevIndex]) !== 'image' && attempts <= images.length);

            // Set loading state
            setIsImageLoading(true);

            // Preload the image
            const img = new window.Image();
            img.onload = () => {
                setIsImageLoading(false);
            };
            img.onerror = () => {
                setIsImageLoading(false);
            };
            img.src = images[prevIndex]?.big;

            setActiveIndex(prevIndex);
        } else {
            // Calculate previous index
            const prevIndex = activeIndex === 0 ? images.length - 1 : activeIndex - 1;

            // Set loading state
            setIsImageLoading(true);

            // Preload the image
            const img = new window.Image();
            img.onload = () => {
                setIsImageLoading(false);
            };
            img.onerror = () => {
                setIsImageLoading(false);
            };
            img.src = images[prevIndex]?.big;

            setActiveIndex(prevIndex);
        }
    };

    const handleNextImage = (e) => {
        e.stopPropagation(); // Prevent opening lightbox

        if (displayMode === 'featured') {
            setPreviousIndex(activeIndex);
            setIsTransitioning(true);
            setTimeout(() => setIsTransitioning(false), 800);

            // Find next image (skip videos and PDFs)
            let nextIndex = activeIndex;
            let attempts = 0;
            do {
                nextIndex = (nextIndex + 1) % images.length;
                attempts++;
                if (attempts > images.length) {
                    nextIndex = activeIndex;
                    break;
                }
            } while (getMediaType(images[nextIndex]) !== 'image' && attempts <= images.length);

            // Set loading state
            setIsImageLoading(true);

            // Preload the image
            const img = new window.Image();
            img.onload = () => {
                setIsImageLoading(false);
            };
            img.onerror = () => {
                setIsImageLoading(false);
            };
            img.src = images[nextIndex]?.big;

            setActiveIndex(nextIndex);
        } else {
            // Calculate next index
            const nextIndex = activeIndex === images.length - 1 ? 0 : activeIndex + 1;

            // Set loading state
            setIsImageLoading(true);

            // Preload the image
            const img = new window.Image();
            img.onload = () => {
                setIsImageLoading(false);
            };
            img.onerror = () => {
                setIsImageLoading(false);
            };
            img.src = images[nextIndex]?.big;

            setActiveIndex(nextIndex);
        }
    };

    const togglePlayPause = (e) => {
        e.stopPropagation(); // Prevent opening lightbox
        setIsPaused(!isPaused);
    };

    if (images.length === 0) {
        return (
            <Box className="lot-images-carousel-wrapper">
                <Box
                    className="no-image"
                    width="150px"
                    height="150px"
                    borderRadius="md"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                    border="1px solid"
                    borderColor="gray.200"
                    position="relative"
                    overflow="hidden"
                    sx={{
                        '& .no-media-text': {
                            opacity: 0,
                            transition: 'opacity 0.2s',
                        },
                        '&:hover .no-media-text': {
                            opacity: 1,
                        }
                    }}
                >
                    {/* Same pictogram as the broken-image fallback
                        (utils/imageFallback.js) so both "no image" paths
                        look identical. */}
                    <img
                        src={NO_IMAGE_SRC}
                        alt=""
                        className="img-fallback"
                        style={{ width: '100%', height: '100%' }}
                    />
                    <Text
                        className="no-media-text"
                        color="gray.500"
                        fontSize="sm"
                        position="absolute"
                        bottom="0"
                        left="0"
                        right="0"
                        textAlign="center"
                    >
                        {t('item.noMedia', { defaultValue: 'No media available' })}
                    </Text>
                </Box>
            </Box>
        );
    }

    const hasMultipleImages = images.length > 1;
    const imageCount = images.length;
    const activeItem = images[activeIndex];
    const activeMediaType = getMediaType(activeItem);

    // Render main display based on media type
    const renderMainDisplay = () => {
        if (activeMediaType === 'video') {
            const videoThumb = videoThumbnails[activeItem.video_url];

            return (
                <Box
                    position="relative"
                    width="100%"
                    height="100%"
                    minH="200px"
                    bg="gray.800"
                >
                    {/* Video thumbnail as background */}
                    {videoThumb && (
                        <Image
                            src={videoThumb}
                            onError={handleImageError}
                            alt="Video preview"
                            objectFit={displayMode === 'grid' ? "cover" : "contain"}
                            width={displayMode === 'grid' ? "100%" : "auto"}
                            height={displayMode === 'grid' ? "100%" : "auto"}
                            maxH={displayMode === 'grid' ? "none" : "100%"}
                            maxW={displayMode === 'grid' ? "none" : "100%"}
                            position={displayMode === 'grid' ? "static" : "absolute"}
                            top={displayMode === 'grid' ? "auto" : "0"}
                            left={displayMode === 'grid' ? "auto" : "0"}
                            right={displayMode === 'grid' ? "auto" : "0"}
                            bottom={displayMode === 'grid' ? "auto" : "0"}
                            margin={displayMode === 'grid' ? "0" : "auto"}
                            loading="lazy"
                        />
                    )}

                    {/* Dark overlay */}
                    <Box
                        position="absolute"
                        top="0"
                        left="0"
                        right="0"
                        bottom="0"
                        bg="rgba(0, 0, 0, 0.3)"
                    />

                    {/* Play button */}
                    <Icon
                        as={FaPlay}
                        boxSize="80px"
                        color="white"
                        opacity={0.9}
                        filter="drop-shadow(0 4px 6px rgba(0,0,0,0.3))"
                        position="absolute"
                        top="50%"
                        left="50%"
                        transform="translate(-50%, -50%)"
                        zIndex="1"
                    />

                    {/* Label */}
                    <Text
                        position="absolute"
                        bottom="30px"
                        left="50%"
                        transform="translateX(-50%)"
                        color="white"
                        fontSize="lg"
                        fontWeight="semibold"
                        textShadow="0 2px 4px rgba(0,0,0,0.5)"
                        zIndex="1"
                    >
                        Click to play video
                    </Text>
                </Box>
            );
        } else if (activeMediaType === 'pdf') {
            return (
                <Box
                    position="relative"
                    width="100%"
                    height="100%"
                    minH="200px"
                    bg="gray.100"
                >
                    <iframe
                        src={`${activeItem.pdf_url}#toolbar=0&navpanes=0&scrollbar=0`}
                        style={{
                            width: '100%',
                            height: '100%',
                            border: 'none',
                            pointerEvents: 'none', // Prevent interaction in preview
                        }}
                        title="PDF Preview"
                    />
                    {/* Overlay with click hint */}
                    <Box
                        position="absolute"
                        bottom="0"
                        left="0"
                        right="0"
                        bg="rgba(0, 0, 0, 0.7)"
                        py={4}
                        px={6}
                        display="flex"
                        alignItems="center"
                        justifyContent="center"
                        gap={3}
                    >
                        <Icon
                            as={FaFilePdf}
                            color="red.400"
                            boxSize="40px"
                        />
                        <Text
                            color="white"
                            fontSize="lg"
                            fontWeight="semibold"
                        >
                            Click to view full PDF
                        </Text>
                    </Box>
                </Box>
            );
        } else {
            return (
                <Image
                    src={activeItem?.big}
                    onError={handleImageError}
                    alt={`Image ${activeIndex + 1}`}
                    // "contain" in grid too: "cover" cropped tall images
                    // (covers/letters) at the top inside the 4/3 tile box
                    // (HK punch list #5) — the whole image must stay visible.
                    objectFit="contain"
                    width={displayMode === 'grid' ? "100%" : "auto"}
                    height={displayMode === 'grid' ? "100%" : "auto"}
                    maxH="100%"
                    maxW="100%"
                    pointerEvents="none"
                    loading="lazy"
                />
            );
        }
    };

    // Render thumbnail based on media type
    const renderThumbnail = (item, index) => {
        const mediaType = getMediaType(item);

        if (mediaType === 'video') {
            const videoThumb = videoThumbnails[item.video_url];

            return (
                <Box
                    position="relative"
                    width="100%"
                    height="132px"
                    bg="gray.800"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                    overflow="hidden"
                >
                    {/* Video thumbnail background */}
                    {videoThumb ? (
                        <Image
                            src={videoThumb}
                            onError={handleImageError}
                            alt={`Video thumbnail ${index + 1}`}
                            width="100%"
                            height="100%"
                            objectFit="cover"
                            position="absolute"
                            top="0"
                            left="0"
                            loading="lazy"
                        />
                    ) : null}

                    {/* Dark overlay */}
                    <Box
                        position="absolute"
                        top="0"
                        left="0"
                        right="0"
                        bottom="0"
                        bg="rgba(0, 0, 0, 0.4)"
                    />

                    {/* Play icon */}
                    <Icon
                        as={FaPlay}
                        boxSize="24px"
                        color="white"
                        opacity={0.9}
                        position="relative"
                        zIndex="1"
                    />
                </Box>
            );
        } else if (mediaType === 'pdf') {
            return (
                <Box
                    position="relative"
                    width="100%"
                    height="132px"
                    bg="gray.100"
                    overflow="hidden"
                >
                    <iframe
                        src={`${item.pdf_url}#toolbar=0&navpanes=0&scrollbar=0&page=1&view=FitH`}
                        style={{
                            position: 'absolute',
                            top: '0',
                            left: '0',
                            width: '200%',
                            height: '200px',
                            border: 'none',
                            transform: 'scale(0.5)',
                            transformOrigin: 'top left',
                            pointerEvents: 'none',
                        }}
                        title={`PDF Thumbnail ${index + 1}`}
                    />
                    {/* PDF Label with Icon - Bottom */}
                    <Box
                        position="absolute"
                        bottom="0"
                        left="0"
                        right="0"
                        bg="rgba(0, 0, 0, 0.75)"
                        px="8px"
                        py="2px"
                        display="flex"
                        alignItems="center"
                        justifyContent="center"
                        gap="6px"
                        lineHeight="1"
                    >
                        <Icon
                            as={FaFilePdf}
                            boxSize="14px"
                            color="red.400"
                        />
                        <Text
                            color="white"
                            fontSize="xs"
                            fontWeight="bold"
                            letterSpacing="wide"
                            lineHeight="1"
                        >
                            PDF
                        </Text>
                    </Box>
                </Box>
            );
        } else {
            return (
                <Image
                    src={item.small}
                    onError={handleImageError}
                    alt={`Thumbnail ${index + 1}`}
                    width="100%"
                    height="132px"
                    objectFit="cover"
                    loading="lazy"
                />
            );
        }
    };

    return (
        <Box className="lot-images-carousel-wrapper" width={displayMode === 'grid' ? "100%" : "auto"}>
            {/* Main Gallery */}
            <Box
                ref={galleryRef}
                className="my-gallery"
                position="relative"
                width={displayMode === 'grid' ? "100%" : "auto"}
            >
                {/* Main/Active Image Display */}
                <Box
                    className="current-zoomed-image active"
                    position="relative"
                    cursor="pointer"
                    borderRadius={displayMode === 'grid' ? "0" : "md"}
                    overflow="hidden"
                    bg="transparent"
                    minH="200px"
                    width={displayMode === 'grid' ? "100%" : "auto"}
                    onClick={handleMainImageClick}
                    onMouseEnter={() => setIsHovering(true)}
                    onMouseLeave={() => setIsHovering(false)}
                    transition={displayMode === 'featured' ? "none" : "all 0.2s"}
                    _hover={{
                        transform: displayMode === 'featured' ? 'none' : 'scale(1.01)',
                    }}
                >
                    {displayMode === 'featured' && isTransitioning ? (
                        /* Featured/Live-auction mode transition - Show both images sliding */
                        <>
                            {/* Previous image sliding out to left */}
                            <Box
                                position="absolute"
                                top="0"
                                left="0"
                                width="100%"
                                height="100%"
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                                sx={{
                                    animation: 'slideOut 0.8s ease-in-out',
                                    '@keyframes slideOut': {
                                        '0%': {
                                            transform: 'translateX(0)',
                                        },
                                        '100%': {
                                            transform: 'translateX(-100%)',
                                        }
                                    }
                                }}
                            >
                                <Image
                                    src={images[previousIndex]?.big}
                                    onError={handleImageError}
                                    alt={`Previous image`}
                                    objectFit={displayMode === 'grid' ? "cover" : "contain"}
                                    width={displayMode === 'grid' ? "100%" : "auto"}
                                    height={displayMode === 'grid' ? "100%" : "auto"}
                                    maxH={displayMode === 'grid' ? "none" : "100%"}
                                    maxW={displayMode === 'grid' ? "none" : "100%"}
                                    pointerEvents="none"
                                    loading="lazy"
                                />
                            </Box>

                            {/* New image sliding in from right */}
                            <Box
                                position="absolute"
                                top="0"
                                left="0"
                                width="100%"
                                height="100%"
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                                sx={{
                                    animation: 'slideIn 0.8s ease-in-out',
                                    '@keyframes slideIn': {
                                        '0%': {
                                            transform: 'translateX(100%)',
                                        },
                                        '100%': {
                                            transform: 'translateX(0)',
                                        }
                                    }
                                }}
                            >
                                {renderMainDisplay()}
                            </Box>
                        </>
                    ) : (
                        /* Normal display */
                        <Box
                            width="100%"
                            height="100%"
                            display={displayMode === 'grid' ? "block" : "flex"}
                            alignItems={displayMode === 'grid' ? "initial" : "center"}
                            justifyContent={displayMode === 'grid' ? "initial" : "center"}
                        >
                            {renderMainDisplay()}
                        </Box>
                    )}

                    {/* Loading Spinner Overlay */}
                    {isImageLoading && (
                        <Box
                            position="absolute"
                            top="0"
                            left="0"
                            right="0"
                            bottom="0"
                            display="flex"
                            alignItems="center"
                            justifyContent="center"
                            bg="rgba(0, 0, 0, 0.4)"
                            zIndex={3}
                        >
                            <Spinner
                                thickness="4px"
                                speed="0.65s"
                                color="white"
                                size="xl"
                            />
                        </Box>
                    )}

                    {/* Navigation Arrows and Controls - Grid mode */}
                    {displayMode === 'grid' && hasMultipleImages && (
                        <>
                            {/* Previous Arrow */}
                            <IconButton
                                icon={<ChevronLeftIcon boxSize={8} />}
                                position="absolute"
                                left="10px"
                                top="50%"
                                transform="translateY(-50%)"
                                onClick={handlePrevImage}
                                opacity={isHovering ? 1 : 0}
                                transition="opacity 0.2s"
                                colorScheme="blackAlpha"
                                bg="rgba(0, 0, 0, 0.5)"
                                color="white"
                                size="lg"
                                borderRadius="full"
                                _hover={{
                                    bg: 'rgba(0, 0, 0, 0.7)',
                                }}
                                zIndex={2}
                                aria-label="Previous image"
                            />

                            {/* Next Arrow */}
                            <IconButton
                                icon={<ChevronRightIcon boxSize={8} />}
                                position="absolute"
                                right="10px"
                                top="50%"
                                transform="translateY(-50%)"
                                onClick={handleNextImage}
                                opacity={isHovering ? 1 : 0}
                                transition="opacity 0.2s"
                                colorScheme="blackAlpha"
                                bg="rgba(0, 0, 0, 0.5)"
                                color="white"
                                size="lg"
                                borderRadius="full"
                                _hover={{
                                    bg: 'rgba(0, 0, 0, 0.7)',
                                }}
                                zIndex={2}
                                aria-label="Next image"
                            />
                        </>
                    )}

                    {/* Navigation Arrows and Controls - Featured and Live-auction mode */}
                    {displayMode === 'featured' && hasMultipleImages && (
                        <>
                            {/* Previous Arrow */}
                            <IconButton
                                icon={<ChevronLeftIcon boxSize={8} />}
                                position="absolute"
                                left="10px"
                                top="50%"
                                transform="translateY(-50%)"
                                onClick={handlePrevImage}
                                opacity={isHovering ? 1 : 0}
                                transition="opacity 0.2s"
                                colorScheme="blackAlpha"
                                bg="rgba(0, 0, 0, 0.5)"
                                color="white"
                                size="lg"
                                borderRadius="full"
                                _hover={{
                                    bg: 'rgba(0, 0, 0, 0.7)',
                                }}
                                zIndex={2}
                                aria-label="Previous image"
                            />

                            {/* Play/Pause Button */}
                            <IconButton
                                icon={isPaused ? <Icon as={FaPlay} boxSize={6} /> : <Icon as={FaPause} boxSize={6} />}
                                position="absolute"
                                left="50%"
                                top="50%"
                                transform="translate(-50%, -50%)"
                                onClick={togglePlayPause}
                                opacity={isHovering ? 1 : 0}
                                transition="opacity 0.2s"
                                colorScheme="blackAlpha"
                                bg="rgba(0, 0, 0, 0.5)"
                                color="white"
                                size="lg"
                                borderRadius="full"
                                _hover={{
                                    bg: 'rgba(0, 0, 0, 0.7)',
                                }}
                                zIndex={2}
                                aria-label={isPaused ? "Play slideshow" : "Pause slideshow"}
                            />

                            {/* Next Arrow */}
                            <IconButton
                                icon={<ChevronRightIcon boxSize={8} />}
                                position="absolute"
                                right="10px"
                                top="50%"
                                transform="translateY(-50%)"
                                onClick={handleNextImage}
                                opacity={isHovering ? 1 : 0}
                                transition="opacity 0.2s"
                                colorScheme="blackAlpha"
                                bg="rgba(0, 0, 0, 0.5)"
                                color="white"
                                size="lg"
                                borderRadius="full"
                                _hover={{
                                    bg: 'rgba(0, 0, 0, 0.7)',
                                }}
                                zIndex={2}
                                aria-label="Next image"
                            />
                        </>
                    )}
                </Box>
            </Box>

            {/* Image Count - Only in grid mode */}
            {displayMode === 'grid' && imageCount > 0 && (
                <Box className="images-count" textAlign="center">
                    <Text fontSize="sm" color="gray.600">
                        {imageCount} {t('item.photos')}
                    </Text>
                </Box>
            )}

            {/* Thumbnails - Only show if more than one image AND not in grid or featured mode AND hideNavigation is false */}
            {hasMultipleImages && displayMode !== 'grid' && displayMode !== 'featured' && !hideNavigation && (
                <>
                    <Box className="lot-image-thumbs" mt={3}>
                        <SimpleGrid minChildWidth="78px" spacing={2} className="inner-thumb-grid">
                            {images.map((image, index) => (
                                <Box
                                    key={index}
                                    position="relative"
                                    cursor="pointer"
                                    borderRadius="md"
                                    overflow="hidden"
                                    border="2px solid"
                                    borderColor={activeIndex === index ? 'blue.500' : 'transparent'}
                                    transition="all 0.2s"
                                    onClick={() => handleThumbnailClick(index)}
                                    _hover={{
                                        borderColor: activeIndex === index ? 'blue.600' : 'gray.300',
                                        transform: 'scale(1.05)'
                                    }}
                                    className={activeIndex === index ? 'active' : ''}
                                >
                                    {renderThumbnail(image, index)}
                                </Box>
                            ))}
                        </SimpleGrid>
                    </Box>

                    {/* Image Count */}
                    <Box className="images-count" mt={2} textAlign="center">
                        <Text fontSize="sm" color="gray.600">
                            {imageCount} {t('item.photos')}
                        </Text>
                    </Box>
                </>
            )}
        </Box>
    );
};

export default ItemImageGallery;
