import React, { useContext, useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { createPortal } from 'react-dom';
// Remaining Chakra primitives — the data table is still Chakra and
// restyled via class selectors. Switch / Badge kept for the per-row
// active toggle and status pill; restyle hooks added in SCSS.
import {
  Table, Thead, Tbody, Tr, Th, Td,
  Switch,
  useToast,
} from '@chakra-ui/react';
import { Search, X, Check } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import fetchData from '../utils/Util';
import { CircuitDropdown } from '../components/CircuitDropdown';

function decodeHtmlEntities(str) {
  if (!str) return '';
  const textarea = document.createElement('textarea');
  textarea.innerHTML = str;
  return textarea.value;
}

const UserInterests = () => {
  const { t, i18n } = useTranslation();
  const [categories, setCategories] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [sortConfig, setSortConfig] = useState({key: 'tree', direction: 'asc'});
  const [filterStatus, setFilterStatus] = useState('all');
  const [hierarchySearch, setHierarchySearch] = useState('');
  const [error, setError] = useState('')
  const toast = useToast();
  const config = useContext(ConfigContext);
  const [boUserID, setBoUserID] = useState(null);
  const searchContainerRef = useRef(null);
  const searchInputRef = useRef(null);
  const searchResultsRef = useRef(null);
  const [searchPos, setSearchPos] = useState(null);
  const [, setAvailableCategories] = useState([]);
  const [addedIds, setAddedIds] = useState(() => new Set());
  const [additionalInterests, setAdditionalInterests] = useState('');
  const [isSavingInterests, setIsSavingInterests] = useState(false);

  // Keep the portaled autocomplete popover anchored under the input.
  // Re-measure whenever the dropdown is visible — fires on each
  // render of the popover, which already happens on every keystroke
  // (searchQuery change drives the input re-render).
  const measureSearchPos = useCallback(() => {
    if (!searchInputRef.current) return;
    const rect = searchInputRef.current.getBoundingClientRect();
    setSearchPos({
      left: rect.left + window.scrollX,
      top: rect.bottom + window.scrollY + 6,
      width: rect.width,
    });
  }, []);

  useLayoutEffect(() => {
    if (!searchQuery) {
      setSearchPos(null);
      return undefined;
    }
    measureSearchPos();
    const onScroll = () => measureSearchPos();
    const onResize = () => measureSearchPos();
    window.addEventListener('scroll', onScroll, true);
    window.addEventListener('resize', onResize);
    return () => {
      window.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', onResize);
    };
  }, [searchQuery, searchResults, measureSearchPos]);

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
          return;
        }  
        // Get both sets of data before doing any state updates
        const [statsResponse, clientsResponse] = await Promise.all([
          // Auto categories fetch
          fetchData(
            `${config.siteData.backoffice_url_lang}/api/v1.0/client-stat?` +
            `filter[sale][value]=0` +
            `filter[category][value]=0` +
            `filter[category][operator]=<>` +
            `&client_uuid=${config.userData.uuid}` +
            `&fields=id,category,category_tid,weight,bids_sum,winning_bids_sum,winning_bids_count,bids_count,tree,status,browse_url,favorites_count`,
            {
              mockData: 'api-me',
              headers: { 'access-token': config.userData.bo_access_token },
            }
          ),
          // Non-auto categories fetch
          fetchData(
            `${config.siteData.backoffice_url}/api/v1.0/datatable-clients?fields=categories,id,additional_interests&filter[uuid][value]=${config.userData.uuid}`,
            {
              mockData: 'api-me',
              headers: { 'access-token': config.userData.bo_access_token },
            }
          )
        ]);
  
        if (!statsResponse.ok) throw new Error(statsResponse.title || t('myAccount.networkError'));
        if (!clientsResponse.ok) throw new Error(clientsResponse.title || t('myAccount.networkError'));
  
        const [statsResult, clientsResult] = await Promise.all([
          statsResponse.json(),
          clientsResponse.json()
        ]);

        if (clientsResult.data == null || clientsResult.data[0] == null) {
          return;
        }

        setBoUserID(clientsResult.data[0].id);
        setAdditionalInterests(clientsResult.data[0].additional_interests || '');
  
        // Transform auto categories
        const autoCategories = statsResult.data
          .filter(item => item.category_tid)  // Filter out items where category_tid is false/null/undefined
          .map(item => ({
            id: parseInt(item.id),
            cat_id: item.category_tid,
            name: item.category[i18n.language] || item.category.en,
            tree: cleanTreeLabel(item.tree[i18n.language] || item.tree.en),
            browse_url: item.browse_url,
            isSelected: item.status === 'active',
            bidCount: parseInt(item.bids_count) || 0,
            wonCount: parseInt(item.winning_bids_count) || 0,
            weight: item.weight || 0,
            favoriteCount: (parseInt(item.favorites_count) || 0),
            isAuto: 1
          }));
  
        // Create a Set of auto category IDs for quick lookup
        const autoCategoryIds = new Set(autoCategories.map(cat => cat.cat_id.toString()));

        // Only include non-auto categories that don't exist in auto categories
        const nonAutoCategories = clientsResult.data?.[0]?.categories
          ? clientsResult.data[0].categories
            .filter(item => !autoCategoryIds.has(item.id.toString()))  // Convert to string here too
            .map(item => ({
              id: parseInt(item.id),
              cat_id: item.id,
              name: item.label[i18n.language] || item.label.en,
              tree: cleanTreeLabel(item.tree_label[i18n.language] || item.tree_label.en),
              browse_url: item.browse_url,
              isSelected: true,
              bidCount: 0,
              wonCount: 0,
              weight: item.weight || 0,
              favoriteCount: 0,
              isAuto: 0
            }))
          : [];
  
        // Single state update with all categories
        setCategories([...autoCategories, ...nonAutoCategories]);
        setError('');
  
      } catch (error) {
        console.error('Error fetching categories:', error);
        setError(error.message);
      }
    };
  
    fetchAllData();
  }, [config.siteData, config.userData, t, i18n.language]);

  // Function to search categories
  const fetchAvailableCategories = async (searchString = '') => {
    if (!config.siteData?.backoffice_url || !config.userData?.bo_access_token) {
      return;
    }

    try {
      const response = await fetch(
          `${config.siteData.backoffice_url_lang}/api/v1.0/categories?` +
          `autocomplete[string]=${encodeURIComponent(searchString)}` +
          `&autocomplete[use_tree_label]=1` +
          `&autocomplete[extended]=1` +
          `&sort=weight`, {
            headers: {
              'access-token': config.userData.bo_access_token,
              'Content-Type': 'application/json',
            }
          });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to fetch categories');
      }

      const result = await response.json();
      // Convert data object into array of categories
      const formattedCategories = Object.entries(result.data).map(([id, categoryData]) => {
        const clientLang = i18n.language;
        return {
          id: parseInt(id),
          name: categoryData[clientLang]?.name || categoryData.en.name,  // Use client language with English fallback
          tree: cleanTreeLabel(categoryData[clientLang]?.tree || categoryData.en.tree),  // Use client language with English fallback
        };
      });

      setError(''); // Clear any previous errors
      setAvailableCategories(formattedCategories);
      return formattedCategories;
    } catch (error) {
      console.error('Error fetching categories:', error);
      setError(error.message || 'Failed to fetch categories');
      setAvailableCategories([]); // Clear results on error
      return [];
    }
  };

  const cleanTreeLabel = (tree) => {
    if (!tree) return '';
        const pipeIndex = tree.indexOf(' | ');
    if (pipeIndex > 0 && /^\d+/.test(tree)) {
      return tree.substring(pipeIndex + 3);
    }    
    return tree;
  };

  useEffect(() => {
    function handleClickOutside(event) {
      // The results dropdown is portaled to document.body, so it lives
      // outside searchContainerRef — check it separately or clicking an
      // "Add" button would unmount the portal before its onClick fires.
      const insideContainer =
        searchContainerRef.current && searchContainerRef.current.contains(event.target);
      const insideResults =
        searchResultsRef.current && searchResultsRef.current.contains(event.target);
      if (!insideContainer && !insideResults) {
        setSearchQuery('');
        setSearchResults([]);
        setAddedIds(new Set());
      }
    }

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleSort = (key) => {
    setSortConfig((prev) => {
      const newConfig = {
        key, // Use the passed key instead of hardcoding 'tree'
        direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
      };
      return newConfig;
    });
  };

  const getSortedAndFilteredCategories = () => {
    let filtered = categories.filter(cat => {
      // Status filter
      const statusMatch = filterStatus === 'all' || 
        (filterStatus === 'active' && cat.isSelected) ||
        (filterStatus === 'inactive' && !cat.isSelected);
      
      // Hierarchy search filter
      const searchMatch = !hierarchySearch || 
        decodeHtmlEntities(cat.tree).toLowerCase().includes(hierarchySearch.toLowerCase());
      
      return statusMatch && searchMatch;
    });

    return filtered.sort((a, b) => {
      let compareResult = 0;
      if (sortConfig.key === 'name') {
        const nameA = decodeHtmlEntities(a.name || '');
        const nameB = decodeHtmlEntities(b.name || '');
        compareResult = nameA.localeCompare(nameB);
      } else if (sortConfig.key === 'tree') {
        const weightA = parseInt(a.weight) || 0;
        const weightB = parseInt(b.weight) || 0;
        compareResult = weightA - weightB;
      } else {
        const aValue = parseInt(a[sortConfig.key]) || 0;
        const bValue = parseInt(b[sortConfig.key]) || 0;
        compareResult = aValue - bValue;
      }
      return sortConfig.direction === 'asc' ? compareResult : -compareResult;
    });
  };

  const handleSearch = async (query) => {
    try {
      if (!query.trim()) {
        setSearchResults([]);
        setAddedIds(new Set());
        setError('');
        return;
      }

      // First fetch available categories from API. Use the returned list —
      // reading `availableCategories` state here would be one render stale.
      const fetchedCategories = (await fetchAvailableCategories(query)) || [];

      // Get opted-out categories with bids
      const optedOutWithBids = categories.filter(cat =>
          !cat.isSelected &&
          cat.bidCount > 0 &&
          (cat.name.toLowerCase().includes(query.toLowerCase()) ||
              cat.tree.toLowerCase().includes(query.toLowerCase()))
      );

      // Get new categories from our fetched results
      const newCategories = fetchedCategories.filter(category =>
          !categories.some(c => c.id === category.id)
      );

      setSearchResults([
        ...optedOutWithBids,
        ...newCategories
      ]);

    } catch (error) {
      console.error('Error during search:', error);
      setError(error.message || 'Search failed');
      setSearchResults([]);
    }
  };

  const handleAddCategory = (category) => {
    // If it's an existing category that was opted out
    if (categories.some(c => c.id === category.id)) {
      handleToggleCategory(category.id);
      // Keep the row in the dropdown but flag it as added so the
      // inline "Added to list" confirmation shows right where the
      // user clicked (the bottom toast is easy to miss).
      setAddedIds(prev => new Set(prev).add(category.id));
      return;
    }

    // If it's a new category
    const newCategory = {
      ...category,
      cat_id: category.id,
      tree: cleanTreeLabel(category.tree),
      isSelected: true,
      bidCount: 0,
      wonCount: 0,
      favoriteCount: 0,
      weight: -1,
      // Means is a self added cat.
      isAuto: 0
    };

    // Update phone/ date to formatted values.
    const updatedData = {
      categories: [
        ...categories,
        newCategory
      ].filter(cat => cat.isAuto === 0)
          .map(cat => ({
            id: cat.id,
          }))
    };

    fetch(`${config.siteData.backoffice_url_lang}/api/datatable-clients/${boUserID}`, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        'access-token': config.userData.bo_access_token,
      },
      body: JSON.stringify(updatedData),
    })
        .then((response) => {
          if (!response.ok) {
            response.json().then((res) => setError(res.title || 'Network error when updating account'));
          } else {
            setCategories(prev => [...prev, newCategory].sort((a, b) => b.weight - a.weight));
            // Keep the row visible with an inline "Added to list"
            // confirmation until the dropdown is closed.
            setAddedIds(prev => new Set(prev).add(category.id));
            toast({
              title: 'Category Added',
              status: 'success',
              duration: 3000,
              isClosable: true,
            });
          }

        })
        .catch((error) => {
          setError(error.message);
        });
  };

  const handleSaveAdditionalInterests = async () => {
    setIsSavingInterests(true);
    setError('');

    try {
      const response = await fetch(
        `${config.siteData.backoffice_url_lang}/api/datatable-clients/${boUserID}`,
        {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'access-token': config.userData.bo_access_token,
          },
          body: JSON.stringify({
            additional_interests: additionalInterests
          }),
        }
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.title || 'Failed to save additional interests');
      }

      toast({
        title: t('userInterests.additionalInterestsSaved'),
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    } catch (error) {
      console.error('Error saving additional interests:', error);
      setError(error.message || 'Failed to save additional interests');
    } finally {
      setIsSavingInterests(false);
    }
  };

  const handleToggleCategory = async (categoryId) => {
    setCategories(prev => {
      const categoryToUpdate = prev.find(cat => cat.id === categoryId);

      if (!categoryToUpdate) return prev;

      // Handle API updates based on category type
      if (categoryToUpdate.isAuto === 1) {
        // Update client-stat API for auto categories
        fetch(`${config.siteData.backoffice_url_lang}/api/v1.0/client-stat/${categoryId}`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'access-token': config.userData.bo_access_token,
          },
          body: JSON.stringify({
            status: categoryToUpdate.isSelected ? 'inactive' : 'active'
          }),
        }).catch(error => {
              console.error('Error updating category status:', error);
              setError(error.message || 'Failed to update category status');
            });
      } else if (categoryToUpdate.isAuto === 0 && categoryToUpdate.isSelected) {
        // Update datatable-clients API for manual categories being deactivated
        const updatedData = {
          categories: prev
              .filter(cat => cat.isAuto === 0 && cat.id !== categoryId)
              .map(cat => ({
                id: cat.id,
              }))
        };

        fetch(`${config.siteData.backoffice_url_lang}/api/datatable-clients/${boUserID}`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'access-token': config.userData.bo_access_token,
          },
          body: JSON.stringify(updatedData),
        })
            .catch(error => {
              console.error('Error removing category:', error);
              setError(error.message || 'Failed to remove category');
            });
      }

      const updatedCategories = prev.map(cat => {
        if (cat.id === categoryId) {
          // Always keep the category but update its selected state
          return {...cat, isSelected: !cat.isSelected};
        }
        return cat;
      });

      // Filter out null values (removed categories)
      const filteredCategories = updatedCategories.filter(cat => cat !== null);

      toast({
        title: filteredCategories.length < prev.length ?
            'Category Removed' :
            'Preference Updated',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });

      return filteredCategories;
    });
  };

  const sortedCategories = getSortedAndFilteredCategories();
  const arrow = (key) =>
    sortConfig.key === key
      ? sortConfig.direction === 'asc' ? ' ↑' : ' ↓'
      : '';

  return (
    <div className="my-interests-page">
      <section className="rc-card account-card my-interests">
        <header className="card-head">
          <h2 className="page-title">{t('userInterests.title')}</h2>
        </header>

        <div className="card-body">
          {error && (
            <div className="cream-note cream-note--error" role="alert">
              <span>{error}</span>
              <button
                type="button"
                className="cream-note__close"
                aria-label="Dismiss"
                onClick={() => setError('')}
              >
                <X size={14} />
              </button>
            </div>
          )}

          <p className="auth-intro">
            <span>{t('userInterests.pageDescription')}</span>
          </p>

          {/* Add-category search box */}
          <div className="interests-search-card">
            <h3 className="bid-limits__section-title">{t('userInterests.searchCategories')}</h3>
            <p className="bid-limits__help">{t('userInterests.searchInstructions')}</p>

            <div className="interests-search" ref={searchContainerRef}>
              <Search size={16} className="favorites-search__icon" aria-hidden="true" />
              <input
                type="search"
                ref={searchInputRef}
                className="field-input favorites-search__input interests-search__input"
                value={searchQuery}
                onChange={async (e) => {
                  setSearchQuery(e.target.value);
                  await handleSearch(e.target.value);
                }}
                placeholder={t('userInterests.searchPlaceholder')}
                aria-label={t('userInterests.searchCategories')}
              />
              {searchQuery && (
                <button
                  type="button"
                  className="interests-search__clear"
                  aria-label="Clear search"
                  onClick={() => {
                    setSearchQuery('');
                    setSearchResults([]);
                    setAddedIds(new Set());
                  }}
                >
                  <X size={14} />
                </button>
              )}

              {searchQuery && searchPos && createPortal(
                <div className="circuit-user-ui">
                  <div
                    ref={searchResultsRef}
                    className="interests-search__results interests-search__results--portaled"
                    role="listbox"
                    style={{
                      left: `${searchPos.left}px`,
                      top: `${searchPos.top}px`,
                      width: `${searchPos.width}px`,
                    }}
                  >
                    {searchResults.length > 0 ? (
                      searchResults.map((category) => {
                        const isAdded = addedIds.has(category.id);
                        return (
                          <div
                            key={category.id}
                            className={`interests-search__result${isAdded ? ' is-added' : ''}`}
                          >
                            <span className="interests-search__result-tree">
                              {decodeHtmlEntities(category.tree)}
                            </span>
                            {isAdded ? (
                              <span className="interests-search__added">
                                <Check size={14} aria-hidden="true" />
                                {t('userInterests.addedToList')}
                              </span>
                            ) : (
                              <button
                                type="button"
                                className="bid-limit-submit"
                                onClick={() => handleAddCategory(category)}
                              >
                                {category.isAuto === 1
                                  ? t('userInterests.reactivate')
                                  : t('userInterests.add')}
                              </button>
                            )}
                          </div>
                        );
                      })
                    ) : (
                      <p className="interests-search__empty">
                        {t('userInterests.noSearchResults')}
                      </p>
                    )}
                  </div>
                </div>,
                document.body
              )}
            </div>
          </div>

          {/* My Categories section */}
          <div className="interests-categories">
            <h3 className="bid-limits__section-title">{t('userInterests.myCategories')}</h3>

            <div className="favorites-toolbar interests-toolbar">
              <div className="favorites-search">
                <Search size={16} className="favorites-search__icon" aria-hidden="true" />
                <input
                  type="search"
                  placeholder={t('userInterests.searchHierarchy', { defaultValue: 'Search hierarchy…' })}
                  onChange={(e) => setHierarchySearch(e.target.value)}
                  className="field-input favorites-search__input"
                  aria-label="Search hierarchy"
                />
              </div>

              <CircuitDropdown
                value={filterStatus}
                onChange={(v) => setFilterStatus(v)}
                ariaLabel={t('userInterests.status')}
                options={[
                  { value: 'all',      label: t('userInterests.filterAll', { defaultValue: 'Show All Categories' }) },
                  { value: 'active',   label: t('userInterests.filterActive', { defaultValue: 'Active Only' }) },
                  { value: 'inactive', label: t('userInterests.filterInactive', { defaultValue: 'Inactive Only' }) },
                ]}
              />
            </div>

            {/* Desktop table */}
            <div className="interests-table-wrap">
              <Table variant="simple">
                <Thead>
                  <Tr>
                    <Th>
                      <button type="button" className="interests-sort" onClick={() => handleSort('name')}>
                        {t('userInterests.category')}{arrow('name')}
                      </button>
                    </Th>
                    <Th>
                      <button type="button" className="interests-sort" onClick={() => handleSort('tree')}>
                        {t('userInterests.categoryHierarchy')}{arrow('tree')}
                      </button>
                    </Th>
                    <Th>
                      <button type="button" className="interests-sort" onClick={() => handleSort('bidCount')}>
                        {t('userInterests.bids')}{arrow('bidCount')}
                      </button>
                    </Th>
                    <Th>
                      <button type="button" className="interests-sort" onClick={() => handleSort('wonCount')}>
                        {t('userInterests.won')}{arrow('wonCount')}
                      </button>
                    </Th>
                    <Th>
                      <button type="button" className="interests-sort" onClick={() => handleSort('favoriteCount')}>
                        {t('userInterests.favorites')}{arrow('favoriteCount')}
                      </button>
                    </Th>
                    <Th>{t('userInterests.status')}</Th>
                    <Th>{t('userInterests.action')}</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {sortedCategories.map((category) => (
                    <Tr
                      key={`${category.id}-${category.isAuto ? 'auto' : 'manual'}`}
                      className={category.isSelected ? '' : 'is-inactive'}
                    >
                      <Td>
                        <a
                          href={category.browse_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="interests-cat-link"
                          title={t('userInterests.browseCategory')}
                        >
                          {decodeHtmlEntities(category.name)}
                        </a>
                      </Td>
                      <Td className="interests-tree">{decodeHtmlEntities(category.tree)}</Td>
                      <Td className="interests-num">{category.bidCount > 0 ? category.bidCount : '-'}</Td>
                      <Td className="interests-num">{category.wonCount > 0 ? category.wonCount : '-'}</Td>
                      <Td className="interests-num">{category.favoriteCount > 0 ? category.favoriteCount : '-'}</Td>
                      <Td>
                        <span
                          className={`interests-pill${category.isSelected ? ' is-active' : ' is-inactive'}`}
                        >
                          {category.isSelected ? t('userInterests.active') : t('userInterests.inactive')}
                        </span>
                      </Td>
                      <Td>
                        <Switch
                          isChecked={category.isSelected}
                          onChange={() => handleToggleCategory(category.id)}
                        />
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </div>

            {/* Mobile cards */}
            <div className="interests-mobile">
              {sortedCategories.map((category) => (
                <div
                  key={`m-${category.id}-${category.isAuto ? 'auto' : 'manual'}`}
                  className={`interests-card${category.isSelected ? '' : ' is-inactive'}`}
                >
                  <div className="interests-card__head">
                    <a
                      href={category.browse_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="interests-cat-link"
                    >
                      {decodeHtmlEntities(category.name)}
                    </a>
                    <Switch
                      size="sm"
                      isChecked={category.isSelected}
                      onChange={() => handleToggleCategory(category.id)}
                    />
                  </div>
                  <p className="interests-card__tree">{decodeHtmlEntities(category.tree)}</p>
                  <div className="interests-card__stats">
                    <span>Bids: <strong>{category.bidCount > 0 ? category.bidCount : '-'}</strong></span>
                    <span>Won: <strong>{category.wonCount > 0 ? category.wonCount : '-'}</strong></span>
                    <span>Fav: <strong>{category.favoriteCount > 0 ? category.favoriteCount : '-'}</strong></span>
                  </div>
                  <span
                    className={`interests-pill${category.isSelected ? ' is-active' : ' is-inactive'}`}
                  >
                    {category.isSelected ? t('userInterests.active') : t('userInterests.inactive')}
                  </span>
                </div>
              ))}
            </div>

            <p className="interests-explanation">
              {t('userInterests.browseExplanation')}
            </p>

            {/* Additional interests — 2-column split: intro on the
                left, textarea + save button on the right. */}
            <div className="interests-additional">
              <div className="interests-additional__intro">
                <h3 className="interests-additional__title">
                  {t('userInterests.additionalInterests')}
                </h3>
                <p className="interests-additional__help">
                  {t('userInterests.additionalInterestsHelp')}
                </p>
              </div>
              <div className="interests-additional__form">
                <textarea
                  className="field-textarea interests-additional__textarea"
                  value={additionalInterests}
                  onChange={(e) => setAdditionalInterests(e.target.value)}
                  placeholder={t('userInterests.additionalInterestsPlaceholder')}
                  rows={5}
                />
                <div className="interests-additional__actions">
                  <button
                    type="button"
                    className="bid-limit-submit"
                    onClick={handleSaveAdditionalInterests}
                    disabled={isSavingInterests}
                  >
                    {isSavingInterests
                      ? t('userInterests.saving')
                      : t('userInterests.saveAdditionalInterests')}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default UserInterests;