import React, { useState, useEffect, useContext, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import { useDataCache } from '../services/DataCache';
import ItemPage from './ItemPage'
import Facets from './SearchFacet'
import SaleInfo from './SaleInfo'
import FeaturedItems from './FeaturedItems'
import { CircuitDropdown } from '../components/CircuitDropdown';
import {
    Box,
    Text,
    Input,
    Flex,
    Spinner,
    Tooltip,
} from '@chakra-ui/react';
import { FaTh, FaThList } from 'react-icons/fa';
import { QuestionOutlineIcon } from '@chakra-ui/icons';
import { isCacheResetRequested } from '../utils/resetParam';
import DataSourceDebugPanel from '../components/DataSourceDebugPanel';

// Define which fields are text inputs (no auto-submit - require clicking Search button)
const TEXT_INPUT_FIELDS = [
    'lotNumber',
    'searchText',
    'openingPriceRange',
    'soldForRange',
    'lotNumberRange',
    'catalogName',
    'catalogNumber'
];

// Define which select fields trigger auto-submit
const AUTO_SUBMIT_SELECTS = ['soldStatus', 'favoritesOnly', 'sortField', 'itemsPerPage'];

// Helper function to check if we have any actual search criteria
const checkHasSearchCriteria = (filterState, facetState, saleNidValue) => {
    return (
        filterState.lotNumber ||
        filterState.searchText ||
        filterState.soldStatus ||
        filterState.favoritesOnly !== '0' ||
        filterState.openingPriceRange ||
        filterState.soldForRange ||
        filterState.catalogName ||
        filterState.catalogNumber ||
        Object.keys(facetState).some(key => facetState[key].length > 0) ||
        saleNidValue
    );
};

const SalePage = () => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSaleSearch, fetchItemsByIds, fetchItem, fetchCatalogs } = useDataCache();

    // State Management
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [successMessage, setSuccessMessage] = useState(null);

    // Helper function to check if we're in init state (no search params)
    const isInitState = () => {
        const params = new URLSearchParams(window.location.search);
        // Check if there are no search/filter parameters
        return params.toString() === '';
    };

    // Helper function to parse URL parameters on initial load
    const parseUrlFilters = () => {
        const params = new URLSearchParams(window.location.search);
        const parsedFilters = {
            lotNumber: '',
            searchText: '',
            soldStatus: '',
            favoritesOnly: '0',
            openingPriceRange: '',
            soldForRange: '',
            lotNumberRange: '',
            catalogName: '',
            catalogNumber: '',
            itemsPerPage: 25,
            sortField: 'field_lot_number'
        };
        const parsedFacets = {};

        // Parse all URL parameters
        for (const [key, value] of params.entries()) {
            // Check for filter parameters like filter[field_category][values]
            const filterMatch = key.match(/^filter\[([^\]]+)\]\[([^\]]+)\]$/);

            if (filterMatch) {
                const fieldName = filterMatch[1];
                const filterType = filterMatch[2];

                // Handle facet filters (values parameter with operator=IN)
                if (filterType === 'values' && params.get(`filter[${fieldName}][operator]`) === 'IN') {
                    // Split comma-separated values and store as array
                    parsedFacets[fieldName] = value.split(',').filter(v => v.trim());
                }
                // Handle range filters (min/max)
                else if (filterType === 'min' || filterType === 'max') {
                    const minValue = params.get(`filter[${fieldName}][min]`) || '';
                    const maxValue = params.get(`filter[${fieldName}][max]`) || '';

                    // Map field names to filter state properties
                    if (fieldName === 'field_opening_price') {
                        parsedFilters.openingPriceRange = minValue && maxValue ? `${minValue}-${maxValue}` : minValue;
                    } else if (fieldName === 'field_sold_for_amount') {
                        parsedFilters.soldForRange = minValue && maxValue ? `${minValue}-${maxValue}` : minValue;
                    } else if (fieldName === 'field_lot_number') {
                        parsedFilters.lotNumberRange = minValue && maxValue ? `${minValue}-${maxValue}` : minValue;
                    }
                }
                // Handle single value filters
                else if (filterType === 'value') {
                    if (fieldName === 'field_lot_number') {
                        parsedFilters.lotNumber = value;
                    } else if (fieldName === 'field_sold_status') {
                        parsedFilters.soldStatus = value;
                    } else if (fieldName === 'my_favorites') {
                        parsedFilters.favoritesOnly = value;
                    } else if (fieldName === 'field_catalog_ref') {
                        parsedFilters.catalogName = value;
                    } else if (fieldName === 'field_catalog_number') {
                        parsedFilters.catalogNumber = value;
                    }
                }
            }
            // Handle direct parameters
            else if (key === 'lotNumberRange') {
                parsedFilters.lotNumberRange = value;
            } else if (key === 'sort') {
                parsedFilters.sortField = value;
            } else if (key === 'range') {
                parsedFilters.itemsPerPage = parseInt(value, 10) || 25;
            } else if (key === 'search') {
                // Handle search text parameter (matches PHP $_GET['search'])
                parsedFilters.searchText = value;
            }
        }

        return { filters: parsedFilters, facets: parsedFacets };
    };

    // Search/Filter states
    // Split into two states:
    // - filters: applied filters that trigger search (selects + submitted text inputs)
    // - inputValues: pending text input values (not yet applied)
    const [filters, setFilters] = useState(() => {
        const { filters } = parseUrlFilters();
        return filters;
    });

    // Separate state for text inputs (don't trigger auto-submit)
    const [inputValues, setInputValues] = useState(() => {
        const { filters } = parseUrlFilters();
        // Build inputValues object from TEXT_INPUT_FIELDS constant
        return TEXT_INPUT_FIELDS.reduce((acc, field) => {
            acc[field] = filters[field];
            return acc;
        }, {});
    });

    // Results and facets
    const [results, setResults] = useState(null);
    const [activeFacets, setActiveFacets] = useState(() => {
        const { facets } = parseUrlFilters();
        return facets;
    });
    const [saleNid, setSaleNid] = useState(null);
    const [showFeatured, setShowFeatured] = useState(false);
    const [debugMode, setDebugMode] = useState(false);
    const [catalogs, setCatalogs] = useState([]);
    const [hasSubmitted, setHasSubmitted] = useState(() => {
        // If there are URL params or sale context, we're not in init state
        return !isInitState() || !!document.getElementById('ca-sale-page')?.getAttribute('data-sale-nid');
    });
    const [catalogErrors, setCatalogErrors] = useState({ name: false, number: false });
    const [facetResetTrigger, setFacetResetTrigger] = useState(0);

    // Track if data attributes have been initialized
    const [dataAttributesInitialized, setDataAttributesInitialized] = useState(false);
    const [currentPage, setCurrentPage] = useState(() => {
        // Read page from URL on initial load
        const params = new URLSearchParams(window.location.search);
        const pageParam = params.get('page');
        return pageParam ? parseInt(pageParam, 10) : 1;
    });
    const [viewMode, setViewMode] = useState(() => {
        const saved = localStorage.getItem('sale_viewMode');
        return saved || 'list';
    });
    const [showAdvanced, setShowAdvanced] = useState(() => {
        // Check if we're in a specific sale view
        const container = document.getElementById('ca-sale-page');
        const hasSaleNid = container?.getAttribute('data-sale-nid');

        // If in init state (global search), always show advanced search
        if (isInitState() && !hasSaleNid) {
            return true;
        }

        // Otherwise use localStorage preference, defaulting to closed
        const saved = localStorage.getItem('sale_showAdvanced');
        return saved === 'true';
    });

    // URL Building
    const buildSearchUrl = useCallback(() => {
        // Build base URL with search term as path segment (if provided)
        let baseUrl = `${config.siteData.backoffice_url_lang}/api/v1.0/sale-search`;

        // Add search text as path segment (not query parameter)
        if (filters.searchText) {
            const trimmedSearch = filters.searchText.trim();
            if (trimmedSearch) {
                // Encode the search term for URL path
                baseUrl += `/${encodeURIComponent(trimmedSearch)}`;
            }
        }

        const params = new URLSearchParams();

        // Add basic filters
        if (filters.lotNumber) params.append('filter[field_lot_number][value]', filters.lotNumber);
        // searchText is now in the path, not in query params
        if (filters.soldStatus) params.append('filter[field_sold_status][value]', filters.soldStatus);
        if (filters.favoritesOnly) params.append('filter[my_favorites][value]', filters.favoritesOnly);

        // Parse and add opening price range (format: "min-max" or just "min")
        if (filters.openingPriceRange) {
            const rangeParts = filters.openingPriceRange.split('-').map(s => s.trim());
            if (rangeParts[0]) params.append('filter[field_opening_price][min]', rangeParts[0]);
            if (rangeParts[1]) params.append('filter[field_opening_price][max]', rangeParts[1]);
        }

        // Parse and add sold for range (format: "min-max" or just "min")
        if (filters.soldForRange) {
            const rangeParts = filters.soldForRange.split('-').map(s => s.trim());
            if (rangeParts[0]) params.append('filter[field_sold_for_amount][min]', rangeParts[0]);
            if (rangeParts[1]) params.append('filter[field_sold_for_amount][max]', rangeParts[1]);
        }

        // Parse and add lot number range (format: "min-max" or just "min")
        if (filters.lotNumberRange) {
            const rangeParts = filters.lotNumberRange.split('-').map(s => s.trim());
            if (rangeParts[0]) params.append('filter[field_lot_number][min]', rangeParts[0]);
            if (rangeParts[1]) params.append('filter[field_lot_number][max]', rangeParts[1]);
        }

        // Add catalog filters (both must be present to apply)
        if (filters.catalogName && filters.catalogNumber) {
            params.append('filter[field_catalog_ref][value]', filters.catalogName);
            params.append('filter[field_catalog_number][value]', filters.catalogNumber);
        }

        // Add facets
        Object.entries(activeFacets).forEach(([fieldName, values]) => {
            if (values.length > 0) {
                params.append(`filter[${fieldName}][values]`, values.join(','));
                params.append(`filter[${fieldName}][operator]`, 'IN');
            }
        });

        // Add required fixed filters
        // Sale NID filter - always required
        if (saleNid) {
            params.append('filter[field_sale][value]', saleNid);
        }

        // Language filter - always required (map 'zh' to 'zh-hans' for Chinese)
        const languageValue = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        params.append('filter[language][value]', languageValue);

        // Check if we have any actual search criteria (filters, facets, or sale context)
        const hasSearchCriteria = checkHasSearchCriteria(filters, activeFacets, saleNid);

        // Only use range=0 (init mode) if we have no search criteria AND haven't submitted yet
        // Once search is clicked (hasSubmitted=true), always show results even without criteria
        const inInitMode = !hasSearchCriteria && !hasSubmitted;

        // Add pagination and sorting
        params.append('sort', filters.sortField);
        params.append('range', inInitMode ? 0 : filters.itemsPerPage);
        params.append('page', currentPage - 1); // Convert from 1-based (UI) to 0-based (API)

        const fullUrl = `${baseUrl}?${params.toString()}`;
        return fullUrl;
    }, [filters, activeFacets, saleNid, hasSubmitted, currentPage, i18n.language, config.siteData]);

    // ---------------
    // Fetch Handler
    // ---------------
    // Data Fetching
    // Note: TEXT_INPUT_FIELDS changes don't trigger this - only applied filters (from form submit or AUTO_SUBMIT_SELECTS changes)
    const getSaleResults = useCallback(async () => {
        setIsLoading(true);
        setError(null);

        try {
            // First fetch search results using DataCache. `?reset=1` on the
            // host page bypasses the client caches and travels to the API.
            const url = buildSearchUrl();
            const searchData = await fetchSaleSearch(
                config.siteData.backoffice_url,
                url,
                config.userData?.bo_access_token,
                { reset: isCacheResetRequested() }
            );

            // Check if we have any actual search criteria (same logic as in buildSearchUrl)
            const hasSearchCriteria = checkHasSearchCriteria(filters, activeFacets, saleNid);

            // If in init mode (no search criteria AND haven't submitted), don't fetch items - only show facets
            // Once search is clicked (hasSubmitted=true), always show results even without criteria
            if (!hasSearchCriteria && !hasSubmitted) {
                setResults({
                    data: [],
                    count: searchData.count || 0,
                    facets: searchData.facets || {},
                    facets_titles: searchData.facets_titles || {}
                });
            } else {
                // Extract IDs and fetch detailed item data
                const itemIds = searchData.data
                    .filter(item => item.entity_id)
                    .map(item => item.entity_id);

                if (itemIds.length > 0) {
                    const language = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
                    const itemsResult = await fetchItemsByIds(
                        config.siteData.backoffice_url,
                        itemIds,
                        language
                    );

                    // Also fetch items from bid server using multiple UUID fetch
                    // Extract UUIDs from items result
                    const itemUuids = itemsResult.data
                        .filter(item => item.uuid)
                        .map(item => item.uuid);

                    if (itemUuids.length > 0) {
                        // Fire-and-forget: warm the bid server cache in the background.
                        // The render only needs itemsResult (backoffice data); child
                        // components will read bid server data from the cache when ready.
                        // `?reset=1` travels to the bid server too (busts Varnish).
                        fetchItem(itemUuids, null, { reset: isCacheResetRequested() }).catch(err => {
                            console.error('Failed to fetch items from bid server:', err);
                        });
                    }

                    // Preserve count and facets from search response
                    itemsResult.count = searchData.count || 0;
                    itemsResult.facets = searchData.facets || {};
                    itemsResult.facets_titles = searchData.facets_titles || {};
                    setResults(itemsResult);
                } else {
                    // When no items found, still set results with facets data
                    setResults({
                        data: [],
                        count: searchData.count || 0,
                        facets: searchData.facets || {},
                        facets_titles: searchData.facets_titles || {}
                    });
                }
            }

            setSuccessMessage(null);
        } catch (err) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    }, [buildSearchUrl, fetchSaleSearch, fetchItemsByIds, fetchItem, filters, activeFacets, saleNid, hasSubmitted, i18n.language, config.siteData, config.userData]);

    // ---------------
    // Read Sale NID, show-featured, and debug from data attributes
    // ---------------
    useEffect(() => {
        const container = document.getElementById('ca-sale-page');
        if (container) {
            const nid = container.getAttribute('data-sale-nid');
            if (nid) {
                setSaleNid(nid);
                // If we're viewing a specific sale, exit init state and show items
                setHasSubmitted(true);
            }

            const showFeaturedAttr = container.getAttribute('data-show-featured');
            setShowFeatured(showFeaturedAttr === 'true');

            const debugAttr = container.getAttribute('data-debug');
            setDebugMode(debugAttr === 'true');
        }

        // Mark data attributes as initialized
        setDataAttributesInitialized(true);
    }, []);

    // ---------------
    // Fetch Catalogs
    // ---------------
    // Wait for data attributes so we don't fire once with saleNid=null and again with the real one.
    useEffect(() => {
        if (!dataAttributesInitialized) return;
        if (!config.siteData) return;

        let cancelled = false;
        fetchCatalogs(config.siteData.backoffice_url_lang, saleNid)
            .then(data => {
                if (!cancelled) setCatalogs(data.data || []);
            })
            .catch(err => {
                if (!cancelled) {
                    console.error('Error fetching catalogs:', err);
                    setCatalogs([]);
                }
            });

        return () => { cancelled = true; };
    }, [dataAttributesInitialized, config.siteData, saleNid, fetchCatalogs]);

    // ---------------
    // Facet Toggling
    // ---------------
    // Effect for fetching data
    // Auto-submits for: AUTO_SUBMIT_SELECTS (soldStatus, favoritesOnly, sortField, itemsPerPage), facets, and pagination
    // TEXT_INPUT_FIELDS require manual search button click
    useEffect(() => {
        // Don't fetch until data attributes have been initialized
        if (!dataAttributesInitialized) return;

        getSaleResults();
    }, [dataAttributesInitialized, getSaleResults]);

    // Save viewMode to localStorage whenever it changes
    useEffect(() => {
        localStorage.setItem('sale_viewMode', viewMode);
    }, [viewMode]);

    // Save showAdvanced to localStorage whenever it changes
    useEffect(() => {
        localStorage.setItem('sale_showAdvanced', showAdvanced);
    }, [showAdvanced]);

    // Update URL when filters, facets, or page changes
    useEffect(() => {
        const params = new URLSearchParams();

        // Add page parameter if not on page 1
        if (currentPage > 1) {
            params.set('page', currentPage);
        }

        // Add facet filters to URL
        Object.entries(activeFacets).forEach(([fieldName, values]) => {
            if (values.length > 0) {
                params.set(`filter[${fieldName}][values]`, values.join(','));
                params.set(`filter[${fieldName}][operator]`, 'IN');
            }
        });

        // Add other filters if they have values
        if (filters.lotNumber) {
            params.set('filter[field_lot_number][value]', filters.lotNumber);
        }
        if (filters.searchText) {
            params.set('search', filters.searchText);
        }
        if (filters.lotNumberRange) {
            params.set('lotNumberRange', filters.lotNumberRange);
        }
        if (filters.soldStatus) {
            params.set('filter[field_sold_status][value]', filters.soldStatus);
        }
        if (filters.catalogName) {
            params.set('filter[field_catalog_ref][value]', filters.catalogName);
        }
        if (filters.catalogNumber) {
            params.set('filter[field_catalog_number][value]', filters.catalogNumber);
        }
        if (filters.sortField !== 'field_lot_number') {
            params.set('sort', filters.sortField);
        }
        if (filters.itemsPerPage !== 25) {
            params.set('range', filters.itemsPerPage);
        }

        const newUrl = params.toString()
            ? `${window.location.pathname}?${params.toString()}`
            : window.location.pathname;

        window.history.replaceState({}, '', newUrl);
    }, [filters, activeFacets, currentPage]);

    // Facet handling
    const toggleFacetValue = (fieldName, term) => {
        // If the term is already active, remove it. Otherwise add it.
        setActiveFacets(prev => {
            const oldValues = prev[fieldName] || [];
            const isActive = oldValues.includes(term.tid);
            const newValues = isActive
                ? oldValues.filter(v => v !== term.tid)
                : [...oldValues, term.tid];

            return {
                ...prev,
                [fieldName]: newValues,
            };
        });
        setCurrentPage(1);
        // Clicking a facet should trigger search and exit init state
        // On first facet click in global search, close advanced search and other facets
        const isFirstSubmit = !hasSubmitted && !saleNid;
        if (!hasSubmitted) {
            setHasSubmitted(true);
            if (isFirstSubmit) {
                setShowAdvanced(false);
                // Close all facets by clearing localStorage (unless user has customized them)
                const currentFacetState = localStorage.getItem('facet_accordion_state');
                const isDefaultState = currentFacetState === JSON.stringify([0, 1, 2, 3, 4, 5]);
                if (isDefaultState) {
                    localStorage.setItem('facet_accordion_state', JSON.stringify([]));
                }
            }
        }
    };

    // Form handling
    // Adapter so CircuitDropdown (which passes the value directly)
    // can reuse the event-based handleFilterChange.
    const handleDropdownChange = (name, value) => {
        handleFilterChange({ target: { name, value, type: 'select-one' } });
    };

    const handleFilterChange = (e) => {
        const { name, value, type } = e.target;

        // Convert itemsPerPage to number, keep others as strings
        const processedValue = name === 'itemsPerPage' ? parseInt(value, 10) : value;

        // Clear catalog errors when user types in catalog fields
        if (name === 'catalogName' || name === 'catalogNumber') {
            setCatalogErrors(prev => ({
                ...prev,
                [name === 'catalogName' ? 'name' : 'number']: false
            }));
        }

        // Auto-submit for specific select fields only
        // Exclude catalogName even though it's a select - it requires manual submit like text inputs
        if (type === 'select-one' && AUTO_SUBMIT_SELECTS.includes(name)) {
            // Update filters directly (triggers auto-submit)
            setFilters(prev => ({
                ...prev,
                [name]: processedValue
            }));

            setCurrentPage(1);
            // Auto-submit filters should exit init state and show results
            // On first auto-submit in global search, close advanced search and facets
            const isFirstSubmit = !hasSubmitted && !saleNid;
            if (!hasSubmitted) {
                setHasSubmitted(true);
                if (isFirstSubmit) {
                    setShowAdvanced(false);
                    // Close all facets by clearing localStorage (unless user has customized them)
                    const currentFacetState = localStorage.getItem('facet_accordion_state');
                    const isDefaultState = currentFacetState === JSON.stringify([0, 1, 2, 3, 4, 5]);
                    if (isDefaultState) {
                        localStorage.setItem('facet_accordion_state', JSON.stringify([]));
                    }
                }
            }
            // The getSaleResults will be triggered by the useEffect watching these filters
        } else if (TEXT_INPUT_FIELDS.includes(name)) {
            // For text inputs and catalogName select, only update inputValues (no auto-submit)
            setInputValues(prev => ({
                ...prev,
                [name]: processedValue
            }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        // Validate catalog filters - both must be filled or both must be empty
        const catalogNameFilled = !!inputValues.catalogName;
        const catalogNumberFilled = !!inputValues.catalogNumber;

        if (catalogNameFilled !== catalogNumberFilled) {
            setCatalogErrors({
                name: catalogNameFilled && !catalogNumberFilled ? false : !catalogNameFilled,
                number: catalogNumberFilled && !catalogNameFilled ? false : !catalogNumberFilled
            });
            return;
        }

        // Clear catalog errors if validation passes
        setCatalogErrors({ name: false, number: false });

        // Apply text input values to filters (triggers search)
        setFilters(prev => {
            const updates = TEXT_INPUT_FIELDS.reduce((acc, field) => {
                acc[field] = inputValues[field];
                return acc;
            }, {});
            return { ...prev, ...updates };
        });

        // On first submit in global search, close advanced search and facets
        const isFirstSubmit = !hasSubmitted && !saleNid;
        if (isFirstSubmit) {
            setShowAdvanced(false);
            // Close all facets by clearing localStorage (unless user has customized them)
            const currentFacetState = localStorage.getItem('facet_accordion_state');
            const isDefaultState = currentFacetState === JSON.stringify([0, 1, 2, 3, 4, 5]);
            if (isDefaultState) {
                localStorage.setItem('facet_accordion_state', JSON.stringify([]));
            }
        }

        setHasSubmitted(true);
        setCurrentPage(1);
        // getSaleResults will be triggered by the useEffect watching filters
    };

    const handleReset = () => {
        // Reset all filters to default values
        setFilters({
            lotNumber: '',
            searchText: '',
            soldStatus: '',
            favoritesOnly: '0',
            catalogName: '',
            catalogNumber: '',
            openingPriceRange: '',
            soldForRange: '',
            lotNumberRange: '',
            itemsPerPage: 25,
            sortField: 'field_lot_number'
        });
        // Reset input values as well
        setInputValues(
            TEXT_INPUT_FIELDS.reduce((acc, field) => {
                acc[field] = '';
                return acc;
            }, {})
        );
        // Clear all active facets
        setActiveFacets({});
        // Reset to page 1
        setCurrentPage(1);

        if (!saleNid) {
            // Global search: go back to init state
            // Reset submission state to show welcome message again
            setHasSubmitted(false);
            // Re-open advanced search when resetting
            setShowAdvanced(true);
            // Re-open all facets by setting localStorage
            localStorage.setItem('facet_accordion_state', JSON.stringify([0, 1, 2, 3, 4, 5]));
            setFacetResetTrigger(prev => prev + 1);
        } else {
            // Sale context: close facets and advanced search
            setShowAdvanced(false);
            // Close all facets by clearing localStorage
            localStorage.setItem('facet_accordion_state', JSON.stringify([]));
            setFacetResetTrigger(prev => prev + 1);
        }

        // Clear URL parameters (redirect to clean sale URL)
        window.history.replaceState({}, '', window.location.pathname);
    };

    // Decode HTML entities (e.g. "&amp;" → "&") in category labels.
    const decodeHtmlEntities = (str) => {
        if (!str || typeof str !== 'string') return str;
        if (typeof document === 'undefined') return str;
        const textarea = document.createElement('textarea');
        textarea.innerHTML = str;
        return textarea.value;
    };

    // Helper function to get category name from item
    const getCategoryName = (item) => {
        if (!item?.item_taxonomy?.field_category?.ancestors) return null;
        const ancestors = item.item_taxonomy.field_category.ancestors;
        const lastCategory = ancestors[ancestors.length - 1];
        let raw = lastCategory?.field_tree_label?.[i18n.language]?.[0]?.value || lastCategory?.name || null;
        // field_tree_label values arrive as "264000 | Europa → Frankreich" —
        // the numeric backoffice id prefix is noise for bidders, keep the tail.
        if (raw && raw.includes('|')) {
            raw = raw.substring(raw.indexOf('|') + 1).trim();
        }
        return decodeHtmlEntities(raw);
    };

    // Process items to insert category headers where category changes
    const processItemsWithCategories = (items) => {
        if (!items || items.length === 0) return [];

        const processed = [];
        let lastCategory = null;

        items.forEach((item, index) => {
            const currentCategory = getCategoryName(item);

            // If category changed or first item, add category header
            if (currentCategory && currentCategory !== lastCategory) {
                processed.push({
                    type: 'category-header',
                    category: currentCategory,
                    key: `category-${index}-${currentCategory}`
                });
                lastCategory = currentCategory;
            }

            // Add the item
            processed.push({
                type: 'item',
                item: item,
                key: item.uuid
            });
        });

        return processed;
    };

    // Reusable pagination renderer
    const renderPagination = (position = 'bottom') => {
        // Check if we have any actual search criteria
        const hasSearchCriteria = checkHasSearchCriteria(filters, activeFacets, saleNid);

        // Don't show pagination if in init mode (no criteria AND not submitted) or itemsPerPage is 0
        if ((!hasSearchCriteria && !hasSubmitted) || filters.itemsPerPage === 0) return null;

        if (!results.data || results.data.length === 0) return null;

        const totalPages = Math.ceil(results.count / filters.itemsPerPage);
        if (totalPages <= 1) return null;

        const handlePageChange = (page) => {
            setCurrentPage(page);
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };

        // Generate page numbers to display
        const getPageNumbers = () => {
            const pages = [];
            const maxVisible = 7; // Show max 7 page numbers

            if (totalPages <= maxVisible) {
                // Show all pages if total is small
                for (let i = 1; i <= totalPages; i++) {
                    pages.push(i);
                }
            } else {
                // Always show first page
                pages.push(1);

                // Calculate range around current page
                let start = Math.max(2, currentPage - 1);
                let end = Math.min(totalPages - 1, currentPage + 1);

                // Adjust if we're near the start
                if (currentPage <= 3) {
                    end = 5;
                }

                // Adjust if we're near the end
                if (currentPage >= totalPages - 2) {
                    start = totalPages - 4;
                }

                // Add ellipsis if needed
                if (start > 2) {
                    pages.push('...');
                }

                // Add middle pages
                for (let i = start; i <= end; i++) {
                    pages.push(i);
                }

                // Add ellipsis if needed
                if (end < totalPages - 1) {
                    pages.push('...');
                }

                // Always show last page
                pages.push(totalPages);
            }

            return pages;
        };

        return (
            <nav className={`sale-pagination sale-pagination--${position}`} aria-label="Pagination">
                <button
                    type="button"
                    className="favorites-pagination__btn"
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                >
                    {t('sale.previous', { defaultValue: 'Previous' })}
                </button>

                {getPageNumbers().map((page, index) => {
                    if (page === '...') {
                        return (
                            <span key={`ellipsis-${position}-${index}`} className="sale-pagination__ellipsis">
                                …
                            </span>
                        );
                    }

                    return (
                        <button
                            key={`page-${position}-${page}`}
                            type="button"
                            className={`favorites-pagination__btn favorites-pagination__btn--num${currentPage === page ? ' is-active' : ''}`}
                            onClick={() => handlePageChange(page)}
                            aria-current={currentPage === page ? 'page' : undefined}
                        >
                            {page}
                        </button>
                    );
                })}

                <button
                    type="button"
                    className="favorites-pagination__btn"
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                >
                    {t('sale.next', { defaultValue: 'Next' })}
                </button>
            </nav>
        );
    };

    if (isLoading && !results) {
        return (
            <div className="sale-page sale-page--loading">
                <Spinner color="blue.500" size="xl" thickness="4px"/>
            </div>
        );
    }

    return (
        <div className="sale-page">
            {/* ?debug=1 data-source panel (single instance for the page). */}
            <DataSourceDebugPanel />
            {/* Debug Info - Only shown when data-debug="true" */}
            {debugMode && (
                <Box
                    bg="yellow.100"
                    border="2px solid"
                    borderColor="yellow.500"
                    p={3}
                    mb={4}
                    borderRadius="md"
                    fontFamily="monospace"
                >
                    <Text fontWeight="bold" mb={2}>Debug Info:</Text>
                    <Text>hasSubmitted: {String(hasSubmitted)}</Text>
                    <Text>saleNid: {saleNid || 'null'}</Text>
                    <Text>hasSearchCriteria: {String(checkHasSearchCriteria(filters, activeFacets, saleNid))}</Text>
                    <Text>debugMode: {String(debugMode)}</Text>
                </Box>
            )}

            {/* Featured Items - Only show when data-show-featured="true" */}
            {showFeatured && saleNid && (
                <>
                    <div
                        id="ca-featured-items"
                        data-sale-nid={saleNid}
                        data-item-display="lot-number"
                    />
                    <FeaturedItems />
                </>
            )}

            {/* Sale Info - Only show when in a sale */}
            {saleNid && <SaleInfo saleNid={saleNid} />}

            {/* Init State Message - Show helpful message until form is submitted */}
            {!hasSubmitted && (
                <div className="cream-note cream-note--warning sale-page__intro" role="status">
                    <div>
                        <strong>{t('sale.searchGuideTitle', 'Search Our Collection')}</strong>
                        <p style={{ margin: '4px 0 0' }}>
                            {t('sale.searchGuideMessage', 'Use the search filters and facets below to find items. Select categories, adjust filters, or enter keywords to begin your search.')}
                        </p>
                    </div>
                </div>
            )}

            {/* 2. Search Form (Filters) */}
            <form onSubmit={handleSubmit}>
                {/* Search Fields */}
                <Flex wrap="wrap" gap={4} mb={4} alignItems="flex-end">
                    <Box>
                        <Text mb={0}>{t('sale.lotNumber')}</Text>
                        <Input
                            type="number"
                            name="lotNumber"
                            value={inputValues.lotNumber}
                            onChange={handleFilterChange}
                            placeholder={t('sale.enterLotNumber')}
                            width="120px"
                        />
                    </Box>
                    <Box>
                        <Text mb={0}>{t('sale.searchText')}</Text>
                        <Input
                            name="searchText"
                            value={inputValues.searchText}
                            onChange={handleFilterChange}
                            placeholder={t('sale.enterSearchText')}
                            width="180px"
                        />
                    </Box>

                    {/* Advanced Filters - Shown inline when toggled */}
                    {showAdvanced && (
                        <>
                            <Box>
                                <Text mb={0}>{t('sale.soldStatus')}</Text>
                                <CircuitDropdown
                                    value={filters.soldStatus || ''}
                                    ariaLabel={t('sale.soldStatus')}
                                    variant="compact"
                                    onChange={(v) => handleDropdownChange('soldStatus', v)}
                                    options={[
                                        { value: '',       label: t('sale.any') },
                                        { value: 'sold',   label: t('sale.sold') },
                                        { value: 'unsold', label: t('sale.unsold') },
                                    ]}
                                />
                            </Box>

                            {/* My Favorites - Only show for logged-in users */}
                            {config.userData?.bo_access_token && (
                                <Box>
                                    <Text mb={0}>{t('sale.myFavorites', 'My Favorites')}</Text>
                                    <CircuitDropdown
                                        value={filters.favoritesOnly || '0'}
                                        ariaLabel={t('sale.myFavorites', 'My Favorites')}
                                        variant="compact"
                                        onChange={(v) => handleDropdownChange('favoritesOnly', v)}
                                        options={[
                                            { value: '0', label: t('sale.all', 'All') },
                                            { value: '1', label: t('sale.favorites', 'Favorites') },
                                        ]}
                                    />
                                </Box>
                            )}

                            <Box>
                                <Text mb={0}>{t('sale.openingPrice', 'Opening Price')}</Text>
                                <Input
                                    type="text"
                                    name="openingPriceRange"
                                    value={inputValues.openingPriceRange}
                                    onChange={handleFilterChange}
                                    placeholder={t('sale.rangePlaceholder', '1-100')}
                                    width="140px"
                                />
                            </Box>

                            <Box>
                                <Text mb={0}>{t('sale.soldFor', 'Sold For')}</Text>
                                <Input
                                    type="text"
                                    name="soldForRange"
                                    value={inputValues.soldForRange}
                                    onChange={handleFilterChange}
                                    placeholder={t('sale.rangePlaceholder', '1-100')}
                                    width="140px"
                                />
                            </Box>

                            <Box>
                                <Flex alignItems="center" gap={1} mb={0}>
                                    <Text mb={0}>{t('sale.catalogName', 'Catalog Name')}</Text>
                                    <Tooltip
                                        label={t('sale.catalogFilterHelp', 'Both Catalog Name and Number must be filled together')}
                                        placement="top"
                                    >
                                        <QuestionOutlineIcon w={3} h={3} color="gray.500" />
                                    </Tooltip>
                                </Flex>
                                <CircuitDropdown
                                    value={inputValues.catalogName || ''}
                                    ariaLabel={t('sale.catalogName', 'Catalog Name')}
                                    variant="compact"
                                    placeholder={t('sale.catalogName', 'Catalog Name')}
                                    onChange={(v) => handleDropdownChange('catalogName', v)}
                                    options={[
                                        { value: '', label: t('sale.any') || 'Any' },
                                        ...catalogs.map((catalog) => ({
                                            value: catalog.label,
                                            label: catalog.label,
                                        })),
                                    ]}
                                />
                                {catalogErrors.name && (
                                    <Text fontSize="sm" color="red.500" mt={1}>
                                        {t('sale.catalogNameRequired', 'Catalog Name is required')}
                                    </Text>
                                )}
                            </Box>

                            <Box>
                                <Text mb={0}>{t('sale.catalogNumber', 'Catalog Number')}</Text>
                                <Input
                                    type="text"
                                    name="catalogNumber"
                                    value={inputValues.catalogNumber}
                                    onChange={handleFilterChange}
                                    placeholder={t('sale.enterCatalogNumber', 'e.g., 123A')}
                                    width="140px"
                                    isInvalid={catalogErrors.number}
                                    borderColor={catalogErrors.number ? 'red.500' : undefined}
                                />
                                {catalogErrors.number && (
                                    <Text fontSize="sm" color="red.500" mt={1}>
                                        {t('sale.catalogNumberRequired', 'Catalog Number is required')}
                                    </Text>
                                )}
                            </Box>

                            <Box>
                                <Text mb={0}>{t('sale.sortBy', 'Sort By')}</Text>
                                <CircuitDropdown
                                    value={filters.sortField || 'field_lot_number'}
                                    ariaLabel={t('sale.sortBy', 'Sort By')}
                                    variant="compact"
                                    onChange={(v) => handleDropdownChange('sortField', v)}
                                    options={[
                                        { value: 'field_lot_number',         label: t('sale.sortLotNumber', 'Lot Number') },
                                        { value: '-field_opening_price',     label: t('sale.sortOpeningPriceHighLow', 'Opening Price: High to Low') },
                                        { value: 'field_opening_price',      label: t('sale.sortOpeningPriceLowHigh', 'Opening Price: Low to High') },
                                        { value: '-field_sold_for_amount',   label: t('sale.sortSoldForHighLow', 'Sold For: High to Low') },
                                        { value: 'field_sold_for_amount',    label: t('sale.sortSoldForLowHigh', 'Sold For: Low to High') },
                                    ]}
                                />
                            </Box>

                        </>
                    )}

                    <Box>
                        <Text mb={0}>{t('sale.itemsPerPage', 'Items Per Page')}</Text>
                        <CircuitDropdown
                            value={String(filters.itemsPerPage)}
                            ariaLabel={t('sale.itemsPerPage', 'Items Per Page')}
                            variant="compact"
                            onChange={(v) => handleDropdownChange('itemsPerPage', v)}
                            options={[
                                { value: '25',  label: '25' },
                                { value: '50',  label: '50' },
                                { value: '100', label: '100' },
                                { value: '200', label: '200' },
                            ]}
                        />
                    </Box>

                    {/* Search and Reset Buttons - Always visible */}
                    <Flex gap={2}>
                        <button type="submit" className="btn-primary-action">
                            {t('sale.search')}
                        </button>
                        <button type="button" className="btn-secondary-action" onClick={handleReset}>
                            {t('sale.reset')}
                        </button>
                    </Flex>

                    {/* Show Advanced Filters Button - Pulled to right */}
                    <Box ml="auto">
                        <button
                            type="button"
                            className="sale-page__advanced-toggle"
                            onClick={() => setShowAdvanced(!showAdvanced)}
                        >
                            {showAdvanced ? `− ${t('sale.hideAdvanced')}` : `+ ${t('sale.showAdvanced')}`}
                        </button>
                    </Box>
                </Flex>
            </form>

            {/* Status Messages */}
            {successMessage && (
                <div className="cream-note cream-note--success" role="status" style={{ margin: '16px 0' }}>
                    {successMessage}
                </div>
            )}

            {error && (
                <div className="cream-note cream-note--error" role="alert" style={{ margin: '16px 0' }}>
                    <strong>{t('sale.error')}</strong>{error}
                </div>
            )}

            {/* Loading State */}
            {isLoading ? (
                <Flex justifyContent="center" mt={8}>
                    <Spinner size="lg" />
                </Flex>
            ) : (
                <>
                    {/* 4. Facets */}
                    {results && (
                        <>
                            <Facets
                                results={results}
                                activeFacets={activeFacets}
                                toggleFacetValue={toggleFacetValue}
                                inSale={!!saleNid}
                                openAll={!checkHasSearchCriteria(filters, activeFacets, saleNid)}
                                resetTrigger={facetResetTrigger}
                            />

                            {/* 5. Results Count and Display Selector - Hide until submitted */}
                            {hasSubmitted && (
                                <div className="sale-toolbar">
                                    <p className="sale-toolbar__count">
                                        {t('sale.resultsFound', { count: results?.count ?? 0 })}
                                        {(results?.count ?? 0) === 0 && (
                                            <button
                                                type="button"
                                                className="btn-secondary-action sale-toolbar__reset"
                                                onClick={handleReset}
                                            >
                                                {t('sale.resetSearchFilters', { defaultValue: 'Reset search filters' })}
                                            </button>
                                        )}
                                    </p>
                                    <div className="view-toggle" role="group" aria-label="Display mode">
                                        <button
                                            type="button"
                                            className={`view-toggle__btn${viewMode === 'list' ? ' is-active' : ''}`}
                                            onClick={() => setViewMode('list')}
                                        >
                                            <FaThList /> {t('sale.listView', { defaultValue: 'List' })}
                                        </button>
                                        <button
                                            type="button"
                                            className={`view-toggle__btn${viewMode === 'grid' ? ' is-active' : ''}`}
                                            onClick={() => setViewMode('grid')}
                                        >
                                            <FaTh /> {t('sale.gridView', { defaultValue: 'Grid' })}
                                        </button>
                                    </div>
                                </div>
                            )}

                            {/* Pagination - Top */}
                            {renderPagination('top')}

                            {/* Items Display - Hide until submitted */}
                            {hasSubmitted && (
                                <Box className="results">
                                {results.data && results.data.length > 0 ? (
                                    (() => {
                                        const processedItems = processItemsWithCategories(results.data);

                                        return viewMode === 'grid' ? (
                                            <Box className="sale-items-grid">
                                                {processedItems.map((entry) => {
                                                    if (entry.type === 'category-header') {
                                                        return (
                                                            <h3
                                                                key={entry.key}
                                                                className="category-header category-header--grid"
                                                            >
                                                                {entry.category}
                                                            </h3>
                                                        );
                                                    } else {
                                                        return (
                                                            <ItemPage
                                                                key={entry.key}
                                                                itemObject={entry.item}
                                                                displayMode="grid"
                                                                inSale={!!saleNid}
                                                            />
                                                        );
                                                    }
                                                })}
                                            </Box>
                                        ) : (
                                            <Box>
                                                {processedItems.map((entry) => {
                                                    if (entry.type === 'category-header') {
                                                        return (
                                                            <h3
                                                                key={entry.key}
                                                                className="category-header"
                                                            >
                                                                {entry.category}
                                                            </h3>
                                                        );
                                                    } else {
                                                        return (
                                                            <ItemPage
                                                                key={entry.key}
                                                                itemObject={entry.item}
                                                                displayMode="teaser"
                                                                inSale={!!saleNid}
                                                            />
                                                        );
                                                    }
                                                })}
                                            </Box>
                                        );
                                    })()
                                ) : (
                                    <Box textAlign="center" py={10}>
                                        <Text fontSize="xl" color="gray.600">
                                            {t('sale.noResults')}
                                        </Text>
                                    </Box>
                                )}

                                {/* Pagination - Bottom */}
                                {renderPagination('bottom')}
                            </Box>
                            )}
                        </>
                    )}
                </>
            )}
        </div>
    );
};

export default SalePage;