/**
 * `?debug=1` data-source panel — a floating box listing where every item /
 * sale fetch of this page load was served from:
 *
 *   MEM   in-memory cache of this page load
 *   LS    persisted localStorage cache (dc:*)
 *   NET   real request — with HTTP status, the edge cache verdict
 *         (CF-Cache-Status / Age / X-Cache) and the backend's own cache
 *         verdict (`_debug.backend_cache`, e.g. items-json Drupal cache
 *         hit/miss).
 *
 * Renders nothing without the debug flag. Feeds off utils/dataSourceLog.
 */
import React, { useEffect, useState } from 'react';
import { isDebugRequested } from '../utils/debugParam';
import { getDataSourceLog, subscribeDataSources } from '../utils/dataSourceLog';

const SOURCE_BADGE = {
  memory: { label: 'MEM', color: '#8a6d1a', bg: 'rgba(212,175,55,0.18)' },
  localStorage: { label: 'LS', color: '#1a5f8a', bg: 'rgba(55,140,212,0.15)' },
  network: { label: 'NET', color: '#1a7a3a', bg: 'rgba(60,190,110,0.15)' },
};

const time = (at) => new Date(at).toLocaleTimeString([], { hour12: false });

const netDetails = (entry) => {
  const parts = [];
  if (entry.status) parts.push(`HTTP ${entry.status}`);
  if (entry.cfCacheStatus) parts.push(`CF ${entry.cfCacheStatus}`);
  if (entry.age) parts.push(`age ${entry.age}s`);
  if (entry.xCache) parts.push(entry.xCache);
  if (entry.backend?.backend_cache) parts.push(`backend ${entry.backend.backend_cache}`);
  return parts.join(' · ');
};

const DataSourceDebugPanel = () => {
  const [log, setLog] = useState(() => [...getDataSourceLog()]);
  const [collapsed, setCollapsed] = useState(false);

  useEffect(() => {
    if (!isDebugRequested()) return undefined;
    return subscribeDataSources((entries) => setLog([...entries]));
  }, []);

  if (!isDebugRequested()) return null;

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 10,
        left: 10,
        zIndex: 99999,
        maxWidth: 420,
        maxHeight: collapsed ? 32 : 300,
        overflow: 'hidden',
        background: 'rgba(19,19,19,0.95)',
        color: '#d6f5d6',
        borderRadius: 8,
        fontFamily: 'monospace',
        fontSize: 11,
        lineHeight: 1.5,
        boxShadow: '0 4px 14px rgba(0,0,0,0.4)',
      }}
    >
      <div
        onClick={() => setCollapsed((value) => !value)}
        style={{
          padding: '6px 10px',
          cursor: 'pointer',
          fontWeight: 700,
          color: '#e9c349',
          display: 'flex',
          justifyContent: 'space-between',
          gap: 12,
        }}
      >
        <span>DATA SOURCES ({log.length})</span>
        <span>{collapsed ? '▲' : '▼'}</span>
      </div>
      {!collapsed && (
        <div style={{ padding: '0 10px 8px', maxHeight: 260, overflowY: 'auto' }}>
          {log.length === 0 && <div>— no fetches yet —</div>}
          {[...log].reverse().map((entry, index) => {
            const badge = SOURCE_BADGE[entry.source] || SOURCE_BADGE.network;
            return (
              <div key={`${entry.at}-${index}`} style={{ marginBottom: 3 }}>
                <span style={{ color: '#74777d' }}>{time(entry.at)} </span>
                <span
                  style={{
                    color: badge.color,
                    background: badge.bg,
                    borderRadius: 4,
                    padding: '0 5px',
                    fontWeight: 700,
                  }}
                >
                  {badge.label}
                </span>
                <span style={{ color: '#e9c349' }}> {entry.endpoint}</span>
                <span style={{ color: '#a5a9b0' }}> {String(entry.key).slice(0, 60)}</span>
                {entry.source === 'network' && (
                  <div style={{ paddingLeft: 58, color: '#88d982' }}>{netDetails(entry)}</div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default DataSourceDebugPanel;
