/**
 * Shared utility for loading Accept.js across components
 * Ensures only one instance is loaded and provides consistent behavior
 */

let acceptJsPromise = null;
let isLoaded = false;

/**
 * Load Accept.js script dynamically based on environment
 * @param {Object} config - Configuration object containing environment info
 * @returns {Promise<boolean>} - Promise that resolves when Accept.js is loaded and ready
 */
export const loadAcceptJs = (config) => {
  // Return existing promise if already loading or loaded
  if (acceptJsPromise) {
    return acceptJsPromise;
  }

  // Check if Accept.js is already loaded and functional
  if (isLoaded && window.Accept && typeof window.Accept.dispatchData === 'function') {
    return Promise.resolve(true);
  }

  // Create new loading promise
  acceptJsPromise = new Promise((resolve, reject) => {
    // Check if Accept.js is already loaded
    if (window.Accept && typeof window.Accept.dispatchData === 'function') {
      isLoaded = true;
      resolve(true);
      return;
    }

    // Check if script is already being loaded
    const existingScript = document.querySelector('script[src*="Accept.js"]');
    if (existingScript) {
      existingScript.onload = () => {
        setTimeout(() => {
          if (window.Accept && typeof window.Accept.dispatchData === 'function') {
            isLoaded = true;
            resolve(true);
          } else {
            reject(new Error('Accept.js loaded but functions not available'));
          }
        }, 100);
      };
      existingScript.onerror = () => reject(new Error('Failed to load Accept.js'));
      return;
    }

    // Create and load new script
    const script = document.createElement('script');
    
    // Determine URL based on environment
    const isLive = config.env === 'live';
    script.src = isLive ? 'https://js.authorize.net/v1/Accept.js' : 'https://jstest.authorize.net/v1/Accept.js';
    script.async = true;
    
    script.onload = () => {
      // Give Accept.js a moment to initialize
      setTimeout(() => {
        if (window.Accept && typeof window.Accept.dispatchData === 'function') {
          isLoaded = true;
          console.log('Accept.js loaded successfully from:', script.src);
          resolve(true);
        } else {
          reject(new Error('Accept.js loaded but functions not available'));
        }
      }, 100);
    };
    
    script.onerror = () => {
      reject(new Error('Failed to load Accept.js'));
    };
    
    document.head.appendChild(script);
  });

  return acceptJsPromise;
};

/**
 * Check if Accept.js is already loaded and ready
 * @returns {boolean}
 */
export const isAcceptJsLoaded = () => {
  return isLoaded && window.Accept && typeof window.Accept.dispatchData === 'function';
};

/**
 * Reset the loader state (useful for testing or if you need to reload)
 */
export const resetAcceptJsLoader = () => {
  acceptJsPromise = null;
  isLoaded = false;
};