import React, { useContext } from 'react';
import { ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';
import { Link as ChakraLink } from '@chakra-ui/react';

/**
 * Format a URL with language prefix based on site's language configuration
 * @param {string} basePath - The base path (e.g., 'item', 'sale', 'price-realizes', 'login')
 * @param {string} [id] - Optional identifier (UUID, ID, etc.)
 * @param {string} [queryParams] - Optional query parameters (e.g., '?redirect=/page')
 * @param {object} i18n - i18n object from useTranslation
 * @param {Array} siteLanguages - Array of language codes supported by the site
 * @returns {string} Properly formatted URL
 */
export const formatLanguageUrl = (basePath, id, queryParams, i18n, siteLanguages) => {
  let url;

  // If there's exactly one language, don't include language prefix
  if (siteLanguages && siteLanguages.length === 1) {
    url = id ? `/${basePath}/${id}` : `/${basePath}`;
  } else {
    // Convert zh to zh-hans for drupal urls, so for login and register and
    const languageForServer = i18n.language === 'zh' ? 'zh-hans' : i18n.language;

    // When multiple languages are available, include the language prefix
    url = id ? `/${languageForServer}/${basePath}/${id}` : `/${languageForServer}/${basePath}`;
  }

  // Append query parameters if provided
  if (queryParams) {
    url += queryParams;
  }

  return url;
};

/**
 * Chakra UI Link component with language-aware URL formatting
 * Flexible component that can link to any URL type (item, sale, price-realizes, etc.)
 * @param {string} basePath - The base path after language (e.g., 'item', 'sale', 'price-realizes', 'login') or absolute URL
 * @param {string} [id] - Optional identifier (UUID, ID, etc.)
 * @param {string} [queryParams] - Optional query parameters (e.g., '?redirect=/page')
 * @param {ReactNode} children - Link content
 */
export const LinkLanguage = ({ basePath, id, queryParams, children, ...props }) => {
  const config = useContext(ConfigContext);
  const { i18n } = useTranslation();

  // Check if basePath is an absolute URL
  const isAbsoluteUrl = basePath && (basePath.startsWith('http://') || basePath.startsWith('https://'));

  // If it's an absolute URL, use it directly
  if (isAbsoluteUrl) {
    return (
      <ChakraLink href={basePath} {...props}>
        {children}
      </ChakraLink>
    );
  }

  // Extract site languages from config
  const siteLanguages = config.siteData?.languages || [];

  // Generate the appropriate URL
  const url = formatLanguageUrl(basePath, id, queryParams, i18n, siteLanguages);

  return (
    <ChakraLink href={url} {...props}>
      {children}
    </ChakraLink>
  );
};

/**
 * Chakra UI Link Item component with language-aware URL formatting
 */
export const ItemLinkChakra = ({ itemUuid, children, ...props }) => {
  return (
    <LinkLanguage basePath="item" id={itemUuid} {...props}>
      {children}
    </LinkLanguage>
  );
};


/**
 * Chakra UI Link Sale component with language-aware URL formatting
 */
export const SaleLinkChakra = ({ saleId, children, ...props }) => {
  return (
    <LinkLanguage basePath="sale" id={saleId} {...props}>
      {children}
    </LinkLanguage>
  );
};


/**
 * Chakra UI Link Sale Live component with language-aware URL formatting
 */
export const SaleLinkLinkChakra = ({ saleUuid, children, ...props }) => {
  const config = useContext(ConfigContext);
  if (config.siteData?.wordpress_url) {
    return (
      <ChakraLink href={`${config.siteData.wordpress_url}/live/#/sale/${saleUuid}`} {...props}>
        {children}
      </ChakraLink>
    );
  }
  return (
    <ChakraLink href={`/live/#/sale/${saleUuid}`} {...props}>
      {children}
    </ChakraLink>
  );
};


