import React from 'react';
import { useTranslation } from 'react-i18next';
import { Package, Truck, MapPin, ExternalLink, Check } from 'lucide-react';

// Lifecycle order of the two statuses we surface. Index drives the
// timeline: any stage at or before the current status is "reached",
// the last reached one is "current".
const STATUS_ORDER = ['sent_via_post_mail', 'received'];

const formatDate = (value) => {
  if (!value) return null;
  return new Date(value).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
};

const ShipmentDetails = ({ shipments = [], currency }) => {
  const { t } = useTranslation();

  if (!shipments.length) {
    return (
      <div className="shipment-details">
        <p className="shipment-details__empty">{t('billing.noShipmentInfo')}</p>
      </div>
    );
  }

  // USD ships in pounds; every other currency uses kilograms.
  const usesLbs = currency === 'USD';

  return (
    <div className="shipment-details">
      <h4 className="shipment-details__title">{t('billing.shipmentDetails')}</h4>

      {shipments.map((shipment, idx) => {
        const currentIndex = STATUS_ORDER.indexOf(shipment.delivery_status);

        const stages = [
          {
            key: 'sent_via_post_mail',
            label: t('billing.deliveryStatus.sent_via_post_mail'),
            dateLabel: t('billing.shippedOn'),
            date: shipment.pickup_date,
            icon: Truck,
          },
          {
            key: 'received',
            label: t('billing.deliveryStatus.received'),
            // Delivered if we have a date, otherwise the carrier estimate.
            dateLabel: shipment.delivery_date ? t('billing.deliveredOn') : t('billing.estimatedDelivery'),
            date: shipment.delivery_date || shipment.tracking?.estimated_delivery_date || null,
            icon: MapPin,
          },
        ];

        const weight = usesLbs ? shipment.weight_lbs : shipment.weight;
        const weightUnit = usesLbs ? 'lbs' : 'kg';
        const trackingNumber = shipment.tracking?.tracking_number || shipment.tracking_number;
        const trackingUrl = shipment.tracking?.tracking_url;

        return (
          <div className="shipment-card" key={shipment.id || idx}>
            {/* Vertical timeline */}
            <ol className="shipment-timeline">
              {stages.map((stage, sIdx) => {
                const reached = currentIndex >= sIdx && currentIndex !== -1;
                const isCurrent = currentIndex === sIdx;
                const StageIcon = stage.icon;
                const stateClass = reached
                  ? (isCurrent ? 'is-current' : 'is-done')
                  : 'is-pending';

                return (
                  <li className={`shipment-stage ${stateClass}`} key={stage.key}>
                    <span className="shipment-stage__marker" aria-hidden="true">
                      {reached && !isCurrent ? <Check size={12} /> : <StageIcon size={13} />}
                    </span>
                    <div className="shipment-stage__body">
                      <span className="shipment-stage__label">{stage.label}</span>
                      {stage.date && (
                        <span className="shipment-stage__date">
                          {stage.dateLabel}: {formatDate(stage.date)}
                        </span>
                      )}
                    </div>
                  </li>
                );
              })}
            </ol>

            {/* Shipment meta */}
            <dl className="shipment-meta">
              {(shipment.carrier_name || shipment.shipping_service_label) && (
                <div className="shipment-meta__row">
                  <dt><Package size={13} aria-hidden="true" /> {t('billing.carrier')}</dt>
                  <dd>
                    {shipment.carrier_name}
                    {shipment.shipping_service_label && (
                      <span className="shipment-meta__sub"> · {shipment.shipping_service_label}</span>
                    )}
                  </dd>
                </div>
              )}

              {weight && Number(weight) > 0 && (
                <div className="shipment-meta__row">
                  <dt>{t('billing.weight')}</dt>
                  <dd className="shipment-meta__num">{weight} {weightUnit}</dd>
                </div>
              )}

              {trackingNumber && (
                <div className="shipment-meta__row">
                  <dt>{t('billing.trackingNumber')}</dt>
                  <dd>
                    {trackingUrl ? (
                      <a
                        className="shipment-track-link"
                        href={trackingUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <span className="shipment-meta__num">{trackingNumber}</span>
                        <ExternalLink size={12} aria-hidden="true" />
                      </a>
                    ) : (
                      <span className="shipment-meta__num">{trackingNumber}</span>
                    )}
                  </dd>
                </div>
              )}
            </dl>
          </div>
        );
      })}
    </div>
  );
};

export default ShipmentDetails;
